package com.nibtracker;

import com.google.gson.JsonObject;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Turns game chat lines (tags already removed) into Nib Tracker events.
 * Returns the event's type and data, or null if the line means nothing to us.
 * Kept free of RuneLite types so it can be unit tested.
 */
final class ChatParser
{
	static final class Parsed
	{
		final String type;
		final JsonObject data;

		Parsed(String type, JsonObject data)
		{
			this.type = type;
			this.data = data;
		}
	}

	private static final Pattern KC = Pattern.compile(
		"^Your (?:completed |subdued )?(.+?) (?:kill |chest |completion |success |harvest )?count is: ?([0-9,]+)\\.?$");
	private static final Pattern CLOG = Pattern.compile("^New item added to your collection log: (.+?)\\.?$");
	private static final Pattern CA = Pattern.compile(
		"^Congratulations, you've completed an? (easy|medium|hard|elite|master|grandmaster) combat task: (.+?)(?: \\(\\d+ points?\\))?\\.?$",
		Pattern.CASE_INSENSITIVE);
	private static final Pattern QUEST = Pattern.compile("^Congratulations, you've completed a quest: (.+?)\\.?$");
	private static final Pattern LEAGUE_TASK = Pattern.compile(
		"^Congratulations, you've completed an? (easy|medium|hard|elite|master) task: (.+?)\\.?$", Pattern.CASE_INSENSITIVE);
	private static final Pattern DIARY_TASK = Pattern.compile(
		"^Well done! You have completed an? (easy|medium|hard|elite) task in the (.+?) area\\..*$", Pattern.CASE_INSENSITIVE);
	private static final Pattern DIARY_DONE = Pattern.compile(
		"^Congratulations! You have completed all of the (easy|medium|hard|elite) tasks in the (.+?) area\\..*$", Pattern.CASE_INSENSITIVE);
	private static final Pattern SLAYER_DONE = Pattern.compile(
		"^You've completed ([0-9,]+) tasks?(?: and received ([0-9,]+) points?, giving you a total of ([0-9,]+))?.*$");
	private static final Pattern CLUE = Pattern.compile(
		"^You have completed ([0-9,]+) (beginner|easy|medium|hard|elite|master) Treasure Trails?\\.?$", Pattern.CASE_INSENSITIVE);
	/* "Fight duration: 1:23.40. Personal best: 1:10.00", "Challenge duration: 25:01 (new personal best)" and the like.
	   The kill count line comes just before, so the web app pairs the two by time. */
	private static final String TIME = "([0-9]+(?::[0-9]{2})+(?:\\.[0-9]{1,2})?)";
	private static final Pattern BOSS_TIME = Pattern.compile(
		"^(Fight|Challenge|Corrupted challenge|Total completion|Theatre of Blood completion|Tombs of Amascut completion|Delve level: [0-9+]+ duration|Duration)"
			+ "(?: duration| time)?: " + TIME + "\\.?(?: ?\\((new personal best)\\))?(?:\\.? ?Personal best: " + TIME + ")?.*$",
		Pattern.CASE_INSENSITIVE);

	private ChatParser()
	{
	}

	static Parsed parse(String msg)
	{
		if (msg == null || msg.isEmpty())
		{
			return null;
		}

		Matcher m = KC.matcher(msg);
		if (m.matches())
		{
			JsonObject d = new JsonObject();
			d.addProperty("boss", m.group(1));
			d.addProperty("count", Integer.parseInt(m.group(2).replace(",", "")));
			return new Parsed("kc", d);
		}

		m = CLOG.matcher(msg);
		if (m.matches())
		{
			JsonObject d = new JsonObject();
			d.addProperty("item", m.group(1));
			return new Parsed("clog_new", d);
		}

		if (msg.startsWith("You have a funny feeling like you") || msg.startsWith("You feel something weird sneaking into your backpack"))
		{
			JsonObject d = new JsonObject();
			d.addProperty("duplicate", msg.contains("would have been followed"));
			d.addProperty("backpack", msg.contains("backpack"));
			return new Parsed("pet", d);
		}

		m = CA.matcher(msg);
		if (m.matches())
		{
			JsonObject d = new JsonObject();
			d.addProperty("tier", m.group(1).toLowerCase());
			d.addProperty("task", m.group(2));
			return new Parsed("ca_done", d);
		}

		m = QUEST.matcher(msg);
		if (m.matches())
		{
			JsonObject d = new JsonObject();
			d.addProperty("quest", m.group(1));
			return new Parsed("quest_done", d);
		}

		m = LEAGUE_TASK.matcher(msg);
		if (m.matches())
		{
			JsonObject d = new JsonObject();
			d.addProperty("tier", m.group(1).toLowerCase());
			d.addProperty("task", m.group(2));
			return new Parsed("league_task", d);
		}

		m = DIARY_TASK.matcher(msg);
		if (m.matches())
		{
			JsonObject d = new JsonObject();
			d.addProperty("tier", m.group(1).toLowerCase());
			d.addProperty("region", m.group(2));
			return new Parsed("diary_task", d);
		}

		m = DIARY_DONE.matcher(msg);
		if (m.matches())
		{
			JsonObject d = new JsonObject();
			d.addProperty("tier", m.group(1).toLowerCase());
			d.addProperty("region", m.group(2));
			return new Parsed("diary_done", d);
		}

		m = SLAYER_DONE.matcher(msg);
		if (m.matches())
		{
			JsonObject d = new JsonObject();
			d.addProperty("streak", Integer.parseInt(m.group(1).replace(",", "")));
			if (m.group(2) != null)
			{
				d.addProperty("points", Integer.parseInt(m.group(2).replace(",", "")));
				d.addProperty("total", Integer.parseInt(m.group(3).replace(",", "")));
			}
			return new Parsed("slayer_task_done", d);
		}

		m = CLUE.matcher(msg);
		if (m.matches())
		{
			JsonObject d = new JsonObject();
			d.addProperty("tier", m.group(2).toLowerCase());
			d.addProperty("count", Integer.parseInt(m.group(1).replace(",", "")));
			return new Parsed("clue_done", d);
		}

		m = BOSS_TIME.matcher(msg);
		if (m.matches())
		{
			JsonObject d = new JsonObject();
			d.addProperty("label", m.group(1));
			d.addProperty("seconds", seconds(m.group(2)));
			d.addProperty("newPb", m.group(3) != null);
			if (m.group(4) != null)
			{
				d.addProperty("pbSeconds", seconds(m.group(4)));
			}
			return new Parsed("boss_time", d);
		}

		return null;
	}

	/** "1:23.40" or "1:02:03" to seconds. */
	static double seconds(String time)
	{
		double total = 0;
		for (String part : time.split(":"))
		{
			total = total * 60 + Double.parseDouble(part);
		}
		return Math.round(total * 100) / 100.0;
	}
}

package com.nibtracker;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.Text;

/**
 * Collection log pages, as the player opens them. Each page is sent in Character Export's collection_log shape;
 * the web app merges pages, so the whole log fills in as pages are viewed.
 */
@Singleton
class CollectionLogTracker
{
	@Inject
	private Client client;

	@Inject
	private ItemManager itemManager;

	@Inject
	private NibTrackerConfig config;

	private EventSink sink;
	private final Map<String, JsonObject> lastSent = new HashMap<>();

	void start(EventSink sink)
	{
		this.sink = sink;
	}

	void reset()
	{
		lastSent.clear();
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired e)
	{
		if (e.getScriptId() != ScriptID.COLLECTION_DRAW_LIST || sink == null || !sink.active() || !sink.allowed("clog", config.sendClog()))
		{
			return;
		}
		String page = pageTitle();
		Widget list = client.getWidget(InterfaceID.Collection.ITEMS_CONTENTS);
		if (page == null || list == null || list.getDynamicChildren() == null)
		{
			return;
		}
		JsonArray items = new JsonArray();
		for (Widget w : list.getDynamicChildren())
		{
			int id = w.getItemId();
			if (id <= 0)
			{
				continue;
			}
			boolean got = w.getOpacity() == 0; // missing slots are drawn faded
			JsonObject o = new JsonObject();
			o.addProperty("id", id);
			o.addProperty("name", itemManager.getItemComposition(id).getName());
			o.addProperty("obtained", got);
			o.addProperty("quantity", got ? Math.max(1, w.getItemQuantity()) : 0);
			items.add(o);
		}
		JsonObject entry = new JsonObject();
		entry.add("items", items);
		entry.add("lines", headerLines());
		if (items.size() == 0 || entry.equals(lastSent.get(page)))
		{
			return;
		}
		lastSent.put(page, entry);
		JsonObject pages = new JsonObject();
		pages.add(page, entry);
		JsonObject tabs = new JsonObject();
		tabs.add("Collection log", pages);
		JsonObject d = new JsonObject();
		d.add("tabs", tabs);
		sink.emit("snapshot_collection_log", d);
	}

	/** The page header's lines after its title, as the game shows them ("Obtained: 12/50", "Vardorvis kills: 5"). */
	private JsonArray headerLines()
	{
		JsonArray lines = new JsonArray();
		Widget header = client.getWidget(InterfaceID.Collection.HEADER);
		Widget[] kids = header == null ? null : header.getDynamicChildren();
		for (int i = 1; kids != null && i < kids.length; i++)
		{
			String t = kids[i].getText() == null ? "" : Text.removeTags(kids[i].getText()).trim();
			if (!t.isEmpty())
			{
				lines.add(t);
			}
		}
		return lines;
	}

	private String pageTitle()
	{
		Widget header = client.getWidget(InterfaceID.Collection.HEADER);
		if (header == null)
		{
			return null;
		}
		Widget[] kids = header.getDynamicChildren();
		String t = kids != null && kids.length > 0 ? kids[0].getText() : header.getText();
		t = t == null ? "" : Text.removeTags(t).trim();
		return t.isEmpty() ? null : t;
	}
}

package com.nibtracker;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.function.IntUnaryOperator;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;

/**
 * Bank (with each item's tab), seed vault, potion storage, worn equipment, inventory and any container the server
 * watches, as snapshots. Each is sent a little after it stops changing, and only
 * when it differs from the last one sent.
 */
@Singleton
class ContainerTracker
{
	private static final class Watch
	{
		final String type;
		final String source;
		final int waitTicks;

		Watch(String type, String source, int waitTicks)
		{
			this.type = type;
			this.source = source;
			this.waitTicks = waitTicks;
		}
	}

	private static final Map<Integer, Watch> WATCH = new HashMap<>();
	// Potion storage is not an item container: it is read from the client when due, as RuneLite's bank tags do.
	private static final int POTION_STORAGE = -1;

	static
	{
		WATCH.put(InventoryID.BANK, new Watch("snapshot_bank", "bank", 10));
		WATCH.put(InventoryID.SEED_VAULT, new Watch("snapshot_seed_vault", "bank", 10));
		WATCH.put(POTION_STORAGE, new Watch("snapshot_potion_storage", "bank", 10));
		WATCH.put(InventoryID.WORN, new Watch("snapshot_equipment", "gear", 5));
		WATCH.put(InventoryID.INV, new Watch("snapshot_inventory", "gear", 100));
	}

	/* Another container the server lists under watch.containers, with its id: only these, the player's own storage. A
	   trade partner's offer, a shop or anyone else's items can never be asked for. */
	private static final Watch SERVER_WATCH = new Watch("snapshot_container", "bank", 10);
	static final Set<Integer> OWN_STORAGE = new HashSet<>(Arrays.asList(InventoryID.LOOTING_BAG, InventoryID.SEED_BOX,
		InventoryID.TACKLE_BOX, InventoryID.HUNTSMANS_KIT, InventoryID.INV_GROUP_TEMP, InventoryID.SAILING_BOAT_1_CARGOHOLD,
		InventoryID.SAILING_BOAT_2_CARGOHOLD, InventoryID.SAILING_BOAT_3_CARGOHOLD, InventoryID.SAILING_BOAT_4_CARGOHOLD,
		InventoryID.SAILING_BOAT_5_CARGOHOLD));
	private static final int[] BANK_TABS = {VarbitID.BANK_TAB_1, VarbitID.BANK_TAB_2, VarbitID.BANK_TAB_3, VarbitID.BANK_TAB_4,
		VarbitID.BANK_TAB_5, VarbitID.BANK_TAB_6, VarbitID.BANK_TAB_7, VarbitID.BANK_TAB_8, VarbitID.BANK_TAB_9};

	@Inject
	private Client client;

	@Inject
	private ItemManager itemManager;

	@Inject
	private NibTrackerConfig config;

	private EventSink sink;
	private final Map<Integer, JsonArray> pending = new HashMap<>();
	private final Map<Integer, Integer> dueAt = new HashMap<>();
	private final Map<Integer, JsonArray> lastSent = new HashMap<>();
	private int ticks;

	void start(EventSink sink)
	{
		this.sink = sink;
	}

	void reset()
	{
		pending.clear();
		dueAt.clear();
		lastSent.clear();
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged e)
	{
		Watch w = watch(e.getContainerId());
		if (w == null || sink == null || !sink.active() || !sink.allowed(w.source, config.sendBank()))
		{
			return;
		}
		pending.put(e.getContainerId(), items(e.getContainerId(), e.getItemContainer()));
		schedule(e.getContainerId());
		if (e.getContainerId() == InventoryID.BANK)
		{
			schedule(POTION_STORAGE);
		}
	}

	/** Storing or taking out potions changes varps, not the bank. */
	@Subscribe
	public void onVarbitChanged(VarbitChanged e)
	{
		if (sink != null && sink.active() && sink.allowed("bank", config.sendBank())
			&& client.getWidget(InterfaceID.Bankmain.UNIVERSE) != null)
		{
			schedule(POTION_STORAGE);
		}
	}

	private void schedule(int id)
	{
		dueAt.putIfAbsent(id, ticks + watch(id).waitTicks);
	}

	/** How a container is sent: one of the fixed ones, one the server asks for, or null. */
	private Watch watch(int id)
	{
		Watch w = WATCH.get(id);
		if (w != null || sink == null)
		{
			return w;
		}
		return OWN_STORAGE.contains(id) && ProgressTracker.watchIds(sink.settings(), "containers", 65536, 50).contains(id) ? SERVER_WATCH : null;
	}

	void tick()
	{
		ticks++;
		if (dueAt.isEmpty())
		{
			return;
		}
		dueAt.entrySet().removeIf(due -> {
			if (ticks < due.getValue())
			{
				return false;
			}
			int id = due.getKey();
			JsonArray items = id == POTION_STORAGE ? potions() : pending.remove(id);
			Watch w = watch(id);
			if (w != null && items != null && !items.equals(lastSent.get(id)) && sink.active())
			{
				lastSent.put(id, items);
				JsonObject d = new JsonObject();
				if (w == SERVER_WATCH)
				{
					d.addProperty("container", id);
				}
				d.add("items", items);
				sink.emit(w.type, d);
			}
			return true;
		});
	}

	private JsonArray items(int containerId, ItemContainer c)
	{
		JsonArray out = new JsonArray();
		if (c == null)
		{
			return out;
		}
		// The bank's tabs are runs of slots, tab 1 first; the slots after them are the main tab (0).
		int[] tabSizes = new int[containerId == InventoryID.BANK ? BANK_TABS.length : 0];
		for (int i = 0; i < tabSizes.length; i++)
		{
			tabSizes[i] = client.getVarbitValue(BANK_TABS[i]);
		}
		Item[] all = c.getItems();
		for (int slot = 0; slot < all.length; slot++)
		{
			Item it = all[slot];
			if (!owned(it, i -> itemManager.getItemComposition(i).getPlaceholderTemplateId()))
			{
				continue;
			}
			int id = itemManager.canonicalize(it.getId());
			JsonObject o = new JsonObject();
			o.addProperty("slot", slot);
			o.addProperty("id", id);
			o.addProperty("name", itemManager.getItemComposition(id).getName());
			o.addProperty("quantity", it.getQuantity());
			if (tabSizes.length > 0)
			{
				o.addProperty("tab", bankTab(slot, tabSizes));
			}
			out.add(o);
		}
		return out;
	}

	/** Potion storage as {id, name, quantity}: the full-dose potion, and how many of them its doses make, rounded up. */
	private JsonArray potions()
	{
		JsonArray out = new JsonArray();
		for (int list : new int[]{EnumID.POTIONSTORE_POTIONS, EnumID.POTIONSTORE_UNFINISHED_POTIONS})
		{
			for (int potion : client.getEnum(list).getIntVals())
			{
				client.runScript(ScriptID.POTIONSTORE_DOSES, potion);
				int doses = client.getIntStack()[0];
				if (doses <= 0)
				{
					continue;
				}
				// The potion's enum maps dose -> item; the highest dose it has is the full potion.
				EnumComposition byDose = client.getEnum(potion);
				int max = 4;
				while (max > 1 && byDose.getIntValue(max) <= 0)
				{
					max--;
				}
				int id = byDose.getIntValue(max);
				JsonObject o = new JsonObject();
				o.addProperty("id", id);
				o.addProperty("name", itemManager.getItemComposition(id).getName());
				o.addProperty("quantity", (doses + max - 1) / max);
				out.add(o);
			}
		}
		return out;
	}

	/** The bank tab a slot is in, from each tab's size (tabs 1 to 9 in order): 0 for the main tab after them. */
	static int bankTab(int slot, int[] tabSizes)
	{
		int end = 0;
		for (int i = 0; i < tabSizes.length; i++)
		{
			end += Math.max(0, tabSizes[i]);
			if (slot < end)
			{
				return i + 1;
			}
		}
		return 0;
	}

	/** A real item: not an empty slot, and not a bank placeholder (shown as 0), so canonicalize can't make it owned. */
	static boolean owned(Item it, IntUnaryOperator placeholderTemplate)
	{
		return it.getId() > 0 && it.getQuantity() > 0 && placeholderTemplate.applyAsInt(it.getId()) == -1;
	}
}

package com.nibtracker;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.function.IntUnaryOperator;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/**
 * Which daily tasks the game says are done, and each task's icon. Kept free of client calls so it can be unit tested:
 * callers pass client::getVarbitValue and client::getVarpValue.
 *
 * The signals. The claim flags are the ones RuneLite's Daily Task Indicators plugin reads (dailytaskindicators/
 * DailyTasksPlugin.java): set when claimed, back to 0 at the daily reset. The rest:
 * - Explorer's ring: LUMBRIDGE_FREE_ALCHS counts today's free alchs used, out of 30 for every ring tier (RuneLite's
 *   ItemChargePlugin, MAX_EXPLORER_RING_CHARGES; the game's own lumbridge_alchemy_vartransmit script shows
 *   "30 - lumbridge_free_alchs"). The ring needs the easy Lumbridge & Draynor diary.
 * - Tears of Guthix: no var says "played this week" (the 7-day lock is kept by the server). TOG_QP_BEFORE_RETURN can't
 *   be used either: it's rewritten to the same value when you play again without a new quest point. So it's the game
 *   ending: TOG_MINIGAME_COLLECTING (the cache's tog_minigame_collecting) going from set back to 0, seen live. Its
 *   meaning comes from its name only, so the edge counts only if TOG_TEARS_COLLECTED went above 0 while collecting:
 *   tears in the bowl prove a real game was played (a countdown alone would not), and a stray reset of the collecting
 *   flag outside a game is ignored. A game with no blue tears at all isn't counted; that's left to a manual tick.
 * - Kingdom of Miscellania: approval is MISC_APPROVAL out of 127 and the coffer MISC_COFFERS; unlocked once the
 *   MISC_QUEST varp is above 0. As in RuneLite's kingdomofmiscellania/KingdomPlugin.java, the varbits don't decay
 *   while you're away, so a reading is trusted only in the kingdom (regions 10044 and 10300) or when approval and
 *   coffer are both above 0; it's saved with its time, and today's approval is estimated from it: 2.5% of 127 off per
 *   whole UTC day (1% after Royal Trouble).
 */
final class DailySignals
{
	private DailySignals()
	{
	}

	/* Robin gives 13 buckets per Morytania diary tier from medium up; NMZ sells 15 herb boxes a day; 30 free alchs. */
	private static final int SLIME_PER_DIARY = 13;
	private static final int HERB_BOXES = 15;
	private static final int FREE_ALCHS = 30;
	/* Miscellania approval runs 0 to 127; under 90% it needs a top-up. */
	static final int MAX_APPROVAL = 127;
	static final int APPROVAL_THRESHOLD = 90;
	private static final double DECAY = 0.025;
	private static final double DECAY_ROYAL_TROUBLE = 0.010;
	/* Miscellania and Etceteria, where the approval varbits are current (RuneLite's KINGDOM_REGION). */
	static final Set<Integer> KINGDOM_REGIONS = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(10044, 10300)));

	static final String TEARS = "tears_of_guthix";
	static final String MISCELLANIA = "miscellania";

	/* Each built-in task's icon, for when the feed has no itemId. */
	static final Map<String, Integer> ICONS;

	static
	{
		Map<String, Integer> m = new HashMap<>();
		m.put(TEARS, ItemID.THOSF_REWARD_LAMP);
		m.put(MISCELLANIA, ItemID.POH_TREASURE_TEAK);
		m.put("zaff_staves", ItemID.BATTLESTAFF);
		m.put("bert_sand", ItemID.BUCKET_SAND);
		m.put("cromperty_essence", ItemID.BLANKRUNE_HIGH);
		m.put("seers_flax", ItemID.BOW_STRING);
		m.put("lundail_runes", ItemID.MINDRUNE);
		m.put("rantz_arrows", ItemID.OGRE_ARROW);
		m.put("nmz_herb_boxes", ItemID.NZONE_HERBBOX);
		m.put("thirus_dynamite", ItemID.LOVAKENGJ_DYNAMITE_FUSED);
