	static Contract contract(int itemId)
	{
		return CONTRACTS.get(itemId);
	}

	private static boolean sameCrop(String patchCrop, String contractCrop)
	{
		return stem(patchCrop).equals(stem(contractCrop));
	}

	private static String stem(String s)
	{
		String t = s == null ? "" : s.trim().toLowerCase();
		if (t.endsWith("ies"))
		{
			return t.substring(0, t.length() - 3) + "y";
		}
		if (t.endsWith("oes"))
		{
			return t.substring(0, t.length() - 2);
		}
		if (t.endsWith("s") && !t.endsWith("ss"))
		{
			return t.substring(0, t.length() - 1);
		}
		return t;
	}

	/** How far along a contract crop is, best first: ready, then growing, then diseased or dead. */
	private static int stage(Routines.Patch p, long now)
	{
		return p.needsAttention() ? 2 : p.readyAt(now) || "ready".equals(p.state) ? 0 : 1;
	}

	static ContractView contractView(Contract c, List<Routines.Patch> farm, long now)
	{
		ContractView v = new ContractView();
		if (c == null)
		{
			v.title = "Contract";
			v.value = "No contract · talk to Jane";
			return v;
		}
		v.title = "Contract: " + c.crop + " · Farming Guild " + c.kind.replace('_', ' ') + " patch";
		v.itemId = c.itemId;

		// The guild has two allotments (North and South), so look at every patch of the contract's kind: the contract crop
		// if one has it (the most advanced), else an empty one, and "Other crop planted" only when all hold something else.
		Routines.Patch p = null;
		boolean empty = false;
		for (Routines.Patch q : farm)
		{
			if (!GUILD.equals(q.region) || !c.kind.equals(q.kind))
			{
				continue;
			}
			if ("empty".equals(q.state))
			{
				empty = true;
			}
			else if (sameCrop(q.crop, c.crop) && (p == null || stage(q, now) < stage(p, now)))
			{
				p = q;
			}
		}
		if (p == null)
		{
			boolean any = farm.stream().anyMatch(q -> GUILD.equals(q.region) && c.kind.equals(q.kind));
			if (!any || empty)
			{
				v.value = "Not planted";
				v.sub = "Harvested? See Jane for a new contract";
			}
			else
			{
				v.value = "Other crop planted";
			}
			return v;
		}
		v.progress = p.progress;
		if ("diseased".equals(p.state))
		{
			v.attention = true;
			v.value = "Diseased";
		}
		else if ("dead".equals(p.state))
		{
			v.attention = true;
			v.value = "Dead";
		}
		else if (p.readyAt(now) || "ready".equals(p.state))
		{
			v.ready = true;
			v.value = "Ready · then see Jane for a new contract";
			v.progress = 1;
		}
		else if (p.readyAt > now)
		{
			v.value = Routines.left(p.readyAt - now);
		}
		else
		{
			v.value = "Growing";
		}
		return v;
	}
}

package com.nibtracker;

import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.function.Predicate;

/** What a farm patch row says, and the Farming tab picker's ticking and saving. Pure, so it can be tested. */
final class FarmRows
{
	private FarmRows()
	{
	}

	/** Ready to harvest: not diseased or dead, not empty or unknown, and its timer is up (or the feed says ready). */
	static boolean ready(Routines.Patch p, long now)
	{
		if (p.needsAttention() || "empty".equals(p.state) || "unknown".equals(p.state))
		{
			return false;
		}
		return p.readyAt(now) || "ready".equals(p.state);
	}

	/** A crop growing or ready: not empty, unknown, diseased or dead. Only these count towards timers and ready shares. */
	static boolean growing(Routines.Patch p)
	{
		return !p.needsAttention() && !"empty".equals(p.state) && !"unknown".equals(p.state);
	}

	/**
	 * For sorting soonest first: 0 when ready, its time when growing with a timer, then growing with no timer, and last
	 * a patch with nothing growing (a timer on an empty, unknown, diseased or dead patch means nothing).
	 */
	static long soonest(Routines.Patch p, long now)
	{
		if (ready(p, now))
		{
			return 0;
		}
		if (!growing(p))
		{
			return Long.MAX_VALUE;
		}
		return p.readyAt > now ? p.readyAt : Long.MAX_VALUE - 1;
	}

	static long soonest(List<Routines.Patch> ps, long now)
	{
		long best = Long.MAX_VALUE;
		for (Routines.Patch p : ps)
		{
			best = Math.min(best, soonest(p, now));
		}
		return best;
	}

	/** The growing crop that's ready soonest, by its timer; null when none has a timer. */
	static Routines.Patch next(List<Routines.Patch> ps, long now)
	{
		Routines.Patch next = null;
		for (Routines.Patch p : ps)
		{
			if (growing(p) && !ready(p, now) && p.readyAt > now && (next == null || p.readyAt < next.readyAt))
			{
				next = p;
			}
		}
		return next;
	}

	static boolean anyGrowing(List<Routines.Patch> ps)
	{
		return ps.stream().anyMatch(FarmRows::growing);
	}

	/** How many of the growing or ready crops are ready, 0 to 1; empty, unknown, diseased and dead don't count. */
	static double readyShare(List<Routines.Patch> ps, long now)
	{
		long all = ps.stream().filter(FarmRows::growing).count();
		return all == 0 ? 0 : (double) ps.stream().filter(p -> ready(p, now)).count() / all;
	}

	/** What a group says when nothing is ready or timed: Growing, or else Diseased, Dead, Empty or Unknown. */
	static String idle(List<Routines.Patch> ps)
	{
		if (anyGrowing(ps))
		{
			return "Growing";
		}
		for (String state : new String[]{"diseased", "dead", "empty"})
		{
			if (ps.stream().anyMatch(p -> state.equals(p.state)))
			{
				return Character.toUpperCase(state.charAt(0)) + state.substring(1);
			}
		}
		return "Unknown";
	}

	/** The row's value: Diseased, Dead, Ready, Empty, Unknown, the time left, or Growing when there's no timer. */
	static String status(Routines.Patch p, long now)
	{
		if ("diseased".equals(p.state))
		{
			return "Diseased";
		}
		if ("dead".equals(p.state))
		{
			return "Dead";
		}
		if (ready(p, now))
		{
			return "Ready";
		}
		if ("empty".equals(p.state))
		{
			return "Empty";
		}
		if ("unknown".equals(p.state))
		{
			return "Unknown";
		}
		return p.readyAt > now ? Routines.left(p.readyAt - now) : "Growing";
	}

	/** The row's title: the crop, "Unknown" for an unknown patch, or the kind (Herbs) when nothing is planted. */
	static String title(Routines.Patch p)
	{
		if ("unknown".equals(p.state))
		{
			return "Unknown";
		}
		if (p.crop != null && !p.crop.trim().isEmpty())
		{
			return p.crop;
		}
		return p.kindLabel != null && !p.kindLabel.isEmpty() ? p.kindLabel : "Patch";
	}

	/** The second line: "region · name · travel", leaving out a name that is just the region and an unknown travel. */
	static String sub(String region, String name, String travel)
	{
		StringBuilder s = new StringBuilder(region);
		if (name != null && !name.isEmpty() && !name.equals(region))
		{
			s.append(" · ").append(name);
		}
		if (travel != null && !travel.isEmpty())
		{
			s.append(" · ").append(travel);
		}
		return s.toString();
	}

	/** The same list with the ready rows first, otherwise in the order given. */
	static <T> List<T> readyFirst(List<T> rows, Predicate<T> ready)
	{
		List<T> out = new ArrayList<>();
		for (T t : rows)
		{
			if (ready.test(t))
			{
				out.add(t);
			}
		}
		for (T t : rows)
		{
			if (!ready.test(t))
			{
				out.add(t);
			}
		}
		return out;
	}

	/**
	 * A shift-click in the picker: every row from the last one clicked (anchor) to this one takes this one's new state.
	 * With no anchor (-1) or one out of range, only this row changes.
	 */
	static void tickRange(List<String> ids, int anchor, int index, boolean on, Set<String> ticked)
	{
		int from = anchor >= 0 && anchor < ids.size() ? Math.min(anchor, index) : index;
		int to = anchor >= 0 && anchor < ids.size() ? Math.max(anchor, index) : index;
		for (int i = from; i <= to; i++)
		{
			if (on)
			{
				ticked.add(ids.get(i));
			}
			else
			{
				ticked.remove(ids.get(i));
			}
		}
	}

	/**
	 * The hidden regions after the All patches picker: the offered regions left unticked, plus regions hidden before that
	 * have no timers now (they weren't offered, so they stay as they were).
	 */
	static Set<String> hiddenAfter(Collection<String> offered, Collection<String> hiddenBefore, Set<String> shown)
	{
		Set<String> out = new LinkedHashSet<>();
		for (String r : hiddenBefore)
		{
			if (!offered.contains(r))
			{
				out.add(r);
			}
		}
		for (String r : offered)
		{
			if (!shown.contains(r))
			{
				out.add(r);
			}
		}
		return out;
	}

	/**
	 * The favourites after the Favourites picker, in the order saved: the ones kept stay where they were, new ones go on
	 * the end in the picker's order, and saved ids the picker didn't offer (a patch with no data now) are kept.
	 */
	static List<String> favouritesAfter(Collection<String> saved, List<String> offered, Set<String> ticked)
	{
		Set<String> out = new LinkedHashSet<>();
		for (String id : saved)
		{
			if (!offered.contains(id) || ticked.contains(id))
			{
				out.add(id);
			}
		}
		for (String id : offered)
		{
			if (ticked.contains(id))
			{
				out.add(id);
			}
		}
		return new ArrayList<>(out);
	}

	/**
	 * The patches worked out here, each with the way there and its stop in the run from the feed row with the same id,
	 * then the feed's rows with no patch here, as they are. When there are patches here, only the feed's unknown rows
	 * (special patches it lists with no data) are added: any other feed-only row is out of date, like an emptied bird
	 * house that no longer has a row here. With no patches here (no Time Tracking data) every feed row shows. With no
	 * feed, or one that's older, the rows still show, without travel tips.
	 */
	static List<Routines.Patch> merge(List<Routines.Patch> local, List<Routines.Patch> feed)
	{
		Map<String, Routines.Patch> byId = new HashMap<>();
		for (Routines.Patch f : feed)
		{
			byId.putIfAbsent(f.id(), f);
		}
		List<Routines.Patch> out = new ArrayList<>();
		Set<String> mine = new HashSet<>();
		for (Routines.Patch p : local)
		{
			mine.add(p.id());
			Routines.Patch f = byId.get(p.id());
			if (f != null)
			{
				p = copy(p);
				p.travel = f.travel;
				p.travelHow = f.travelHow;
				p.travelCat = f.travelCat;
				p.travelItem = f.travelItem;
				p.order = f.order;
				p.stop = f.stop;
			}
			out.add(p);
		}
		for (Routines.Patch f : feed)
		{
			if (!mine.contains(f.id()) && (local.isEmpty() || "unknown".equals(f.state)))
			{
				out.add(f);
			}
		}
		return out;
	}

	/** The teleports the player won't use (Book of the dead when it's out of charges), from the setting: one per line or comma. */
	static List<String> excluded(String setting)
	{
		List<String> out = new ArrayList<>();
		for (String s : setting.split("[,\n]"))
		{
			String t = loose(s);
			if (!t.isEmpty())
			{
				out.add(t);
			}
		}
		return out;
	}

	/** Whether a teleport is one the player won't use: its name has one of theirs in it, however either is written. */
	static boolean excluded(String travel, List<String> excluded)
	{
		String t = loose(travel);
		return excluded.stream().anyMatch(t::contains);
	}

	/** A name as typed loosely: any case, apostrophes dropped, anything else but letters and digits a single space. */
	private static String loose(String s)
	{
		return s.toLowerCase(Locale.ROOT).replaceAll("['\u2019]", "").replaceAll("[^a-z0-9]+", " ").trim();
	}

	/** A stop's best teleport the player will use, or null when they've excluded every one there is. */
	static Routines.Tele pick(Routines.Stop s, List<String> excluded)
	{
		for (Routines.Tele t : s.teles)
		{
			if (!excluded(t.travel, excluded))
			{
				return t;
			}
		}
		return null;
	}

	/**
	 * The patches with any excluded teleport swapped for their stop's best one the player will use (copies; the rest
	 * as they were). A patch with no stop, or whose stop has nothing left, keeps what it had.
	 */
	static List<Routines.Patch> skipTeleports(List<Routines.Patch> farm, List<Routines.Stop> route, List<String> excluded)
	{
		if (excluded.isEmpty())
		{
			return farm;
		}
		Map<Integer, Routines.Stop> stops = new HashMap<>();
		route.forEach(s -> stops.put(s.stop, s));
		List<Routines.Patch> out = new ArrayList<>();
		for (Routines.Patch p : farm)
		{
			Routines.Stop s = stops.get(p.stop);
			Routines.Tele t = s == null || p.travel.isEmpty() || !excluded(p.travel, excluded) ? null : pick(s, excluded);
			if (t != null)
			{
				p = copy(p);
				p.travel = t.travel;
				p.travelHow = t.how;
				p.travelCat = t.cat;
				p.travelItem = t.item;
			}
			out.add(p);
		}
		return out;
	}

	/** A copy, so merging leaves the rows it was given as they were. */
	private static Routines.Patch copy(Routines.Patch p)
	{
		Routines.Patch c = new Routines.Patch(p.region, p.name, p.type, p.crop, p.itemId, p.readyAt, p.ready);
		c.travel = p.travel;
		c.travelHow = p.travelHow;
		c.kind = p.kind;
		c.kindLabel = p.kindLabel;
		c.run = p.run;
		c.order = p.order;
		c.stop = p.stop;
		c.travelCat = p.travelCat;
		c.travelItem = p.travelItem;
		c.state = p.state;
		c.progress = p.progress;
		return c;
	}
}

package com.nibtracker;

import com.google.gson.JsonObject;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

/**
 * Farming patches and bird houses, as RuneLite's Time Tracking plugin saves them for this character. The entries are
 * sent as saved ("<region>.<varbit>" = "<value>:<unix seconds>", "birdhouse.<n>", "farmTickOffset" ...), so the
 * web app reads them with the parser it already uses for RuneLite profile files. They're also kept in memory, so the
 * Farming tab can work out the patches here (PatchPredictor).
 */
@Singleton
class FarmingTracker
{
	private static final String GROUP = "timetracking";
	private static final int EVERY_TICKS = 500; // about 5 minutes
	private static final int MAX_ENTRIES = 1000;

	@Inject
	private ConfigManager configManager;

	@Inject
	private NibTrackerConfig config;

	private EventSink sink;
	private JsonObject lastSent;
	private int ticks;
	/* The last read, for this character; replaced whole, so any thread can read it. */
	private volatile Map<String, String> entries = Collections.emptyMap();

	void start(EventSink sink)
	{
		this.sink = sink;
	}

	void login()
	{
		read();
		ticks = EVERY_TICKS - 20; // first send shortly after login
	}

	void reset()
	{
		lastSent = null;
		entries = Collections.emptyMap();
	}

	void tick()
	{
		if (++ticks >= EVERY_TICKS)
		{
			ticks = 0;
			send();
		}
	}

	/** The item id of the Farming Guild contract you hold, from Time Tracking; 0 when none. */
	int contractItemId()
	{
		String value = configManager.getRSProfileConfiguration(GROUP, "contract");
		if (value == null)
		{
			return 0;
		}
		try
		{
			return Integer.parseInt(value.trim());
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}

	/** Also called at logout, so timers planted just before logging out are sent. */
	void send()
	{
		read();
		if (sink == null || !sink.active() || !sink.allowed("farming", config.sendFarming()))
		{
			return;
		}
		JsonObject sent = new JsonObject();
		for (Map.Entry<String, String> e : entries.entrySet())
		{
			sent.addProperty(e.getKey(), e.getValue());
		}
		if (sent.size() == 0 || sent.equals(lastSent))
		{
			return;
		}
		lastSent = sent;
		JsonObject d = new JsonObject();
		d.add("entries", sent);
		sink.emit("snapshot_timetracking", d);
	}

	/** Time Tracking's saved entries for this character as last read: key without the profile -> value. */
	Map<String, String> entries()
	{
		return entries;
	}

	/** Any thread. Reads Time Tracking's entries again (ConfigManager holds them in memory, no disk read). */
	void read()
	{
		String profile = configManager.getRSProfileKey();
		if (profile == null)
		{
			entries = Collections.emptyMap();
			return;
		}
		Map<String, String> m = new LinkedHashMap<>();
		for (String key : configManager.getRSProfileConfigurationKeys(GROUP, profile, ""))
		{
			if (m.size() >= MAX_ENTRIES)
			{
				break;
			}
			String value = configManager.getRSProfileConfiguration(GROUP, key);
			if (value != null)
			{
				m.put(key, value);
			}
		}
		entries = Collections.unmodifiableMap(m);
	}
}

package com.nibtracker;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Function;

/** Per-tab favourites and the pin ids. Pure, so it can be tested. */
final class Favourites
{
	/* Ids hold |, : and commas, so tabs and ids are split on control characters that can't appear in one. */
	private static final char TAB_SEP = '\u001E';
	private static final char ID_SEP = '\u001F';
	/* The Farming tab's Special and All trees groups on the game screen. */
	static final String SPECIAL_PIN = "farming:special";
	static final String TREES_PIN = "farming:trees";

	private Favourites()
	{
	}

	static Map<String, Set<String>> parse(String saved)
	{
		Map<String, Set<String>> out = new LinkedHashMap<>();
		if (saved == null || saved.isEmpty())
		{
			return out;
		}
		for (String line : saved.split(String.valueOf(TAB_SEP)))
		{
			int eq = line.indexOf('=');
			if (eq <= 0)
			{
				continue;
			}
			Set<String> ids = new LinkedHashSet<>();
			for (String id : line.substring(eq + 1).split(String.valueOf(ID_SEP)))
			{
				if (!id.isEmpty())
				{
					ids.add(id);
				}
			}
			out.put(line.substring(0, eq), ids);
		}
		return out;
	}

	static String write(Map<String, Set<String>> m)
	{
		StringBuilder sb = new StringBuilder();
		for (Map.Entry<String, Set<String>> e : m.entrySet())
		{
			if (e.getValue().isEmpty())
			{
				continue;
			}
			if (sb.length() > 0)
			{
				sb.append(TAB_SEP);
			}
			sb.append(e.getKey()).append('=').append(String.join(String.valueOf(ID_SEP), e.getValue()));
		}
		return sb.toString();
	}

	static void toggle(Map<String, Set<String>> m, String tab, String id)
	{
		Set<String> ids = m.computeIfAbsent(tab, k -> new LinkedHashSet<>());
		if (!ids.remove(id))
		{
			ids.add(id);
		}
	}

	static void setAll(Map<String, Set<String>> m, String tab, Collection<String> ids)
	{
		m.put(tab, new LinkedHashSet<>(ids));
	}

	static String patchPin(String patchId)
	{
		return "farm:patch:" + patchId;
	}

	static String dailyPin(String id)
	{
		return "daily:" + id;
	}

	static String groupPin(String tab)
	{
		return "fav:" + tab;
	}

	static String regionPin(String region)
	{
		return "farm:region:" + region;
	}

	static String kindPin(String key)
	{
		return "farming:kind:" + key;
	}

	/** An old "farming:Herbs" pin, from before kinds had keys. Check SPECIAL_PIN and TREES_PIN first: they match too. */
	static boolean isLegacyKindPin(String pin)
	{
		return pin.startsWith("farming:") && !pin.startsWith("farming:kind:") && !pin.equals(FarmGroups.CONTRACT_ID);
	}

	/** The rows whose id is a favourite, in the rows' order (what Overview keeps of a tab). */
	static <T> List<T> only(List<T> rows, Function<T, String> id, Set<String> favs)
	{
		List<T> out = new ArrayList<>();
		for (T r : rows)
		{
			if (favs.contains(id.apply(r)))
			{
				out.add(r);
			}
		}
		return out;
	}

	/* The old kind-chip labels of the tree kinds, as "farming:<label>" pins used them. */
	private static final Set<String> TREE_LABELS = new HashSet<>(Arrays.asList("Trees", "Hardwood", "Redwood"));

	/**
	 * The pins with every old tree-kind pin ("farming:Trees", "farming:kind:hardwood"...) replaced by one All trees pin,
	 * where the first of them was. Those kinds have no chip of their own now, so their pins couldn't be taken off.
	 */
	static Set<String> migrateTreePins(Set<String> pins)
	{
		Set<String> out = new LinkedHashSet<>();
		String kindPrefix = kindPin("");
		for (String pin : pins)
		{
			boolean tree = pin.startsWith(kindPrefix) ? FarmGroups.tree(pin.substring(kindPrefix.length()))
				: !pin.equals(SPECIAL_PIN) && !pin.equals(TREES_PIN) && isLegacyKindPin(pin)
					&& TREE_LABELS.contains(pin.substring("farming:".length()));
			out.add(tree ? TREES_PIN : pin);
		}
		return out;
	}
}

package com.nibtracker;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * How the Goals panel arranges goals: each main goal with its parts folded under it (Base 80 with its skills, a quest
 * cape with its quests), main goals in sections by kind, and finished main goals in a Completed section.
 * Kept free of Swing so it can be unit tested.
 */
final class GoalLayout
{
	private GoalLayout()
	{
	}

	/** A main goal and its parts (empty for a goal on its own). */
	static final class Group
	{
		final GoalsPanel.Row main;
		final List<GoalsPanel.Row> parts;
		/* Shown under the goal but not parts of it (the current Slayer task under a Slayer goal). */
		final List<GoalsPanel.Row> extras = new ArrayList<>();

		Group(GoalsPanel.Row main, List<GoalsPanel.Row> parts)
		{
			this.main = main;
			this.parts = parts;
		}

		/** Parts done: what the web app counted, plus parts done in game since it last sent them. */
		int partsDone()
		{
			int later = 0;
			for (GoalsPanel.Row p : parts)
			{
				if (p.done && !p.serverDone)
				{
					later++;
				}
			}
			return Math.min(partsTotal(), main.partsDone + later);
		}

		int partsTotal()
		{
			return Math.max(main.partsTotal, parts.size());
		}

		/** The main goal's own progress, or the share of parts done when it has none (a quest cape, say). */
		double progress()
		{
			if (main.done)
			{
				return 1;
			}
			if (main.progress >= 0 || partsTotal() == 0)
			{
				return main.progress;
			}
			return (double) partsDone() / partsTotal();
		}
	}

	static final class Layout
	{
		/** Open main goals by section, in display order; empty sections are left out. */
		final Map<String, List<Group>> sections = new LinkedHashMap<>();
		/** Finished main goals, most recent first as the server lists them. */
		final List<Group> completed = new ArrayList<>();
	}

	static Layout of(List<GoalsPanel.Row> rows)
	{
		Map<String, GoalsPanel.Row> byId = new HashMap<>();
		for (GoalsPanel.Row r : rows)
		{
			byId.put(r.id, r);
		}
		Map<String, Group> groups = new LinkedHashMap<>();
		for (GoalsPanel.Row r : rows)
		{
			// A part whose main goal isn't in the list stands on its own; an extra without its goal isn't shown.
			if (r.extra)
			{
				continue;
			}
			if (r.parent.isEmpty() || !byId.containsKey(r.parent) || r.parent.equals(r.id))
			{
				groups.put(r.id, new Group(r, new ArrayList<>()));
			}
		}
		for (GoalsPanel.Row r : rows)
		{
			Group g = r.parent.isEmpty() ? null : groups.get(r.parent);
			if (g != null && r.extra)
			{
				g.extras.add(r);
			}
			else if (g != null && !groups.containsKey(r.id))
			{
				g.parts.add(r);
			}
		}
		Layout out = new Layout();
		for (String c : GoalProgress.CATEGORIES)
		{
			out.sections.put(c, new ArrayList<>());
		}
		for (Group g : groups.values())
		{
			// Parts still to do first, closest to done first; finished parts after them.
			g.parts.sort(Comparator.comparing((GoalsPanel.Row r) -> r.done).thenComparing(r -> -r.progress));
			if (g.main.done)
			{
				out.completed.add(g);
			}
			else
			{
				out.sections.computeIfAbsent(g.main.category, k -> new ArrayList<>()).add(g);
			}
		}
		for (List<Group> s : out.sections.values())
		{
			s.sort(Comparator.comparing((Group g) -> -g.progress()));
		}
		out.sections.values().removeIf(List::isEmpty);
		return out;
	}

	/** What Overview shows of some goals: whole groups, and goals on their own. */
	static final class Picks
	{
		final List<Group> groups = new ArrayList<>();
		final List<GoalsPanel.Row> rows = new ArrayList<>();

		int size()
		{
			return groups.size() + rows.size();
		}

		boolean isEmpty()
		{
			return size() == 0;
		}
	}

	/**
	 * The favourites among some groups, each checked against its own tab's favourites (favs by category, as the ★
	 * saves them). A favourite main goal brings its group with its parts; otherwise each favourite part or extra comes
	 * on its own.
	 */
	static Picks favourites(List<Group> groups, Map<String, Set<String>> favs)
	{
		Picks out = new Picks();
		for (Group g : groups)
		{
			if (favourite(g.main, favs))
			{
				out.groups.add(g);
				continue;
			}
			for (GoalsPanel.Row r : g.extras)
			{
				if (favourite(r, favs))
				{
					out.rows.add(r);
				}
			}
			for (GoalsPanel.Row r : g.parts)
			{
				if (favourite(r, favs))
				{
					out.rows.add(r);
				}
			}
		}
		return out;
	}

	private static boolean favourite(GoalsPanel.Row r, Map<String, Set<String>> favs)
	{
		return favs.getOrDefault(r.category, Collections.emptySet()).contains(r.id);
	}

	/* Overview's sections, top to bottom, until the player drags them into their own order. Completed is always last. */
	static final List<String> OVERVIEW_ORDER = Collections.unmodifiableList(Arrays.asList("Farming", "Daily tasks",
		"Combat achievements", "Quests", "Collection log", "Skills", "Bosses", "Items", "Achievement diaries", "Other"));

	/**
	 * Overview's section order from the saved setting (names, comma separated): the saved ones it knows, in that order,
	 * then any it doesn't mention in the default order, so a new section still shows.
	 */
	static List<String> overviewOrder(String saved)
	{
		List<String> out = new ArrayList<>();
		for (String s : saved.split(","))
		{
			String t = s.trim();
			if (OVERVIEW_ORDER.contains(t) && !out.contains(t))
			{
				out.add(t);
			}
		}
		for (String t : OVERVIEW_ORDER)
		{
			if (!out.contains(t))
			{
				out.add(t);
			}
		}
		return out;
	}

	/**
	 * The order with a section dropped onto another: moving down it lands after that one, moving up before it, so it ends
	 * up where it was dropped either way.
	 */
	static List<String> move(List<String> order, String section, String onto)
	{
		List<String> out = new ArrayList<>(order);
		int from = out.indexOf(section), to = out.indexOf(onto);
		if (from < 0 || to < 0 || from == to)
		{
			return out;
		}
		out.remove(from);
		out.add(to, section);
		return out;
	}
}

package com.nibtracker;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.Paint;
import java.awt.Polygon;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.AbstractMap;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.ImageUtil;

/**
 * What the player chose to show on the game screen (▣ in the Goals panel): goals, daily tasks, patches, the farming
 * contract, groups of patches and favourites lists. Entries are drawn in boxes, one per tab or group they were pinned
 * from, stacked: a title line ("Farming · 2 ready"), then each entry; a box with a single entry is just that entry.
 * Detailed style shows, for each entry, its icon, name, value, a progress bar and one line of detail (the next teleport,
 * the task); Compact shows icon and value. Hover over an entry for everything (what's left, the whole run, how to get
 * there). Size from the plugin settings; Alt-drag to move. GoalTracker works the entries out once per change and set()
 * groups them; this only draws them.
 */
@Singleton
class GoalOverlay extends Overlay
{
	/**
	 * One entry: the box it's drawn in, icon, name, value ("73/80", "3 ready"), a line of detail, progress 0..1 (-1: no
	 * bar), and hover text.
	 */
	static final class Entry
	{
		final String box;
		final BufferedImage icon;
		final String title;
		final String value;
		final String detail;
		final double progress;
		/* Something to act on now (patches ready, tasks due): the value shows in green. */
		final boolean ready;
		final String tooltip;
		/* The value up to its first " · ", for Compact ("Ready · then see Jane..." is "Ready"), without " left". */
		final String shortValue;

		Entry(String box, BufferedImage icon, String title, String value, String detail, double progress, boolean ready, String tooltip)
		{
			this.box = box == null ? "" : box;
			this.icon = icon;
			this.title = title;
			this.value = value;
			this.detail = detail == null ? "" : detail;
			this.progress = progress;
			this.ready = ready;
			this.tooltip = tooltip;
			int dot = value.indexOf(" · ");
			// Compact drops a trailing " left" too: the Slayer task's "120 left" is "120".
			this.shortValue = (dot > 0 ? value.substring(0, dot) : value).replaceFirst(" left$", "");
		}
	}

	/** A box as drawn: its title line (null for a single entry, which needs none) and its entries. */
	private static final class Box
	{
		final String heading;
		final List<Entry> entries;

		Box(String heading, List<Entry> entries)
		{
			this.heading = heading;
			this.entries = entries;
		}
	}

	private static final String STAR = "★ ";
	private static final int BOX_GAP = 6;

	private static final Color READY = new Color(0x3F, 0xC2, 0x5F);
	private static final Color TITLE = new Color(0xF2, 0xEF, 0xE6);
	private static final Color DETAIL = new Color(0xB4, 0xB0, 0xA4);
	private static final Color HEADING = new Color(0xD8, 0xB6, 0x6A);
	private static final Color TRACK = new Color(0, 0, 0, 150);
	private static final Color EDGE = new Color(255, 255, 255, 28);
	private static final Color DIVIDER = new Color(255, 255, 255, 18);

	private final Client client;
	private final TooltipManager tooltips;
	private final NibTrackerConfig config;
	private volatile List<Box> boxes = Collections.emptyList();
	/* Each icon resized once to the size it's drawn at, smoothly, rather than stretched as each frame is drawn (which
	   blurred the pixel art). Emptied when the entries change, and again when an item's picture finishes loading. */
	private final Map<String, BufferedImage> sized = new ConcurrentHashMap<>();

	@Inject
	GoalOverlay(NibTrackerPlugin plugin, Client client, TooltipManager tooltips, NibTrackerConfig config)
	{
		super(plugin);
		this.client = client;
		this.tooltips = tooltips;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	/** Any thread. Groups the entries into boxes here, once per change, so render only draws. */
	void set(List<Entry> entries)
	{
		sized.clear();
		for (Entry e : entries)
		{
			if (e.icon instanceof AsyncBufferedImage)
			{
				((AsyncBufferedImage) e.icon).onLoaded(sized::clear);
			}
		}
		List<Box> out = new ArrayList<>();
		boolean favouriteTitles = config.overlayFavouriteTitles();
		for (Map.Entry<String, List<Entry>> b : boxes(entries))
		{
			// A favourites box can go without its "★ Farming favourites · 6 ready" title (the plugin setting).
			String title = !favouriteTitles && b.getKey().startsWith(STAR) ? null : heading(b.getKey(), b.getValue());
			out.add(new Box(title, b.getValue()));
		}
		this.boxes = Collections.unmodifiableList(out);
	}

	/** The entries grouped by box: boxes in the order first seen, entries in their order within each box. */
	static List<Map.Entry<String, List<Entry>>> boxes(List<Entry> entries)
	{
		Map<String, List<Entry>> byBox = new LinkedHashMap<>();
		for (Entry e : entries)
		{
			byBox.computeIfAbsent(e.box, k -> new ArrayList<>()).add(e);
		}
		List<Map.Entry<String, List<Entry>>> out = new ArrayList<>();
		for (Map.Entry<String, List<Entry>> b : byBox.entrySet())
		{
			out.add(new AbstractMap.SimpleImmutableEntry<>(b.getKey(), Collections.unmodifiableList(b.getValue())));
		}
		return out;
	}

	/**
	 * A box's title line: its name and how many of its entries are ready ("Farming · 2 ready"; "due" for daily tasks).
	 * Null for a single pinned entry, which is a one-line box; a favourites list keeps its title even with one.
	 */
	static String heading(String box, List<Entry> entries)
	{
		if (entries.size() == 1 && !box.startsWith(STAR))
		{
			return null;
		}
		long ready = entries.stream().filter(e -> e.ready).count();
		return ready == 0 ? box : box + " · " + ready + (box.contains("Daily tasks") ? " due" : " ready");
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		List<Box> list = boxes;
		if (list.isEmpty())
		{
			return null;
		}
		int size = config.overlaySize().px;
		boolean compact = config.overlayStyle() == NibTrackerConfig.OverlayStyle.COMPACT;
		// The boxes stacked one under the other, in one overlay, so Alt-drag moves them together.
		int width = 0, y = 0;
		for (Box b : list)
		{
			Dimension d = compact ? compact(g, b, size, y) : detailed(g, b, size, y);
			width = Math.max(width, d.width);
			y += d.height + BOX_GAP;
		}
		return new Dimension(width, y - BOX_GAP);
	}

	/**
	 * A card at y0: the title line, then each entry with icon, name and value, a bar, and a line of detail. A value too
	 * long to sit beside the name (the contract's "Ready · then see Jane...") gets its own line under it.
	 */
	private Dimension detailed(Graphics2D g, Box box, int size, int y0)
	{
		List<Entry> list = box.entries;
		Font titleFont = size >= 26 ? FontManager.getRunescapeFont() : FontManager.getRunescapeSmallFont();
		Font smallFont = FontManager.getRunescapeSmallFont();
		FontMetrics tm = g.getFontMetrics(titleFont), sm = g.getFontMetrics(smallFont);
		int pad = 6, icon = size - 2, gap = 6, bar = Math.max(3, size / 6);
		int width = Math.round(size * 7.6f);
		int textX = pad + icon + gap, textW = width - pad - textX;

		// Lay out first, so the background can be drawn behind everything at the right height.
		int headH = box.heading == null ? 0 : sm.getAscent() + 6;
		int[] tops = new int[list.size()];
		int[] heights = new int[list.size()];
		boolean[] ownLine = new boolean[list.size()];
		int y = pad + headH;
		for (int i = 0; i < list.size(); i++)
		{
			Entry e = list.get(i);
			ownLine[i] = tm.stringWidth(e.value) > textW / 2;
			int h = tm.getAscent() + 3 + (ownLine[i] ? sm.getAscent() + 2 : 0) + ((e.progress >= 0 || e.ready) ? bar + 3 : 0)
				+ (e.detail.isEmpty() ? 0 : sm.getAscent() + 2);
			tops[i] = y0 + y;
			heights[i] = Math.max(icon, h);
			y += heights[i] + (i < list.size() - 1 ? 7 : 0);
		}
		int height = y + pad;

		g.setColor(ComponentConstants.STANDARD_BACKGROUND_COLOR);
		g.fillRoundRect(0, y0, width, height, 6, 6);
		g.setColor(EDGE);
		g.drawRoundRect(0, y0, width - 1, height - 1, 6, 6);
		if (box.heading != null)
		{
			g.setFont(smallFont);
			drawHeading(g, sm, box.heading, pad, y0 + pad + sm.getAscent(), width - 2 * pad);
			// A hairline under the title, as the panel's section headings have.
			g.setColor(DIVIDER);
			g.drawLine(pad, y0 + pad + headH - 3, width - pad, y0 + pad + headH - 3);
		}

		Point mouse = mousePoint();
		Rectangle at = getBounds();
		for (int i = 0; i < list.size(); i++)
		{
			Entry e = list.get(i);
			int top = tops[i];
			if (i > 0)
			{
				g.setColor(DIVIDER);
				g.drawLine(pad, top - 4, width - pad, top - 4);
			}
			drawIcon(g, e.icon, pad, top, icon);
			// Name on the left, value on the right; the name gives way if both don't fit.
			g.setFont(titleFont);
			String value = e.value;
			int valueW = tm.stringWidth(value);
			int ty = top + tm.getAscent();
			shadowed(g, fit(tm, e.title, ownLine[i] ? textW : textW - valueW - 6), textX, ty, TITLE);
			if (!ownLine[i])
			{
				shadowed(g, value, width - pad - valueW, ty, valueColour(e));
			}
			int cy = ty + 3;
			if (ownLine[i])
			{
				g.setFont(smallFont);
				shadowed(g, fit(sm, value, textW), textX, cy + sm.getAscent() - 1, valueColour(e));
				cy += sm.getAscent() + 2;
			}
			if (e.progress >= 0 || e.ready)
			{
				drawBar(g, e, textX, cy, textW, bar);
				cy += bar + 3;
			}
			if (!e.detail.isEmpty())
			{
				g.setFont(smallFont);
				shadowed(g, fit(sm, e.detail, textW), textX, cy + sm.getAscent() - 1, DETAIL);
			}
			hover(e, mouse, at, new Rectangle(0, top - 3, width, heights[i] + 6));
		}
		return new Dimension(width, height);
	}

	/** Small boxes at y0: the title line, then icon and value per entry, with the bar along the bottom of each. */
	private Dimension compact(Graphics2D g, Box box, int size, int y0)
	{
		List<Entry> list = box.entries;
		int bar = Math.max(3, size / 7);
		Point mouse = mousePoint();
		Rectangle at = getBounds();
		int width = 0, y = y0;
		if (box.heading != null)
		{
			Font smallFont = FontManager.getRunescapeSmallFont();
			FontMetrics sm = g.getFontMetrics(smallFont);
			int h = sm.getAscent() + 5, w = headingWidth(sm, box.heading) + 8;
			g.setColor(ComponentConstants.STANDARD_BACKGROUND_COLOR);
			g.fillRoundRect(0, y, w, h, 6, 6);
			g.setFont(smallFont);
			drawHeading(g, sm, box.heading, 4, y + 2 + sm.getAscent(), w - 8);
			width = w;
			y += h + 2;
		}
		g.setFont(size >= 30 ? FontManager.getRunescapeFont() : FontManager.getRunescapeSmallFont());
		FontMetrics fm = g.getFontMetrics();
		for (Entry e : list)
		{
			String value = e.shortValue;
			int textW = fm.stringWidth(value);
			int rowW = size + (textW > 0 ? 3 + textW + 4 : 0);
			int inner = size - bar - 2;
			g.setColor(ComponentConstants.STANDARD_BACKGROUND_COLOR);
			g.fillRoundRect(0, y, rowW, size, 6, 6);
			drawIcon(g, e.icon, (size - inner) / 2, y + 1, inner);
			if (textW > 0)
			{
				shadowed(g, value, size + 3, y + 1 + (inner + fm.getAscent() - fm.getDescent()) / 2, valueColour(e));
			}
			if (e.progress >= 0 || e.ready)
			{
				drawBar(g, e, 3, y + size - bar - 2, rowW - 6, bar);
			}
			hover(e, mouse, at, new Rectangle(0, y, rowW, size));
			width = Math.max(width, rowW);
			y += size + 3;
		}
		return new Dimension(width, y - 3 - y0);
	}

	/** Green when it's ready, light for a measured value, gold for something waiting on you (a yes/no goal, a timer). */
	private static Color valueColour(Entry e)
	{
		return e.ready ? READY : e.progress >= 0 ? TITLE : GoalsPanel.GOLD;
	}

	/**
	 * A slim rounded bar, as the panel draws it: a dark track, then gold deepening to bright gold as it fills, or green
	 * when ready.
	 */
	private static void drawBar(Graphics2D g, Entry e, int x, int y, int w, int h)
	{
		Object aa = g.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(TRACK);
		g.fillRoundRect(x, y, w, h, h, h);
		int fill = (int) Math.round(w * (e.progress < 0 ? 1 : Math.min(1, e.progress)));
		if (fill > 0)
		{
			Paint before = g.getPaint();
			g.setPaint(e.ready ? READY : new GradientPaint(x, 0, GoalsPanel.GOLD_DEEP, x + w, 0, GoalsPanel.GOLD));
			g.fillRoundRect(x, y, Math.max(fill, h), h, h, h);
			g.setPaint(before);
		}
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, aa);
	}

	/* The RuneScape fonts have no ★, so a favourites title gets a drawn star in its place. */
	private static int headingWidth(FontMetrics fm, String text)
	{
		return text.startsWith(STAR) ? fm.getAscent() + 2 + fm.stringWidth(text.substring(STAR.length())) : fm.stringWidth(text);
	}

	private static void drawHeading(Graphics2D g, FontMetrics fm, String text, int x, int baseline, int width)
	{
		if (text.startsWith(STAR))
		{
			int s = fm.getAscent();
			g.setColor(Color.BLACK);
			g.fillPolygon(star(x + 1, baseline - s + 1, s));
			g.setColor(HEADING);
			g.fillPolygon(star(x, baseline - s, s));
			x += s + 2;
			width -= s + 2;
			text = text.substring(STAR.length());
		}
		shadowed(g, fit(fm, text, width), x, baseline, HEADING);
	}

	/** A five-pointed star in an s by s square at x, y. */
	private static Polygon star(int x, int y, int s)
	{
		Polygon p = new Polygon();
		double cx = x + s / 2.0, cy = y + s / 2.0 + s * 0.05, outer = s / 2.0, inner = outer * 0.45;
		for (int i = 0; i < 10; i++)
		{
			double r = i % 2 == 0 ? outer : inner, a = -Math.PI / 2 + i * Math.PI / 5;
			p.addPoint((int) Math.round(cx + r * Math.cos(a)), (int) Math.round(cy + r * Math.sin(a)));
		}
		return p;
	}

	private void drawIcon(Graphics2D g, BufferedImage img, int x, int y, int box)
	{
		if (img == null || img.getWidth() <= 0)
		{
			return;
		}
		double s = Math.min((double) box / img.getWidth(), (double) box / img.getHeight());
		int w = Math.max(1, (int) Math.round(img.getWidth() * s)), h = Math.max(1, (int) Math.round(img.getHeight() * s));
		BufferedImage fit = w == img.getWidth() && h == img.getHeight() ? img
			: sized.computeIfAbsent(System.identityHashCode(img) + ":" + w + "x" + h, k -> ImageUtil.resizeImage(img, w, h));
		g.drawImage(fit, x + (box - w) / 2, y + (box - h) / 2, null);
	}

	private static void shadowed(Graphics2D g, String text, int x, int y, Color c)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(c);
		g.drawString(text, x, y);
	}

	/** Text cut to fit a width, ending ".." when it's cut. */
	private static String fit(FontMetrics fm, String text, int width)
	{
		if (fm.stringWidth(text) <= width)
		{
			return text;
		}
		String t = text;
		while (t.length() > 1 && fm.stringWidth(t + "..") > width)
		{
			t = t.substring(0, t.length() - 1);
		}
		return t.trim() + "..";
	}

	private Point mousePoint()
	{
		return client == null ? null : client.getMouseCanvasPosition();
	}

	private void hover(Entry e, Point mouse, Rectangle at, Rectangle area)
	{
		if (mouse != null && at != null && e.tooltip != null && !e.tooltip.isEmpty()
			&& new Rectangle(at.x + area.x, at.y + area.y, area.width, area.height).contains(mouse.getX(), mouse.getY()))
		{
			tooltips.add(new Tooltip(e.tooltip));
		}
	}
}

package com.nibtracker;

import java.util.ArrayDeque;
import java.util.Deque;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.WidgetNode;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetModalMode;
import net.runelite.client.callback.ClientThread;

/**
 * The game's own notification pop-up (the one used for new collection log slots), shown for completed goals. One at a
 * time; the rest wait their turn. Client thread only.
 */
@Singleton
class GoalPopup
{
	/* The game's notification_display_init script (title, text, colour), as the collection log pop-up runs it. */
	private static final int NOTIFICATION_DISPLAY_INIT = 3343;
	private static final int MAX_WAITING = 10;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	private final Deque<String[]> waiting = new ArrayDeque<>();
	private boolean showing;

	void show(String title, String text)
	{
		if (waiting.size() < MAX_WAITING)
		{
			waiting.addLast(new String[]{title, text});
		}
		next();
	}

	void reset()
	{
		waiting.clear();
	}

	private void next()
	{
		if (showing || waiting.isEmpty() || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		int parent = parentComponent();
		if (parent == -1)
		{
			waiting.clear();
			return;
		}
		String[] p = waiting.pollFirst();
		showing = true;
		WidgetNode node = client.openInterface(parent, InterfaceID.NOTIFICATION_DISPLAY, WidgetModalMode.MODAL_CLICKTHROUGH);
		client.runScript(NOTIFICATION_DISPLAY_INIT, p[0], p[1], -1);
		// The game hides the pop-up when it's finished with it; close the interface then and show the next one.
		clientThread.invokeLater(() -> {
			Widget w = client.getWidget(InterfaceID.NotificationDisplay.CONTAINER);
			if (w != null && w.getWidth() > 0 && client.getGameState() == GameState.LOGGED_IN)
			{
				return false;
			}
			client.closeInterface(node, true);
			showing = false;
			next();
			return true;
		});
	}

	/** Where the pop-up goes in the current window mode (fixed, resizable, or resizable with the modern layout). */
	private int parentComponent()
	{
		switch (client.getTopLevelInterfaceId())
		{
			case InterfaceID.TOPLEVEL:
				return InterfaceID.Toplevel.NOTIFICATIONS;
			case InterfaceID.TOPLEVEL_OSRS_STRETCH:
				return InterfaceID.ToplevelOsrsStretch.NOTIFICATIONS;
			case InterfaceID.TOPLEVEL_PRE_EOC:
				return InterfaceID.ToplevelPreEoc.NOTIFICATIONS;
			default:
				return -1;
		}
	}
}

package com.nibtracker;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.text.NumberFormat;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Experience;

/**
 * Goals from the server's settings, and their progress worked out from what the plugin can see. Only these built-in goal
 * types are worked out here (skill level, skill XP, base level, kill count, collection log item, quest, item owned); for
 * any other type the server's own progress is shown. The server only ever sends parameters, never logic.
 * Kept free of client calls so it can be unit tested.
 */
final class GoalProgress
{
	private GoalProgress()
	{
	}

	/** One goal as the web app published it. */
	static final class Goal
	{
		final String id;
		final String title;
		final String type;
		final JsonObject params;
		final double target;
		final double current;
		final double progress;
		final boolean done;
		final int points;
		/* One line on what the goal is, from the web app (e.g. a combat achievement's task), or empty. */
		final String info;
		/* How to get there (for goals tied to a boss or monster), from the web app, or empty. */
		String travel = "";
		/* The main goal this one is part of (Base 80 for 80 Smithing), or empty. */
		String parent = "";
		/* For a main goal: how many of its parts the web app counts as done, and how many there are. */
		int partsDone;
		int partsTotal;

		Goal(String id, String title, String type, JsonObject params, double target, double current, double progress, boolean done, int points,
			String info)
		{
			this.id = id;
			this.title = title;
			this.type = type;
			this.params = params;
			this.target = target;
			this.current = current;
			this.progress = progress;
			this.done = done;
			this.points = points;
			this.info = info;
		}

		String str(String key)
		{
			JsonElement v = params.get(key);
			return v != null && v.isJsonPrimitive() ? v.getAsString() : "";
		}

		/* The item's id from the web app (already the charged item for inert ones), or 0 when it sent none. */
		int itemId()
		{
			return (int) num("itemId", 0);
		}

		double num(String key, double fallback)
		{
			JsonElement v = params.get(key);
			return v != null && v.isJsonPrimitive() && v.getAsJsonPrimitive().isNumber() ? v.getAsDouble() : fallback;
		}
	}

	/** What the plugin has seen this session. Names are lower case; skills by their RuneLite name. */
	static final class Facts
	{
		final Map<String, Long> xp = new HashMap<>();
		final Map<String, Integer> levels = new HashMap<>();
		final Map<String, Integer> kc = new HashMap<>();
		final Set<String> clog = new HashSet<>();
		final Map<String, String> quests = new HashMap<>();
		final Map<String, Long> bank = new HashMap<>();
		final Map<String, Long> carried = new HashMap<>();
		boolean bankSeen;
		Map<String, String> kcAliases = Collections.emptyMap();

		int kcFor(String boss)
		{
			Integer n = kc.get(metric(boss, kcAliases));
			return n == null ? -1 : n;
		}
	}

	/**
	 * A goal's state for display. progress is 0..1, or -1 when there's nothing to measure. detail is the short value
	 * ("73 / 80"), hint what's left ("1,234,567 XP left"); either may be empty.
	 */
	static final class Result
	{
		final double progress;
		final String detail;
		final String hint;
		final boolean done;

		Result(double progress, String detail, String hint, boolean done)
		{
			this.progress = progress;
			this.detail = detail;
			this.hint = done ? "" : hint;
			this.done = done;
		}
	}

	/** The panel section a goal type goes in, in display order. */
	/* At most this many goals are read from the server (main goals with their parts). */
	static final int MAX_GOALS = 150;

	static final String[] CATEGORIES = {"Skills", "Quests", "Bosses", "Collection log", "Items", "Achievement diaries", "Combat achievements", "Other"};

	static String category(String type)
	{
		switch (type)
		{
			case "skill_level":
			case "skill_xp":
			case "base_level":
				return "Skills";
			case "quest":
				return "Quests";
			case "kc":
				return "Bosses";
			case "clog_item":
				return "Collection log";
			case "item_owned":
				return "Items";
			case "diary_task":
			case "diary_tier":
				return "Achievement diaries";
			case "combat_achievement":
				return "Combat achievements";
			default:
				return "Other";
		}
	}

	/** Reads settings.goals. Anything malformed is skipped. */
	static List<Goal> parse(JsonElement goals)
	{
		List<Goal> out = new ArrayList<>();
		if (goals == null || !goals.isJsonArray())
		{
			return out;
		}
		for (JsonElement e : (JsonArray) goals)
		{
			if (!e.isJsonObject())
			{
				continue;
			}
			JsonObject o = e.getAsJsonObject();
			String id = text(o, "id");
			String type = text(o, "type");
			if (id.isEmpty() || type.isEmpty())
			{
				continue;
			}
			JsonElement params = o.get("params");
			Goal goal = new Goal(id, text(o, "title").isEmpty() ? "Goal" : text(o, "title"), type,
				params != null && params.isJsonObject() ? params.getAsJsonObject() : new JsonObject(),
				number(o, "target", -1), number(o, "current", -1), number(o, "progress", -1),
				o.has("done") && o.get("done").isJsonPrimitive() && o.get("done").getAsBoolean(), (int) number(o, "points", 0), text(o, "info"));
			goal.parent = text(o, "parent");
			goal.travel = text(o, "travel");
			JsonElement parts = o.get("parts");
			if (parts != null && parts.isJsonArray() && parts.getAsJsonArray().size() == 2)
			{
				goal.partsDone = (int) Math.max(0, number(parts.getAsJsonArray(), 0));
				goal.partsTotal = (int) Math.max(0, number(parts.getAsJsonArray(), 1));
			}
			out.add(goal);
			if (out.size() >= MAX_GOALS)
			{
				break;
			}
		}
		return out;
	}

	/** Works out a goal's progress. A goal the server says is done stays done. */
	static Result compute(Goal g, Facts f)
	{
		Result r = local(g, f);
		if (r == null)
		{
			r = fromServer(g);
		}
		return g.done && !r.done ? new Result(1, r.detail, "", true) : r;
	}

	/**
	 * Records whether a goal is done now and says if it has just completed: it was seen not done earlier this session
	 * and is done now, and hasn't been announced before. A goal already done the first time it's seen (at login, or
	 * when it first arrives from the server) never counts, so logging in doesn't bring up old pop-ups.
	 */
	static boolean justCompleted(Map<String, Boolean> wasDone, Set<String> announced, String id, boolean done)
	{
		Boolean before = wasDone.put(id, done);
		return Boolean.FALSE.equals(before) && done && announced.add(id);
	}

	private static Result local(Goal g, Facts f)
	{
		switch (g.type)
		{
			case "skill_level":
			{
				String skill = skillKey(g.str("skill"));
				int target = (int) g.num("level", g.target);
				Long xp = f.xp.get(skill);
				Integer level = f.levels.get(skill);
				if (xp == null || level == null || target < 1)
				{
					return null;
				}
				return new Result(ratio(xp, xpFor(target)), level + " / " + target, toGo(xpFor(target) - xp, " XP left"), level >= target);
			}
			case "skill_xp":
			{
				Long xp = f.xp.get(skillKey(g.str("skill")));
				double target = g.num("xp", g.target);
				if (xp == null || target <= 0)
				{
					return null;
				}
				return new Result(ratio(xp, target), compact(xp) + " / " + compact(target), toGo(target - xp, " XP left"), xp >= target);
			}
			case "base_level":
			{
				int target = (int) g.num("level", g.target);
				if (f.levels.isEmpty() || target < 1)
				{
					return null;
				}
				double sum = 0;
				int lowest = Integer.MAX_VALUE;
				int below = 0;
				long xpLeft = 0;
				for (Map.Entry<String, Integer> s : f.levels.entrySet())
				{
					lowest = Math.min(lowest, s.getValue());
					long xp = f.xp.getOrDefault(s.getKey(), 0L);
					sum += ratio(xp, xpFor(target));
					if (s.getValue() < target)
					{
						below++;
						xpLeft += Math.max(0, xpFor(target) - xp);
					}
				}
				String hint = below == 0 ? "" : below + (below == 1 ? " skill" : " skills") + " below " + target + "  ·  " + fmt(xpLeft) + " XP left";
				return new Result(sum / f.levels.size(), "Lowest " + lowest, hint, lowest >= target);
			}
			case "kc":
			{
				double target = g.num("count", g.target);
				int seen = f.kcFor(g.str("boss"));
				if (target <= 0 || (seen < 0 && g.current < 0))
				{
					return null;
				}
				double count = Math.max(seen, g.current);
				return new Result(ratio(count, target), fmt(count) + " / " + fmt(target), toGo(target - count, " kills left"), count >= target);
			}
			case "clog_item":
			{
				if (!f.clog.contains(g.str("item").toLowerCase(Locale.ROOT)))
				{
					return null;
				}
				return new Result(1, "Obtained", "", true);
			}
			case "quest":
			{
				String state = f.quests.get(g.str("quest").toLowerCase(Locale.ROOT));
				if (state == null)
				{
					return null;
				}
				switch (state)
				{
					case "FINISHED":
						return new Result(1, "Completed", "", true);
					case "IN_PROGRESS":
						return new Result(0.5, "In progress", "Click for the wiki guide", false);
					default:
						return new Result(0, "Not started", "Click for the wiki guide", false);
				}
			}
			case "item_owned":
			{
				String item = g.str("item").toLowerCase(Locale.ROOT);
				double target = Math.max(1, g.num("qty", g.target > 0 ? g.target : 1));
				long carried = f.carried.getOrDefault(item, 0L);
				double have = f.bankSeen ? f.bank.getOrDefault(item, 0L) + carried : Math.max(carried, g.current);
				if (!f.bankSeen && carried == 0)
				{
					return null;
				}
				String hint = f.bankSeen ? toGo(target - have, " more needed") : "Open your bank to count it";
				return new Result(ratio(have, target), fmt(have) + " / " + fmt(target), hint, have >= target);
			}
			default:
				return null;
		}
	}

	private static Result fromServer(Goal g)
	{
		boolean counted = g.target > 0 && g.current >= 0;
		String detail = counted ? fmt(g.current) + " / " + fmt(g.target) : g.done ? "Done" : "";
		double p = g.done ? 1 : g.progress >= 0 ? Math.min(1, g.progress) : counted ? ratio(g.current, g.target) : -1;
		String hint = !g.info.isEmpty() ? g.info
			: "clog_item".equals(g.type) ? "Not in your collection log yet"
			: "item_owned".equals(g.type) ? "Open your bank to count it"
			: "Updates when Nib Tracker sees it";
		return new Result(p, detail, hint, g.done);
	}

	private static String toGo(double left, String what)
	{
		return left > 0 ? fmt(Math.ceil(left)) + what : "";
	}

	/** 13,034,431 as 13.0M and 250,000 as 250K, to keep the panel's value column narrow. */
	static String compact(double n)
	{
		if (n >= 10_000_000)
		{
			return String.format(Locale.US, "%.1fM", n / 1_000_000);
		}
		if (n >= 100_000)
		{
			return Math.round(n / 1000) + "K";
		}
		return fmt(n);
	}

	/** A boss name as a Wise Old Man metric key, as the server's bt_wom_metric does, with its alias list. */
	static String metric(String name, Map<String, String> aliases)
	{
		String k = name.toLowerCase(Locale.ROOT).replace("'", "").replaceAll("[^a-z0-9]+", "_").replaceAll("^_+|_+$", "");
		return aliases.getOrDefault(k, k);
	}

	/** Skill names as the web app writes them, as RuneLite's lower-case names. */
	static String skillKey(String skill)
	{
		String s = skill.toLowerCase(Locale.ROOT);
		return "runecrafting".equals(s) ? "runecraft" : s;
	}

	static int xpFor(int level)
	{
		return Experience.getXpForLevel(Math.max(1, Math.min(Experience.MAX_VIRT_LEVEL, level)));
	}

	private static double ratio(double have, double need)
	{
		return need <= 0 ? 1 : Math.max(0, Math.min(1, have / need));
	}

	static String fmt(double n)
	{
		return NumberFormat.getIntegerInstance(Locale.US).format((long) n);
	}

	private static String text(JsonObject o, String key)
	{
		JsonElement v = o.get(key);
		return v != null && v.isJsonPrimitive() ? v.getAsString() : "";
	}

	private static double number(JsonObject o, String key, double fallback)
	{
		JsonElement v = o.get(key);
		return v != null && v.isJsonPrimitive() && v.getAsJsonPrimitive().isNumber() ? v.getAsDouble() : fallback;
	}

	private static double number(JsonArray a, int i)
	{
		JsonElement v = a.get(i);
		return v != null && v.isJsonPrimitive() && v.getAsJsonPrimitive().isNumber() ? v.getAsDouble() : 0;
	}

	/** A goal's value in a few characters, for the game screen: "73/80", "34 left", or a percentage when it's longer. */
	static String shortText(String detail, double progress, boolean done)
	{
		if (done)
		{
			return "Done";
		}
		String d = detail == null ? "" : detail.replace(" / ", "/").trim();
		if (d.length() <= 12)
		{
			return d.isEmpty() && progress >= 0 ? Math.round(progress * 100) + "%" : d;
		}
		return progress >= 0 ? Math.round(progress * 100) + "%" : d.substring(0, 10) + "..";
	}
}

