	static final class PatchView
	{
		final String region;
		final String crop;
		final String type;
		final String status;
		final String travel;
		final String travelHow;
		final boolean ready;
		final int itemId;
		/* Its kind's label (Herbs), its stop in the run order (0 = not planned), and the teleport's kind and item. */
