/**
 * Reports the player's own game events to Nib Tracker. The plugin only reports facts (a drop, a kill count, XP gained);
 * the web app decides what they mean. Contract: docs/plugin-spec.md in the Nib Tracker repo.
 */
@Slf4j
@PluginDescriptor(
	name = "Nib Tracker",
	description = "Syncs your loot, kill counts, collection log, XP and levels to your Nib Tracker planner",
	tags = {"loot", "collection", "log", "xp", "goals", "planner", "sync", "leagues"}
)
public class NibTrackerPlugin extends Plugin implements EventSink
{
	private static final int MAX_QUEUE = 2000;
	private static final int BATCH = 50;
	private static final long MAX_BACKOFF_MS = 5 * 60_000L;
	/* What this build supports beyond the basics, sent with snapshot_character: add one with each new server-driven feature. */
	private static final List<String> CAPABILITIES = Arrays.asList("potion_storage", "bank_tabs", "clog_lines",
		"watch_vars", "watch_containers", "notice", "bingo", "farm_route", "ge_empty");
	/* IRONMAN varbit value -> the account modes the web app uses. */
	private static final String[] ACCOUNT_TYPES = {"main", "ironman", "ultimate", "hardcore", "group", "group", "group"};

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private NibTrackerConfig config;

	@Inject
	private NibTrackerApi api;

	@Inject
	private ItemManager itemManager;

	@Inject
	private SkillIconManager skillIconManager;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private EventBus eventBus;

	@Inject
	private ProgressTracker progress;

	@Inject
	private SlayerTracker slayer;

	@Inject
	private ContainerTracker containers;

	@Inject
	private GrandExchangeTracker grandExchange;

	@Inject
	private FarmingTracker farming;

	@Inject
	private CollectionLogTracker collectionLog;

	@Inject
	private ScreenshotService screenshots;

	@Inject
	private GoalTracker goals;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private GoalOverlay goalOverlay;

	private NavigationButton goalsButton;

	/** An event waiting to be sent, with the character and profile it belongs to. */
	private static final class Pending
	{
		final JsonObject who;
		final JsonObject ev;

		Pending(JsonObject who, JsonObject ev)
		{
			this.who = who;
			this.ev = ev;
		}
	}

	private final ConcurrentLinkedDeque<Pending> queue = new ConcurrentLinkedDeque<>();
	private ScheduledFuture<?> ticker;

	/* Client thread only. */
	private final Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
	private final Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
	private final Map<String, Integer> xpGains = new LinkedHashMap<>();
	private long xpBucketStart;
	private long sessionStart;
	private int primeIn = -1;
	private boolean xpChanged;
	private long nextSnapshotAt;

	/* Who is playing: RSN, hashed account id and game profile (main vs league etc). Set at login, null when logged out. */
	private volatile JsonObject who;
	private volatile boolean linked;
	private volatile boolean helloSent;
	private volatile long nextHelloAt;
	private volatile JsonObject settings = new JsonObject();

	/* One batch at a time: send() runs on the scheduler, and on the client thread at logout and shutdown. */
	private final AtomicBoolean inFlight = new AtomicBoolean();
	private volatile long nextSendAt;
	private volatile long backoffMs;
	private volatile long lastSentAt;
	/* When settings last came from the server; if nothing has been sent for a while they're asked for again. */
	private volatile long settingsAt;
	private volatile boolean refreshing;

	@Override
	protected void startUp()
	{
		for (Object t : trackers())
		{
			eventBus.register(t);
		}
		progress.start(this);
		slayer.start(this);
		containers.start(this);
		grandExchange.start(this);
		farming.start(this);
		collectionLog.start(this);
		GoalsPanel panel = new GoalsPanel(itemManager, skillIconManager);
		goals.start(this, panel);
		goalsButton = NavigationButton.builder()
			.tooltip("Nib Tracker goals")
			.icon(goalsIcon())
			.priority(8)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(goalsButton);
		overlayManager.add(goalOverlay);
		ticker = executor.scheduleWithFixedDelay(this::tick, 2, 1, TimeUnit.SECONDS);
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			primeIn = 2;
		}
	}

	@Override
	protected void shutDown()
	{
		if (ticker != null)
		{
			ticker.cancel(false);
			ticker = null;
		}
		clientToolbar.removeNavigation(goalsButton);
		overlayManager.remove(goalOverlay);
		goalsButton = null;
		for (Object t : trackers())
		{
			eventBus.unregister(t);
		}
		clientThread.invoke(() -> {
			endSession();
			send(true);
			resetLink();
			screenshots.reset();
			goals.reset();
		});
	}

	private Object[] trackers()
	{
		return new Object[]{progress, slayer, containers, grandExchange, collectionLog, goals};
	}

	/** The Goals panel's toolbar icon: the Nib Tracker logo (64 px in the jar, shown at 18 px). */
	private static BufferedImage goalsIcon()
	{
		return ImageUtil.resizeImage(ImageUtil.loadImageResource(NibTrackerPlugin.class, "goals_icon.png"), 18, 18, true);
	}

	@Provides
	NibTrackerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(NibTrackerConfig.class);
	}

	// ------------------------------------------------------------ game events

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		GameState s = e.getGameState();
		if (s == GameState.LOGGED_IN && who == null && primeIn < 0)
		{
			primeIn = 2;
		}
		else if (s == GameState.LOGIN_SCREEN || s == GameState.HOPPING)
		{
			// Hopping can move between a normal and a league or Deadman world, so the profile is worked out again after.
			endSession();
			send(true);
			resetLink();
		}
	}

	@Subscribe
	public void onGameTick(GameTick e)
	{
		if (primeIn > 0 && --primeIn == 0)
		{
			prime();
		}
		goals.tick();
		if (who == null)
		{
			return;
		}
		long now = System.currentTimeMillis();
		if (!xpGains.isEmpty() && now - xpBucketStart >= setting("xpBucketSeconds", 60) * 1000L)
		{
			flushXp();
		}
		if (xpChanged && linked && now >= nextSnapshotAt)
		{
			snapshotCharacter();
		}
		progress.tick();
		slayer.tick();
		containers.tick();
		farming.tick();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged e)
	{
		// Time Tracking saved a patch, a bird house or the contract (a new one from Jane, or one handed in): the Farming
		// tab works its patches out again from what's saved.
		if ("timetracking".equals(e.getGroup()))
		{
			if (who != null)
			{
				farming.read();
			}
			goals.refresh();
			return;
		}
		if (!NibTrackerConfig.GROUP.equals(e.getGroup()))
		{
			return;
		}
		if ("syncEnabled".equals(e.getKey()) || "pluginKey".equals(e.getKey()))
		{
			linked = false;
			helloSent = false;
			nextHelloAt = 0;
		}
		// Any of the plugin's settings can change what the Goals panel or the game screen shows.
		goals.refresh();
	}

	@Subscribe
	public void onChatMessage(ChatMessage e)
	{
		ChatMessageType t = e.getType();
		if (t != ChatMessageType.GAMEMESSAGE && t != ChatMessageType.SPAM)
		{
			return;
		}
		String msg = Text.removeTags(e.getMessage());
		ChatParser.Parsed p = ChatParser.parse(msg);
		if (p == null)
		{
			return;
		}
		goals.onParsed(p.type, p.data);
		if (!allowed(sourceOf(p.type), localToggle(p.type)))
		{
			return;
		}
		progress.onParsed(p.type);
		// The original line goes along too, so the server can re-read it if a pattern here turns out to be wrong.
		p.data.addProperty("msg", msg);
		String id = add(p.type, p.data);
		if ("clog_new".equals(p.type))
		{
			screenshotIfWanted(id, p.data.get("item").getAsString());
		}
	}

	@Subscribe
	public void onLootReceived(LootReceived e)
	{
		if (!allowed("loot", config.sendLoot()))
		{
			return;
		}
		JsonArray items = new JsonArray();
		long value = 0;
		for (ItemStack s : e.getItems())
		{
			long price = itemManager.getItemPrice(s.getId());
			value += price * s.getQuantity();
			JsonObject it = new JsonObject();
			it.addProperty("id", s.getId());
			it.addProperty("name", itemManager.getItemComposition(s.getId()).getName());
			it.addProperty("qty", s.getQuantity());
			it.addProperty("price", price);
			items.add(it);
		}
		if (items.size() == 0 || value < setting("minLootValue", 0))
		{
			return;
		}
		JsonObject d = new JsonObject();
		d.addProperty("source", e.getName());
		d.addProperty("sourceType", e.getType().name());
		if (e.getCombatLevel() > 0)
		{
			d.addProperty("combatLevel", e.getCombatLevel());
		}
		if (e.getAmount() > 1)
		{
			d.addProperty("amount", e.getAmount());
		}
		d.add("items", items);
		String id = add("loot", d);
		for (JsonElement it : items)
		{
			if (screenshotIfWanted(id, it.getAsJsonObject().get("name").getAsString()))
			{
				break;
			}
		}
	}

	/** Captures the screen for this event if the item is on one of the player's live bingo drop tiles. */
	private boolean screenshotIfWanted(String eventId, String item)
	{
		JsonElement wanted = settings.get("screenshotItems");
		if (eventId == null || item == null || wanted == null || !wanted.isJsonArray() || !allowed("screenshots", config.sendScreenshots()))
		{
			return false;
		}
		for (JsonElement w : wanted.getAsJsonArray())
		{
			if (w.isJsonPrimitive() && w.getAsString().equalsIgnoreCase(item))
			{
				screenshots.capture(eventId, config.pluginKey().trim());
				return true;
			}
		}
		return false;
	}

	@Subscribe
	public void onStatChanged(StatChanged e)
	{
		if (who == null)
		{
			return;
		}
		Skill skill = e.getSkill();
		Integer xpBefore = xp.put(skill, e.getXp());
		if (xpBefore != null && e.getXp() > xpBefore)
		{
			xpChanged = true;
			if (xpGains.isEmpty())
			{
				xpBucketStart = System.currentTimeMillis();
			}
			xpGains.merge(skill.getName(), e.getXp() - xpBefore, Integer::sum);
		}
		int real = client.getRealSkillLevel(skill);
		Integer before = levels.put(skill, real);
		if (before != null && real > before && allowed("levels", config.sendLevels()))
		{
			JsonObject d = new JsonObject();
			d.addProperty("skill", skill.getName());
			d.addProperty("level", real);
			d.addProperty("xp", e.getXp());
			add("level", d);
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath e)
	{
		Player me = client.getLocalPlayer();
		if (me == null || e.getActor() != me || !allowed("deaths", config.sendSessions()))
		{
			return;
		}
		JsonObject d = new JsonObject();
		d.addProperty("regionId", me.getWorldLocation().getRegionID());
		add("death", d);
	}

	// ------------------------------------------------------------ login, sessions, linking

	/** Client thread, a couple of ticks after login once stats have loaded. */
	private void prime()
	{
		Player me = client.getLocalPlayer();
		long hash = client.getAccountHash();
		if (me == null || me.getName() == null || hash == -1)
		{
			primeIn = 2;
			return;
		}
		for (Skill s : Skill.values())
		{
			if (s != Skill.OVERALL)
			{
				levels.put(s, client.getRealSkillLevel(s));
				xp.put(s, client.getSkillExperience(s));
			}
		}
		JsonArray worldTypes = new JsonArray();
		for (WorldType t : client.getWorldType())
		{
			worldTypes.add(t.name());
		}
		JsonObject w = new JsonObject();
		w.addProperty("rsn", me.getName().replace((char) 160, ' '));
		w.addProperty("acct", accountId(hash));
		w.addProperty("profile", RuneScapeProfileType.getCurrent(client).name());
		w.add("worldTypes", worldTypes);
		who = w;
		sessionStart = System.currentTimeMillis();
		nextSnapshotAt = 0;
		xpChanged = true;

		if (allowed("sessions", config.sendSessions()))
		{
			JsonObject d = new JsonObject();
			d.addProperty("world", client.getWorld());
			d.add("worldTypes", worldTypes);
			add("session_start", d);
		}
		progress.login();
		slayer.login();
		grandExchange.login();
		farming.login();
		goals.login();
	}

	/** Client thread. Sends what's left of the XP bucket and the session length, then forgets who was playing. */
	private void endSession()
	{
		if (who == null)
		{
			return;
		}
		flushXp();
		farming.send();
		if (xpChanged)
		{
			snapshotCharacter();
		}
		if (allowed("sessions", config.sendSessions()))
		{
			JsonObject d = new JsonObject();
			d.addProperty("seconds", (System.currentTimeMillis() - sessionStart) / 1000);
			add("session_end", d);
		}
		who = null;
		progress.reset();
		slayer.reset();
		containers.reset();
		grandExchange.reset();
		farming.reset();
		collectionLog.reset();
		goals.reset();
		levels.clear();
		xp.clear();
		primeIn = -1;
	}

	private void flushXp()
	{
		if (xpGains.isEmpty())
		{
			return;
		}
		if (allowed("xp", config.sendXp()))
		{
			JsonObject gains = new JsonObject();
			xpGains.forEach(gains::addProperty);
			JsonObject d = new JsonObject();
			d.add("gains", gains);
			d.addProperty("seconds", Math.max(1, (System.currentTimeMillis() - xpBucketStart) / 1000));
			add("xp", d);
		}
		xpGains.clear();
	}

	/** Scheduler thread. */
	private void hello()
	{
		JsonObject w = who;
		String key = config.pluginKey().trim();
		if (w == null || !config.syncEnabled() || key.isEmpty() || helloSent)
		{
			return;
		}
		helloSent = true;
		api.hello(key, w, r -> {
			if (r == null)
			{
				helloSent = false;
				nextHelloAt = System.currentTimeMillis() + 30_000;
				return;
			}
			if (!r.has("ok") || !r.get("ok").getAsBoolean())
			{
				chat(problem(r));
				return;
			}
			if (r.has("settings") && r.get("settings").isJsonObject())
			{
				updateSettings(r.getAsJsonObject("settings"), r.get("plannerAccount"));
			}
			linked = true;
			JsonElement msg = settings.get("message");
			if (msg != null && msg.isJsonPrimitive())
			{
				chat(msg.getAsString());
			}
			JsonElement planner = r.get("plannerAccount");
			String name = w.get("rsn").getAsString() + profileLabel(w.get("profile").getAsString());
			chat(planner != null && planner.isJsonPrimitive()
				? "Nib Tracker is syncing " + name + " to " + planner.getAsString() + "."
				: "Nib Tracker: choose which planner character " + name + " syncs to on the Account page. Nothing is lost meanwhile.");
		});
	}

	private void resetLink()
	{
		linked = false;
		helloSent = false;
		inFlight.set(false);
		backoffMs = 0;
		nextSendAt = 0;
		nextHelloAt = 0;
	}

	private static String problem(JsonObject r)
	{
		String err = r.has("error") ? r.get("error").getAsString() : "";
		if ("bad_key".equals(err))
		{
			return "Nib Tracker doesn't recognise your plugin key. Make a new one on the Account page.";
		}
		return "Nib Tracker couldn't link this character (" + err + ").";
	}

	private static String profileLabel(String profile)
	{
		if ("STANDARD".equals(profile))
		{
			return "";
		}
		String p = profile.toLowerCase().replace('_', ' ');
		return " (" + Character.toUpperCase(p.charAt(0)) + p.substring(1) + ")";
	}

	/**
	 * A one-way hash of RuneLite's account hash: stable for the account across name changes, but not the raw id.
	 * The "bun-tracker:" salt is from before the rename and must never change, or every character gets a new id.
	 */
	static String accountId(long accountHash)
	{
		try
		{
			byte[] d = MessageDigest.getInstance("SHA-256").digest(("bun-tracker:" + accountHash).getBytes(StandardCharsets.UTF_8));
			StringBuilder sb = new StringBuilder();
			for (int i = 0; i < 16; i++)
			{
				sb.append(String.format("%02x", d[i]));
			}
			return sb.toString();
		}
		catch (Exception e)
		{
			throw new IllegalStateException(e);
		}
	}

	// ------------------------------------------------------------ snapshots, queue and sending

	private void snapshotCharacter()
	{
		xpChanged = false;
		nextSnapshotAt = System.currentTimeMillis() + setting("snapshotMinutes", 30) * 60_000L;
		Player me = client.getLocalPlayer();
		if (!allowed("levels", config.sendLevels()) || me == null || who == null)
		{
			return;
		}
		JsonObject stats = new JsonObject();
		for (Skill s : Skill.values())
		{
			if (s == Skill.OVERALL)
			{
				continue;
			}
			JsonObject v = new JsonObject();
			v.addProperty("real_level", client.getRealSkillLevel(s));
			v.addProperty("experience", client.getSkillExperience(s));
			stats.add(s.getName().toLowerCase(), v);
		}
		int iron = client.getVarbitValue(VarbitID.IRONMAN);
		JsonObject d = new JsonObject();
		d.addProperty("account_name", who.get("rsn").getAsString());
		d.addProperty("account_type", iron >= 0 && iron < ACCOUNT_TYPES.length ? ACCOUNT_TYPES[iron] : "main");
		d.addProperty("combat_level", me.getCombatLevel());
		d.addProperty("total_level", client.getTotalLevel());
		d.add("stats", stats);
		// Which plugin sent it and what it can do, so the server only asks a plugin for what it supports.
		d.addProperty("plugin_version", NibTrackerApi.VERSION);
		JsonArray caps = new JsonArray();
		CAPABILITIES.forEach(caps::add);
		d.add("plugin_caps", caps);
		add("snapshot_character", d);
	}

	/** Client thread. */
	private String add(String type, JsonObject data)
	{
		JsonObject w = who;
		if (w == null || !config.syncEnabled() || config.pluginKey().trim().isEmpty())
		{
			return null;
		}
		String id = UUID.randomUUID().toString();
		JsonObject ev = new JsonObject();
		ev.addProperty("v", 1);
		ev.addProperty("id", id);
		ev.addProperty("type", type);
		ev.addProperty("ts", Instant.now().toString());
		ev.addProperty("world", client.getWorld());
		ev.add("data", data);
		queue.addLast(new Pending(w, ev));
		while (queue.size() > MAX_QUEUE)
		{
			queue.pollFirst();
		}
		return id;
	}

	// EventSink, for the trackers (client thread).

	@Override
	public String emit(String type, JsonObject data)
	{
		return add(type, data);
	}

	@Override
	public JsonObject settings()
	{
		return settings;
	}

	@Override
	public boolean active()
	{
		return who != null;
	}

	/** Any thread. New settings from the server; the watch list is re-read on the client thread if it changed. */
	private void updateSettings(JsonObject s, JsonElement plannerAccount)
	{
		JsonElement oldWatch = settings.get("watch");
		settings = s;
		settingsAt = System.currentTimeMillis();
		if (oldWatch == null || !oldWatch.equals(s.get("watch")))
		{
			clientThread.invoke(progress::settingsChanged);
		}
		goals.settingsChanged(s, plannerAccount != null && plannerAccount.isJsonPrimitive() ? plannerAccount.getAsString() : null);
	}

	/** Scheduler thread. Asks for settings again (goals included) when nothing has been sent for a couple of minutes. */
	private void refreshSettings()
	{
		JsonObject w = who;
		if (w == null || refreshing)
		{
			return;
		}
		refreshing = true;
		settingsAt = System.currentTimeMillis();
		api.hello(config.pluginKey().trim(), w, r -> {
			refreshing = false;
			if (r != null && r.has("ok") && r.get("ok").getAsBoolean() && r.has("settings") && r.get("settings").isJsonObject() && w == who)
			{
				updateSettings(r.getAsJsonObject("settings"), r.get("plannerAccount"));
			}
		});
	}

	/** Scheduler thread, once a second. An exception would stop the scheduler running it again, so none gets out. */
	private void tick()
	{
		try
		{
			tickOnce();
		}
		catch (RuntimeException e)
		{
			log.debug("Nib Tracker tick failed", e);
		}
	}

	private void tickOnce()
	{
		if (!helloSent && who != null && config.syncEnabled() && System.currentTimeMillis() >= nextHelloAt)
		{
			hello();
		}
		if (linked && System.currentTimeMillis() - settingsAt >= 120_000L)
		{
			refreshSettings();
		}
		long gap = setting("flushSeconds", 10) * 1000L;
		if (queue.size() >= BATCH || System.currentTimeMillis() - lastSentAt >= gap)
		{
			send(false);
		}
	}

	/** Sends one batch. A batch only holds events from one character and profile. */
	private void send(boolean now)
	{
		long t = System.currentTimeMillis();
		Pending first = queue.peekFirst();
		if (!linked || first == null || (!now && t < nextSendAt) || !inFlight.compareAndSet(false, true))
		{
			return;
		}
		List<Pending> batch = new ArrayList<>();
		Pending p;
		while (batch.size() < BATCH && (p = queue.peekFirst()) != null && p.who == first.who)
		{
			batch.add(queue.pollFirst());
		}
		JsonArray arr = new JsonArray();
		batch.forEach(x -> arr.add(x.ev));
		if (batch.isEmpty())
		{
			inFlight.set(false); // another thread took these events first
			return;
		}
		lastSentAt = t;
		api.ingest(config.pluginKey().trim(), first.who, arr, r -> {
			inFlight.set(false);
			if (r != null && r.has("ok") && r.get("ok").isJsonPrimitive() && r.get("ok").getAsBoolean())
			{
				backoffMs = 0;
				nextSendAt = 0;
				List<String> ids = new ArrayList<>();
				batch.forEach(x -> ids.add(x.ev.get("id").getAsString()));
				screenshots.eventsDelivered(ids);
				if (r.has("settings") && r.get("settings").isJsonObject())
				{
					updateSettings(r.getAsJsonObject("settings"), r.get("plannerAccount"));
				}
				return;
			}
			String err = r != null && r.has("error") ? r.get("error").getAsString() : null;
			if ("bad_key".equals(err))
			{
				linked = false;
				queue.clear();
				screenshots.reset(); // their events will never reach the server, so free the space they hold
				chat(problem(r));
				return;
			}
			// Network trouble, rate limit or a server error: put the batch back and wait longer each time.
			for (int i = batch.size() - 1; i >= 0; i--)
			{
				queue.addFirst(batch.get(i));
			}
			backoffMs = Math.min(MAX_BACKOFF_MS, backoffMs == 0 ? 5_000 : backoffMs * 2);
			nextSendAt = System.currentTimeMillis() + backoffMs;
		});
	}

	// ------------------------------------------------------------ helpers

	/** Which server "send" switch covers a chat event type. */
	private static String sourceOf(String type)
	{
		switch (type)
		{
			case "clog_new":
				return "clog";
			case "pet":
				return "pets";
			case "quest_done":
				return "quests";
			case "ca_done":
				return "combatTasks";
			case "clue_done":
				return "clues";
			case "boss_time":
				return "times";
			case "league_task":
				return "league";
			case "diary_task":
			case "diary_done":
				return "diaries";
			case "slayer_task_done":
				return "slayer";
			default:
				return "kc";
		}
	}

	private boolean localToggle(String type)
	{
		switch (type)
		{
			case "clog_new":
			case "pet":
				return config.sendClog();
			case "quest_done":
			case "ca_done":
			case "league_task":
			case "diary_task":
			case "diary_done":
				return config.sendTasks();
			case "slayer_task_done":
				return config.sendSlayer();
			default:
				return config.sendKc();
		}
	}

	/** A source is sent only if both the player and the server allow it. */
	@Override
	public boolean allowed(String serverKey, boolean local)
	{
		if (!local)
		{
			return false;
		}
		JsonElement send = settings.get("send");
		if (send == null || !send.isJsonObject())
		{
			return true;
		}
		JsonElement v = send.getAsJsonObject().get(serverKey);
		return v == null || v.getAsBoolean();
	}

	private int setting(String key, int fallback)
	{
		JsonElement v = settings.get(key);
		return v != null && v.isJsonPrimitive() ? v.getAsInt() : fallback;
	}

	private void chat(String msg)
	{
		// Escaped, so names and messages from the server show as plain text and can't add colours or icons.
		clientThread.invoke(() -> client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", Text.escapeJagex(msg), null));
	}
}

package com.nibtracker;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarPlayerID;

/**
 * Farm patches and bird houses worked out from what RuneLite's Time Tracking plugin saves, so the Farming tab is
 * current without the website open. A port of the web app's TT.predictAll, itself a port of RuneLite's
 * FarmingTracker.predictPatch (BSD-2-Clause); the tables in timetracking.json come from the same source. Rows mean
 * the same as the feed's (see plugExtra in the web app), so the two join by id(). Pure, so it can be tested.
 */
final class PatchPredictor
{
	/* Spirit trees are left out of runs and reminders, as on the website. */
	private static final String NO_TRACK = "SPIRIT_TREE";
	/* Time Tracking's tab names, as the feed shows them (TAB_LABEL in the web app). */
	private static final Map<String, String> TAB_LABEL = new HashMap<>();
	/* Bird house spaces (Time Tracking's key) and the house built, by (value - 1) / 3. */
	private static final Map<Integer, String> BIRDHOUSE_SPACES = new LinkedHashMap<>();
	private static final String[] BIRDHOUSE_NAMES = {"Bird House", "Oak Bird House", "Willow Bird House", "Teak Bird House", "Maple Bird House",
		"Mahogany Bird House", "Yew Bird House", "Magic Bird House", "Redwood Bird House"};
	private static final int[] BIRDHOUSE_ITEMS = {ItemID.BIRDHOUSE_NORMAL, ItemID.BIRDHOUSE_OAK, ItemID.BIRDHOUSE_WILLOW, ItemID.BIRDHOUSE_TEAK,
		ItemID.BIRDHOUSE_MAPLE, ItemID.BIRDHOUSE_MAHOGANY, ItemID.BIRDHOUSE_YEW, ItemID.BIRDHOUSE_MAGIC, ItemID.BIRDHOUSE_REDWOOD};
	/* A seeded bird house is full after 50 minutes. */
	private static final long BIRDHOUSE_SECS = 50 * 60;

	static
	{
		TAB_LABEL.put("BIRD_HOUSE", "Bird house");
		TAB_LABEL.put("ALLOTMENT", "Allotment");
		TAB_LABEL.put("FLOWER", "Flower");
		TAB_LABEL.put("HERB", "Herb");
		TAB_LABEL.put("TREE", "Tree");
		TAB_LABEL.put("FRUIT_TREE", "Fruit Tree");
		TAB_LABEL.put("HOPS", "Hops");
		TAB_LABEL.put("BUSH", "Bush");
		TAB_LABEL.put("GRAPE", "Grape");
		TAB_LABEL.put("SPECIAL", "Special");
		BIRDHOUSE_SPACES.put(VarPlayerID.BIRDHOUSE_TRANSMIT_A, "Mushroom Meadow (North)");
		BIRDHOUSE_SPACES.put(VarPlayerID.BIRDHOUSE_TRANSMIT_B, "Mushroom Meadow (South)");
		BIRDHOUSE_SPACES.put(VarPlayerID.BIRDHOUSE_TRANSMIT_C, "Verdant Valley (Northeast)");
		BIRDHOUSE_SPACES.put(VarPlayerID.BIRDHOUSE_TRANSMIT_D, "Verdant Valley (Southwest)");
	}

	/** A crop: label, minutes per growth tick, stages, minutes per regrowth tick, harvest stages, item id. */
	private static final class Produce
	{
		String label;
		int tick;
		int stages;
		int regrow;
		int harvest;
		int itemId;
	}

	/** One value range of a patch: what's in it, its state, and its stage (a * value + b). */
	private static final class Range
	{
		int lo;
		int hi;
		String produce;
		String crop;
		int a;
		int b;
	}

	private static final class Impl
	{
		String tab;
		final List<Range> ranges = new ArrayList<>();
	}

	private static final class Spot
	{
		final String region;
		final String name;
		final String impl;

		Spot(String region, String name, String impl)
		{
			this.region = region;
			this.name = name;
			this.impl = impl;
		}
	}

	/** Kind label and group (run). */
	private static final class Kind
	{
		final String label;
		final String group;

		Kind(String label, String group)
		{
			this.label = label;
			this.group = group;
		}
	}

	private final Map<String, Produce> produce = new HashMap<>();
	private final Map<String, Impl> impls = new HashMap<>();
	/* "<regionId>.<varbit>" -> patch, in the table's order. */
	private final Map<String, Spot> patches = new LinkedHashMap<>();
	private final Map<String, Kind> kinds = new HashMap<>();
	private final Map<String, String> implKind = new HashMap<>();
	private final Map<String, String> splitTree = new HashMap<>();

	private PatchPredictor()
	{
	}

	/** Reads timetracking.json from the jar. Call once, off the client thread. */
	static PatchPredictor load(Gson gson)
	{
		try (InputStream in = PatchPredictor.class.getResourceAsStream("timetracking.json"))
		{
			if (in == null)
			{
				throw new IllegalStateException("timetracking.json is missing");
			}
			try (Reader r = new InputStreamReader(in, StandardCharsets.UTF_8))
			{
				return from(gson.fromJson(r, JsonObject.class));
			}
		}
		catch (IOException e)
		{
			throw new IllegalStateException("timetracking.json can't be read", e);
		}
	}

	private static PatchPredictor from(JsonObject j)
	{
		PatchPredictor t = new PatchPredictor();
		for (Map.Entry<String, JsonElement> e : j.getAsJsonObject("produce").entrySet())
		{
			JsonArray a = e.getValue().getAsJsonArray();
			Produce p = new Produce();
			p.label = a.get(0).getAsString();
			p.tick = a.get(1).getAsInt();
			p.stages = a.get(2).getAsInt();
			p.regrow = a.get(3).getAsInt();
			p.harvest = a.get(4).getAsInt();
			p.itemId = a.get(5).isJsonNull() ? 0 : a.get(5).getAsInt();
			t.produce.put(e.getKey(), p);
		}
		for (Map.Entry<String, JsonElement> e : j.getAsJsonObject("impl").entrySet())
		{
			JsonObject o = e.getValue().getAsJsonObject();
			Impl impl = new Impl();
			impl.tab = o.get("tab").getAsString();
			for (JsonElement re : o.getAsJsonArray("r"))
			{
				JsonArray a = re.getAsJsonArray();
				Range r = new Range();
				r.lo = a.get(0).getAsInt();
				r.hi = a.get(1).getAsInt();
				r.produce = a.get(2).getAsString();
				r.crop = a.get(3).getAsString();
				r.a = a.get(4).getAsInt();
				r.b = a.get(5).getAsInt();
				impl.ranges.add(r);
			}
			t.impls.put(e.getKey(), impl);
		}
		for (JsonElement re : j.getAsJsonArray("regions"))
		{
			JsonArray region = re.getAsJsonArray();
			String name = region.get(0).getAsString();
			int id = region.get(1).getAsInt();
			for (JsonElement pe : region.get(2).getAsJsonArray())
			{
				JsonArray p = pe.getAsJsonArray();
				t.patches.put(id + "." + p.get(1).getAsInt(), new Spot(name, p.get(0).getAsString(), p.get(2).getAsString()));
			}
		}
		for (JsonElement ke : j.getAsJsonArray("kinds"))
		{
			JsonArray k = ke.getAsJsonArray();
			t.kinds.put(k.get(0).getAsString(), new Kind(k.get(1).getAsString(), k.get(2).getAsString()));
		}
		for (Map.Entry<String, JsonElement> e : j.getAsJsonObject("implKind").entrySet())
		{
			t.implKind.put(e.getKey(), e.getValue().getAsString());
		}
		for (Map.Entry<String, JsonElement> e : j.getAsJsonObject("splitTree").entrySet())
		{
			t.splitTree.put(e.getKey(), e.getValue().getAsJsonArray().get(1).getAsString());
		}
		return t;
	}

	/** Time Tracking's farming tick offset: minutes and how sure it is, either null when not saved. */
	private static final class Offset
	{
		Long mins;
		Long precision;
	}

	/**
	 * Every saved patch and bird house at nowMs. entries are Time Tracking's keys for this character without the
	 * profile ("11062.4774" = "<value>:<unix seconds>", "birdhouse.1626", "farmTickOffset" ...). Rows come in the
	 * table's order; unknown patches and values are skipped.
	 */
	List<Routines.Patch> predict(Map<String, String> entries, long nowMs)
	{
		long now = Math.floorDiv(nowMs, 1000);
		Offset tt = new Offset();
		tt.mins = number(entries.get("farmTickOffset"));
		tt.precision = number(entries.get("farmTickOffsetPrecision"));
		boolean autoweed = "2".equals(entries.get("autoweed"));
		List<Routines.Patch> rows = new ArrayList<>();
		for (Map.Entry<String, Spot> e : patches.entrySet())
		{
			long[] saved = saved(entries.get(e.getKey()));
			Spot patch = e.getValue();
			if (saved == null || NO_TRACK.equals(patch.impl))
			{
				continue;
			}
			Routines.Patch p = patch(patch, (int) saved[0], saved[1], now, tt, autoweed);
			if (p != null)
			{
				rows.add(p);
			}
		}
		for (Map.Entry<Integer, String> e : BIRDHOUSE_SPACES.entrySet())
		{
			long[] saved = saved(entries.get("birdhouse." + e.getKey()));
			if (saved != null)
			{
				Routines.Patch p = birdhouse(e.getValue(), (int) saved[0], saved[1], nowMs);
				if (p != null)
				{
					rows.add(p);
				}
			}
		}
		return rows;
	}

	/** A spirit tree spot: where it is, what's there (Not planted, Growing, Grown, Diseased, Dead, Unknown), and growth 0..1 (-1 unknown). */
	static final class SpiritTree
	{
		final String region;
		final String state;
		final double progress;

		SpiritTree(String region, String state, double progress)
		{
			this.region = region;
			this.state = state;
			this.progress = progress;
		}
	}

	/**
	 * Every spirit tree spot at nowMs, by place name, whether or not Time Tracking has saved it (Unknown when not). Grown
	 * is the final stage, worked out with the same growth ticks as any patch. These are never farm timers.
	 */
	List<SpiritTree> spiritTrees(Map<String, String> entries, long nowMs)
	{
		long now = Math.floorDiv(nowMs, 1000);
		Offset tt = new Offset();
		tt.mins = number(entries.get("farmTickOffset"));
		tt.precision = number(entries.get("farmTickOffsetPrecision"));
		List<SpiritTree> out = new ArrayList<>();
		for (Map.Entry<String, Spot> e : patches.entrySet())
		{
			Spot spot = e.getValue();
			if (!NO_TRACK.equals(spot.impl))
			{
				continue;
			}
			String region = "Kourend".equals(spot.region) ? "Hosidius" : spot.region;
			long[] saved = saved(entries.get(e.getKey()));
			Routines.Patch p = saved == null ? null : patch(spot, (int) saved[0], saved[1], now, tt, false);
			if (p == null)
			{
				out.add(new SpiritTree(region, "Unknown", -1));
				continue;
			}
			switch (p.state)
			{
				case "ready":
					out.add(new SpiritTree(region, "Grown", 1));
					break;
				case "empty":
					out.add(new SpiritTree(region, "Not planted", -1));
					break;
				case "diseased":
					out.add(new SpiritTree(region, "Diseased", p.progress));
					break;
				case "dead":
					out.add(new SpiritTree(region, "Dead", p.progress));
					break;
				default:
					out.add(new SpiritTree(region, "Growing", p.progress));
			}
		}
		out.sort(Comparator.comparing(t -> t.region));
		return out;
	}

	private Routines.Patch patch(Spot patch, int value, long time, long now, Offset tt, boolean autoweed)
	{
		Impl impl = impls.get(patch.impl);
		Range st = impl == null ? null : stateFor(impl, value);
		if (st == null)
		{
			return null;
		}
		Produce pr = produce.get(st.produce);
		if (pr == null)
		{
			return null;
		}
		int stage = st.a * value + st.b;
		int stages = "HARVESTABLE".equals(st.crop) || "FILLING".equals(st.crop) ? pr.harvest : pr.stages;
		int rate = "GROWING".equals(st.crop) ? pr.tick : "HARVESTABLE".equals(st.crop) ? pr.regrow : 0;
		if (autoweed && "WEEDS".equals(st.produce))
		{
			stage = 0;
			stages = 1;
			rate = 0;
		}
		long done = 0;
		if (rate > 0)
		{
			long tNow = tickTime(rate, 0, now, tt), tThen = tickTime(rate, 0, time, tt);
			long delta = Math.floorDiv(tNow - tThen, rate * 60L);
			done = tickTime(rate, stages - 1 - stage, tThen, tt);
			stage = (int) Math.min(stages - 1, stage + delta);
		}
		boolean weeds = "WEEDS".equals(st.produce) || "SCARECROW".equals(st.produce);
		String status = st.crop;
		if ("GROWING".equals(st.crop) && done != 0 && done <= now)
		{
			status = "HARVESTABLE";
		}
		if (weeds)
		{
			status = "EMPTY";
		}
		String type = splitTree.containsKey(patch.impl) ? splitTree.get(patch.impl) : TAB_LABEL.getOrDefault(impl.tab, impl.tab);
		String crop = weeds ? ("SCARECROW".equals(st.produce) ? "Scarecrow" : "Weeds") : pr.label;
		Routines.Patch p = new Routines.Patch(patch.region, patch.name, type, crop, weeds ? 0 : pr.itemId, done != 0 ? done * 1000 : 0,
			"HARVESTABLE".equals(status));
		finish(p, implKind.getOrDefault(patch.impl, "herb"), status, stage, stages);
		return p;
	}

	/** A bird house; null for an empty one (nothing built, or no seeds yet), which the feed leaves out too. */
	private Routines.Patch birdhouse(String space, int value, long time, long nowMs)
	{
		int type = value > 0 ? (value - 1) / 3 : -1;
		boolean known = type >= 0 && type < BIRDHOUSE_NAMES.length;
		boolean seeded = value > 0 && value % 3 == 0;
		if (!seeded)
		{
			return null;
		}
		long readyAt = (time + BIRDHOUSE_SECS) * 1000;
		boolean ready = readyAt <= nowMs;
		Routines.Patch p = new Routines.Patch("Fossil Island", space, TAB_LABEL.get("BIRD_HOUSE"), known ? BIRDHOUSE_NAMES[type] : "Empty",
			known ? BIRDHOUSE_ITEMS[type] : 0, readyAt, ready);
		finish(p, "birdhouse", ready ? "HARVESTABLE" : "GROWING", ready ? 1 : 0, 2);
		return p;
	}

	/** The fields the feed adds: state, progress, kind, its label and its run. */
	private void finish(Routines.Patch p, String kind, String status, int stage, int stages)
	{
		switch (status)
		{
			case "HARVESTABLE":
				p.state = "ready";
				break;
			case "EMPTY":
				p.state = "empty";
				break;
			case "DISEASED":
				p.state = "diseased";
				break;
			case "DEAD":
				p.state = "dead";
				break;
			default:
				p.state = "growing";
		}
		if (stages > 1)
		{
			p.progress = Math.max(0, Math.min(1, (double) stage / (stages - 1)));
		}
		Kind k = kinds.get(kind);
		p.kind = kind;
		p.kindLabel = k != null ? k.label : p.type;
		p.run = k != null ? k.group : "";
	}

	private static Range stateFor(Impl impl, int value)
	{
		for (Range r : impl.ranges)
		{
			if (value >= r.lo && value <= r.hi)
			{
				return r;
			}
		}
		return null;
	}

	/** The unix second of the farming tick `ticks` ticks after the one at or before t, for a crop growing every tickRate minutes. */
	private static long tickTime(int tickRate, int ticks, long t, Offset tt)
	{
		long off = 0;
		if (tt.precision != null && tt.mins != null && (tt.precision >= tickRate || tt.precision >= 40))
		{
			off = (tt.mins % tickRate) * 60;
		}
		long now = t + off;
		return now - (now % (tickRate * 60L)) + (long) ticks * tickRate * 60 - off;
	}

	/** "<value>:<unix seconds>" as {value, seconds}; null when it doesn't parse or has no time. */
	private static long[] saved(String s)
	{
		if (s == null)
		{
			return null;
		}
		int colon = s.indexOf(':');
		if (colon < 0)
		{
			return null;
		}
		Long value = number(s.substring(0, colon)), time = number(s.substring(colon + 1));
		if (value == null || time == null || time <= 0 || value < Integer.MIN_VALUE || value > Integer.MAX_VALUE)
		{
			return null;
		}
		return new long[]{value, time};
	}

	private static Long number(String s)
	{
		if (s == null)
		{
			return null;
		}
		try
		{
			return Long.parseLong(s.trim());
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}
}

package com.nibtracker;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.StructComposition;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.eventbus.Subscribe;

/**
 * Quests, achievement diaries and combat achievements as full snapshots (in Character Export's file shapes), plus
 * the game values the server asks to watch (combat task bits, league tasks, relics and points).
 */
@Slf4j
@Singleton
class ProgressTracker
{
	/* region, then the easy/medium/hard/elite completion varbits. Karamja's first three count as done at 2. */
	private static final Object[][] DIARIES = {
		{"Ardougne", VarbitID.ARDOUGNE_DIARY_EASY_COMPLETE, VarbitID.ARDOUGNE_DIARY_MEDIUM_COMPLETE, VarbitID.ARDOUGNE_DIARY_HARD_COMPLETE, VarbitID.ARDOUGNE_DIARY_ELITE_COMPLETE},
		{"Desert", VarbitID.DESERT_DIARY_EASY_COMPLETE, VarbitID.DESERT_DIARY_MEDIUM_COMPLETE, VarbitID.DESERT_DIARY_HARD_COMPLETE, VarbitID.DESERT_DIARY_ELITE_COMPLETE},
		{"Falador", VarbitID.FALADOR_DIARY_EASY_COMPLETE, VarbitID.FALADOR_DIARY_MEDIUM_COMPLETE, VarbitID.FALADOR_DIARY_HARD_COMPLETE, VarbitID.FALADOR_DIARY_ELITE_COMPLETE},
		{"Fremennik", VarbitID.FREMENNIK_DIARY_EASY_COMPLETE, VarbitID.FREMENNIK_DIARY_MEDIUM_COMPLETE, VarbitID.FREMENNIK_DIARY_HARD_COMPLETE, VarbitID.FREMENNIK_DIARY_ELITE_COMPLETE},
		{"Kandarin", VarbitID.KANDARIN_DIARY_EASY_COMPLETE, VarbitID.KANDARIN_DIARY_MEDIUM_COMPLETE, VarbitID.KANDARIN_DIARY_HARD_COMPLETE, VarbitID.KANDARIN_DIARY_ELITE_COMPLETE},
		{"Karamja", VarbitID.ATJUN_EASY_DONE, VarbitID.ATJUN_MED_DONE, VarbitID.ATJUN_HARD_DONE, VarbitID.KARAMJA_DIARY_ELITE_COMPLETE},
		{"Kourend & Kebos", VarbitID.KOUREND_DIARY_EASY_COMPLETE, VarbitID.KOUREND_DIARY_MEDIUM_COMPLETE, VarbitID.KOUREND_DIARY_HARD_COMPLETE, VarbitID.KOUREND_DIARY_ELITE_COMPLETE},
		{"Lumbridge & Draynor", VarbitID.LUMBRIDGE_DIARY_EASY_COMPLETE, VarbitID.LUMBRIDGE_DIARY_MEDIUM_COMPLETE, VarbitID.LUMBRIDGE_DIARY_HARD_COMPLETE, VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE},
		{"Morytania", VarbitID.MORYTANIA_DIARY_EASY_COMPLETE, VarbitID.MORYTANIA_DIARY_MEDIUM_COMPLETE, VarbitID.MORYTANIA_DIARY_HARD_COMPLETE, VarbitID.MORYTANIA_DIARY_ELITE_COMPLETE},
		{"Varrock", VarbitID.VARROCK_DIARY_EASY_COMPLETE, VarbitID.VARROCK_DIARY_MEDIUM_COMPLETE, VarbitID.VARROCK_DIARY_HARD_COMPLETE, VarbitID.VARROCK_DIARY_ELITE_COMPLETE},
		{"Western Provinces", VarbitID.WESTERN_DIARY_EASY_COMPLETE, VarbitID.WESTERN_DIARY_MEDIUM_COMPLETE, VarbitID.WESTERN_DIARY_HARD_COMPLETE, VarbitID.WESTERN_DIARY_ELITE_COMPLETE},
		{"Wilderness", VarbitID.WILDERNESS_DIARY_EASY_COMPLETE, VarbitID.WILDERNESS_DIARY_MEDIUM_COMPLETE, VarbitID.WILDERNESS_DIARY_HARD_COMPLETE, VarbitID.WILDERNESS_DIARY_ELITE_COMPLETE},
	};
	private static final String[] DIARY_TIERS = {"easy", "medium", "hard", "elite"};

	/* Combat achievements: one enum of task structs per tier (no named constants for these in RuneLite's API); each
	   struct has the task's id and name. A task is done when bit (id % 32) of CA_TASK_COMPLETED_(id / 32) is set. */
	private static final int[] CA_TIER_ENUMS = {3981, 3982, 3983, 3984, 3985, 3986};
	private static final String[] CA_TIERS = {"Easy", "Medium", "Hard", "Elite", "Master", "Grandmaster"};
	private static final int CA_PARAM_ID = 1306;
	private static final int CA_PARAM_NAME = 1308;
	private static final int[] CA_VARPS = {
		VarPlayerID.CA_TASK_COMPLETED_0, VarPlayerID.CA_TASK_COMPLETED_1, VarPlayerID.CA_TASK_COMPLETED_2, VarPlayerID.CA_TASK_COMPLETED_3,
		VarPlayerID.CA_TASK_COMPLETED_4, VarPlayerID.CA_TASK_COMPLETED_5, VarPlayerID.CA_TASK_COMPLETED_6, VarPlayerID.CA_TASK_COMPLETED_7,
		VarPlayerID.CA_TASK_COMPLETED_8, VarPlayerID.CA_TASK_COMPLETED_9, VarPlayerID.CA_TASK_COMPLETED_10, VarPlayerID.CA_TASK_COMPLETED_11,
		VarPlayerID.CA_TASK_COMPLETED_12, VarPlayerID.CA_TASK_COMPLETED_13, VarPlayerID.CA_TASK_COMPLETED_14, VarPlayerID.CA_TASK_COMPLETED_15,
		VarPlayerID.CA_TASK_COMPLETED_16, VarPlayerID.CA_TASK_COMPLETED_17, VarPlayerID.CA_TASK_COMPLETED_18, VarPlayerID.CA_TASK_COMPLETED_19,
		VarPlayerID.CA_TASK_COMPLETED_20,
	};
	/* Watched values are sent at most this often while they change. */
	private static final int VARS_EVERY_TICKS = 10;
	/* Watch list ids from the server above this are ignored (the game has far fewer varps and varbits). */
	private static final int MAX_VAR_ID = 65536;

	@Inject
	private Client client;

	@Inject
	private NibTrackerConfig config;

	private EventSink sink;
	private final Set<Integer> diaryVarbits = new HashSet<>();
	private final Set<Integer> caVarps = new HashSet<>();
	private final Set<Integer> watchVarps = new HashSet<>();
	private final Set<Integer> watchVarbits = new HashSet<>();
	private final Map<Integer, Integer> changedVarps = new HashMap<>();
	private final Map<Integer, Integer> changedVarbits = new HashMap<>();
	private final Map<String, JsonObject> lastSnapshot = new HashMap<>();
	private boolean questsDirty;
	private boolean diariesDirty;
	private boolean caDirty;
	private boolean varsFull;
	private int ticks;
	private int lastVarsTick;

	void start(EventSink sink)
	{
		this.sink = sink;
		for (Object[] d : DIARIES)
		{
			for (int i = 1; i < d.length; i++)
			{
				diaryVarbits.add((Integer) d[i]);
			}
		}
		for (int v : CA_VARPS)
		{
			caVarps.add(v);
		}
	}

	void login()
	{
		questsDirty = diariesDirty = caDirty = varsFull = true;
		ticks = 0;
	}

	void reset()
	{
		questsDirty = diariesDirty = caDirty = varsFull = false;
		changedVarps.clear();
		changedVarbits.clear();
	}

	/** A chat event the plugin parsed; some mean a snapshot is out of date. */
	void onParsed(String type)
	{
		switch (type)
		{
			case "quest_done":
				questsDirty = true;
				break;
			case "diary_done":
			case "diary_task":
				diariesDirty = true;
				break;
			case "ca_done":
				caDirty = true;
				break;
			default:
		}
	}

	/** The server's watch list changed (or arrived): send every watched value again. */
	void settingsChanged()
	{
		Set<Integer> varps = ids("varps");
		Set<Integer> varbits = ids("varbits");
		if (!varps.equals(watchVarps) || !varbits.equals(watchVarbits))
		{
			watchVarps.clear();
			watchVarps.addAll(varps);
			watchVarbits.clear();
			watchVarbits.addAll(varbits);
			varsFull = true;
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged e)
	{
		int varbit = e.getVarbitId(), varp = e.getVarpId();
		if (varbit != -1)
		{
			if (diaryVarbits.contains(varbit))
			{
				diariesDirty = true;
			}
			if (watchVarbits.contains(varbit))
			{
				changedVarbits.put(varbit, e.getValue());
			}
		}
		else if (varp != -1)
		{
			if (caVarps.contains(varp))
			{
				caDirty = true;
			}
			if (watchVarps.contains(varp))
			{
				changedVarps.put(varp, e.getValue());
			}
		}
	}

	/** Client thread, every game tick. At most one snapshot per tick, so login stays smooth. */
	void tick()
	{
		if (sink == null || !sink.active())
		{
			return;
		}
		ticks++;
		if (ticks < 5)
		{
			return; // let the game finish sending varps after login
		}
		boolean tasks = config.sendTasks();
		if (questsDirty)
		{
			questsDirty = false;
			if (sink.allowed("quests", tasks))
			{
				snapshotQuests();
			}
			return;
		}
		if (diariesDirty)
		{
			diariesDirty = false;
			if (sink.allowed("diaries", tasks))
			{
				snapshotDiaries();
			}
			return;
		}
		if (caDirty)
		{
			caDirty = false;
			if (sink.allowed("combatTasks", tasks))
			{
				snapshotCombatAchievements();
			}
			return;
		}
		if (ticks - lastVarsTick >= VARS_EVERY_TICKS && (varsFull || !changedVarps.isEmpty() || !changedVarbits.isEmpty()))
		{
			lastVarsTick = ticks;
			sendVars();
		}
	}

	private void snapshotQuests()
	{
		JsonArray quests = new JsonArray();
		for (Quest q : Quest.values())
		{
			QuestState s = q.getState(client);
			JsonObject o = new JsonObject();
			o.addProperty("name", q.getName());
			o.addProperty("state", s == null ? "NOT_STARTED" : s.name());
			quests.add(o);
		}
		JsonObject d = new JsonObject();
		d.add("quests", quests);
		emitIfChanged("snapshot_quests", d);
	}

	private void snapshotDiaries()
	{
		JsonObject regions = new JsonObject();
		for (Object[] d : DIARIES)
		{
			JsonObject tiers = new JsonObject();
			for (int i = 0; i < DIARY_TIERS.length; i++)
			{
				int value = client.getVarbitValue((Integer) d[i + 1]);
				boolean karamjaEarly = "Karamja".equals(d[0]) && i < 3;
				JsonObject t = new JsonObject();
				t.addProperty("complete", karamjaEarly ? value >= 2 : value >= 1);
				t.add("tasks", new JsonArray());
				tiers.add(DIARY_TIERS[i], t);
			}
			regions.add((String) d[0], tiers);
		}
		JsonObject data = new JsonObject();
		data.add("diaries", regions);
		emitIfChanged("snapshot_diaries", data);
	}

	private void snapshotCombatAchievements()
	{
		JsonObject tiers = new JsonObject();
		int named = 0;
		for (int i = 0; i < CA_TIER_ENUMS.length; i++)
		{
			EnumComposition en = client.getEnum(CA_TIER_ENUMS[i]);
			if (en == null)
			{
				continue;
			}
			JsonArray tasks = new JsonArray();
			for (int structId : en.getIntVals())
			{
				StructComposition s = client.getStructComposition(structId);
				String name = s == null ? null : s.getStringValue(CA_PARAM_NAME);
				if (name == null || name.isEmpty())
				{
					continue;
				}
				int id = s.getIntValue(CA_PARAM_ID);
				JsonObject t = new JsonObject();
				t.addProperty("id", id);
				t.addProperty("name", name);
				t.addProperty("complete", caDone(id));
				tasks.add(t);
				named++;
			}
			JsonObject tier = new JsonObject();
			tier.addProperty("name", CA_TIERS[i]);
			tier.add("tasks", tasks);
			tiers.add(CA_TIERS[i].toLowerCase(), tier);
		}
		if (named == 0)
		{
			log.debug("Combat achievement structs not readable; the raw task bits are still sent as watched values");
			return;
		}
		JsonObject d = new JsonObject();
		d.add("tiers", tiers);
		emitIfChanged("snapshot_combat_achievements", d);
	}

	private boolean caDone(int id)
	{
		int word = id / 32;
		return id >= 0 && word < CA_VARPS.length && ((client.getVarpValue(CA_VARPS[word]) >> (id % 32)) & 1) == 1;
	}

	private void sendVars()
	{
		if (!sink.allowed("vars", true))
		{
			changedVarps.clear();
			changedVarbits.clear();
			varsFull = false;
			return;
		}
		JsonObject varps = new JsonObject();
		JsonObject varbits = new JsonObject();
		if (varsFull)
		{
			int varpCount = client.getVarps().length;
			for (int id : watchVarps)
			{
				if (id < varpCount)
				{
					varps.addProperty(String.valueOf(id), client.getVarpValue(id));
				}
			}
			for (int id : watchVarbits)
			{
				try
				{
					varbits.addProperty(String.valueOf(id), client.getVarbitValue(id));
				}
				catch (RuntimeException ex)
				{
					// Not a varbit in this game version: skip it.
				}
			}
		}
		else
		{
			changedVarps.forEach((id, v) -> varps.addProperty(String.valueOf(id), v));
			changedVarbits.forEach((id, v) -> varbits.addProperty(String.valueOf(id), v));
		}
		boolean full = varsFull;
		varsFull = false;
		changedVarps.clear();
		changedVarbits.clear();
		if (varps.size() == 0 && varbits.size() == 0)
		{
			return;
		}
		JsonObject d = new JsonObject();
		d.addProperty("full", full);
		d.add("varps", varps);
		d.add("varbits", varbits);
		sink.emit("vars", d);
	}

	/** Snapshots are only sent when they differ from the last one (hopping worlds re-reads them). */
	private void emitIfChanged(String type, JsonObject d)
	{
		if (!d.equals(lastSnapshot.get(type)))
		{
			lastSnapshot.put(type, d);
			sink.emit(type, d);
		}
	}

	private Set<Integer> ids(String key)
	{
		return sink == null ? new HashSet<>() : watchIds(sink.settings(), key, MAX_VAR_ID, 500);
	}

	/** The server's watch list under key ("varps", "varbits", "containers"): up to limit plain ids from 0 to below max. */
	static Set<Integer> watchIds(JsonObject settings, String key, int max, int limit)
	{
		Set<Integer> out = new HashSet<>();
		JsonElement w = settings.get("watch");
		if (w == null || !w.isJsonObject())
		{
			return out;
		}
		JsonElement list = w.getAsJsonObject().get(key);
		if (list == null || !list.isJsonArray())
		{
			return out;
		}
		for (JsonElement e : list.getAsJsonArray())
		{
			// Only plain ids in the game's range; anything else from the server is ignored.
			if (e.isJsonPrimitive() && e.getAsJsonPrimitive().isNumber() && out.size() < limit)
			{
				int id = e.getAsInt();
				if (id >= 0 && id < max)
				{
					out.add(id);
				}
			}
		}
		return out;
	}
}

package com.nibtracker;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

/**
 * Daily tasks and farm timers from the server's settings (dailies, farm), and the time maths for showing them. The
 * server sends plain data; the plugin only counts down. Kept free of client calls so it can be unit tested.
 */
final class Routines
{
	private Routines()
	{
	}

	static final long MINUTE = 60_000L;
	static final long DAY = 24 * 60 * MINUTE;
	/* The patch states Nib Tracker sends. Anything else falls back to ready or growing. */
	private static final List<String> STATES = Arrays.asList("empty", "growing", "ready", "diseased", "dead", "unknown");

	/** A daily task switched on in Nib Tracker. dueAt is when it's next due (epoch ms), or 0 when it's due now. */
	static final class Daily
	{
		final String id;
		final String label;
		final String cadence;
		final int every;
		final long dueAt;
		/* What to do or collect, from Nib Tracker, or empty. */
		String how = "";
		/* The built-in task it is (zaff_staves...), so the game can tick it off; empty for a task the player named. */
		String key = "";
		/* Its icon item, from Nib Tracker; 0 when the feed has none (see DailySignals.icon). */
		int itemId;
		/* For a "condition" task (Miscellania): whether it's due now. Null for every other cadence. */
		Boolean due;

		Daily(String id, String label, String cadence, int every, long dueAt)
		{
			this.id = id;
			this.label = label;
			this.cadence = cadence;
			this.every = every;
			this.dueAt = dueAt;
		}

		boolean condition()
		{
			return "condition".equals(cadence);
		}
	}

	/** A farm patch or bird house with a timer. readyAt is epoch ms, or 0 when not known. */
	static final class Patch
	{
		final String region;
		final String name;
		final String type;
		final String crop;
		final int itemId;
		final long readyAt;
		final boolean ready;
		/* The best way there with what's in your bank, and how to use it, from Nib Tracker; empty when unknown. */
		String travel = "";
		String travelHow = "";
		/* Its kind (herb, fruit_tree...) and label (Herbs), its run (patches done together), its stop in that run's order
		   (1 = first, 0 = not planned), and the teleport's kind (ITEM, SPELLBOOK, FAIRY_RING...) and item, from Nib Tracker. */
		String kind = "";
		String kindLabel = "";
		String run = "";
		int order;
		/* Its stop in the one run over every kind of patch (see Stop), 0 when it has none. */
		int stop;
		String travelCat = "";
		String travelItem = "";
		/* empty, growing, ready, diseased, dead or unknown, from Nib Tracker; "growing" or "ready" when the feed has none. */
		String state;
		/* How far it has grown, 0 to 1; -1 when unknown. */
		double progress = -1;

		Patch(String region, String name, String type, String crop, int itemId, long readyAt, boolean ready)
		{
			this.region = region;
			this.name = name;
			this.type = type;
			this.crop = crop;
			this.itemId = itemId;
			this.readyAt = readyAt;
			this.ready = ready;
			this.state = ready ? "ready" : "growing";
		}

		boolean readyAt(long now)
		{
			return ready || (readyAt > 0 && readyAt <= now);
		}

		/** True when it's diseased or dead and needs a visit. */
		boolean needsAttention()
		{
			return "diseased".equals(state) || "dead".equals(state);
		}

		/** Which patch this is: region, name and kind. */
		String id()
		{
			return region + "|" + name + "|" + kind;
		}
	}

	/**
	 * A stop in the one farm run over every kind of patch, as Nib Tracker's planner works it out with your bank: the
	 * place (the Farming Guild's herb and trees are one stop) and the teleports you can use to get there, best first.
	 */
	static final class Stop
	{
		final int stop;
		final String place;
		final List<Tele> teles = new ArrayList<>();

		Stop(int stop, String place)
		{
			this.stop = stop;
			this.place = place;
		}
	}

	/** A teleport: its name ("Ardougne cloak 2"), how to use it, its kind (ITEM, SPELLBOOK, FAIRY_RING...) and item. */
	static final class Tele
	{
		final String travel;
		final String how;
		final String cat;
		final String item;

		Tele(String travel, String how, String cat, String item)
		{
			this.travel = travel;
			this.how = how;
			this.cat = cat;
			this.item = item;
		}
	}

	/** A live bingo board of the player's group: its name, size (3 to 5 a side) and tiles, as Nib Tracker sends them. */
	static final class Board
	{
		final String id;
		final String name;
		final int size;
		/* size * size slots, row by row; a slot the feed didn't fill is null. */
		final Tile[] tiles;

		Board(String id, String name, int size)
		{
			this.id = id;
			this.name = name;
			this.size = size;
			this.tiles = new Tile[size * size];
		}
	}

	/** A tile: what it asks for, its picture (an item, or a skill for an XP tile), and whether the team has it. */
	static final class Tile
	{
		final String label;
		final int itemId;
		final String skill;
		final boolean done;

		Tile(String label, int itemId, String skill, boolean done)
		{
			this.label = label;
			this.itemId = itemId;
			this.skill = skill;
			this.done = done;
		}
	}

	/** Up to 3 boards: each 3 to 5 a side (bigger ones don't fit the panel), tiles placed by idx; anything out of range is left out. */
	static List<Board> bingo(JsonElement e)
	{
		List<Board> out = new ArrayList<>();
		for (JsonObject o : objects(e, 3))
		{
			int size = (int) num(o, "size");
			String name = str(o, "name");
			if (size < 3 || size > 5 || name.isEmpty())
			{
				continue;
			}
			// The id goes into the board's link, so only a plain one (letters, digits, dashes) is kept.
			String id = str(o, "id").matches("[A-Za-z0-9-]{1,40}") ? str(o, "id") : "";
			Board b = new Board(id, name.length() > 60 ? name.substring(0, 60) : name, size);
			for (JsonObject t : objects(o.get("tiles"), 25))
			{
				int idx = (int) num(t, "idx");
				String label = str(t, "label");
				if (idx >= 0 && idx < b.tiles.length && !label.isEmpty() && t.has("idx"))
				{
					JsonElement done = t.get("done");
					b.tiles[idx] = new Tile(label.length() > 80 ? label.substring(0, 80) : label, (int) num(t, "itemId"), str(t, "skill"),
						done != null && done.isJsonPrimitive() && done.getAsJsonPrimitive().isBoolean() && done.getAsBoolean());
				}
			}
			out.add(b);
		}
		return out;
	}

	static List<Stop> route(JsonElement e)
	{
		List<Stop> out = new ArrayList<>();
		for (JsonObject o : objects(e, 60))
		{
			int n = (int) num(o, "stop");
			String place = str(o, "place");
			if (n > 0 && !place.isEmpty())
			{
				Stop s = new Stop(n, place);
				for (JsonObject t : objects(o.get("teles"), 6))
				{
					if (!str(t, "travel").isEmpty())
					{
						s.teles.add(new Tele(str(t, "travel"), str(t, "how"), str(t, "cat"), str(t, "item")));
					}
				}
				out.add(s);
			}
		}
		return out;
	}

	static List<Daily> dailies(JsonElement e)
	{
		List<Daily> out = new ArrayList<>();
		for (JsonObject o : objects(e, 40))
		{
			String id = str(o, "id"), label = str(o, "label"), cadence = str(o, "cadence");
			if (!id.isEmpty() && !label.isEmpty())
			{
				Daily d = new Daily(id, label, cadence, (int) Math.max(1, num(o, "every")), (long) num(o, "dueAt"));
				d.how = str(o, "how");
				d.key = str(o, "key");
				d.itemId = (int) num(o, "itemId");
				if (d.condition())
				{
					JsonElement due = o.get("due");
					d.due = due != null && due.isJsonPrimitive() && due.getAsJsonPrimitive().isBoolean() && due.getAsBoolean();
				}
				out.add(d);
			}
		}
		return out;
	}

	static List<Patch> farm(JsonElement e)
	{
		List<Patch> out = new ArrayList<>();
		for (JsonObject o : objects(e, 150))
		{
			String region = str(o, "region");
			if (!region.isEmpty())
			{
				Patch p = new Patch(region, str(o, "name"), str(o, "type"), str(o, "crop"), (int) num(o, "itemId"), (long) num(o, "readyAt"),
					o.has("ready") && o.get("ready").isJsonPrimitive() && o.get("ready").getAsBoolean());
				p.travel = str(o, "travel");
				p.travelHow = str(o, "travelHow");
				p.kind = str(o, "kind");
				p.kindLabel = str(o, "kindLabel").isEmpty() ? p.type : str(o, "kindLabel");
				p.run = str(o, "run");
				p.order = (int) num(o, "order");
				p.stop = (int) num(o, "stop");
				p.travelCat = str(o, "travelCat");
				p.travelItem = str(o, "travelItem");
				String state = str(o, "state");
				if (STATES.contains(state))
				{
					p.state = state;
				}
				if (o.has("progress") && o.get("progress").isJsonPrimitive() && o.get("progress").getAsJsonPrimitive().isNumber())
				{
					p.progress = Math.max(0, Math.min(1, num(o, "progress")));
				}
				out.add(p);
			}
		}
		return out;
	}

	/** When a task done at `now` is next due, as Nib Tracker works it out: daily ones at the next UTC midnight(s). */
	static long nextDue(Daily d, long now)
	{
		if ("interval_min".equals(d.cadence))
		{
			return now + d.every * MINUTE;
		}
		return (now / DAY) * DAY + d.every * DAY;
	}

	/** A duration in a few characters: "34m", "5h 12m", "2d 3h" (under a minute shows as "1m"). */
	static String left(long ms)
	{
		long m = Math.max(1, (ms + MINUTE - 1) / MINUTE);
		if (m < 60)
		{
			return m + "m";
		}
		long h = m / 60;
		if (h < 24)
		{
			return h + "h " + (m % 60) + "m";
		}
		return (h / 24) + "d " + (h % 24) + "h";
	}

	/**
	 * A region's line: how many are ready, or how long until the next growing one is; with neither, Growing, Diseased,
	 * Dead, Empty or Unknown (a timer on a patch that isn't growing means nothing).
	 */
	static String summary(List<Patch> patches, long now)
	{
		long ready = patches.stream().filter(p -> FarmRows.ready(p, now)).count();
		if (ready > 0)
		{
			return ready + " ready";
		}
		Patch next = FarmRows.next(patches, now);
		return next == null ? FarmRows.idle(patches) : "next " + left(next.readyAt - now);
	}

	private static List<JsonObject> objects(JsonElement e, int max)
	{
		List<JsonObject> out = new ArrayList<>();
		if (e != null && e.isJsonArray())
		{
			for (JsonElement x : (JsonArray) e)
			{
				if (x.isJsonObject() && out.size() < max)
				{
					out.add(x.getAsJsonObject());
				}
			}
		}
		return out;
	}

	private static String str(JsonObject o, String k)
	{
		JsonElement v = o.get(k);
		return v != null && v.isJsonPrimitive() ? v.getAsString() : "";
	}

	private static double num(JsonObject o, String k)
	{
		JsonElement v = o.get(k);
		return v != null && v.isJsonPrimitive() && v.getAsJsonPrimitive().isNumber() ? v.getAsDouble() : 0;
	}
}

package com.nibtracker;

import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.util.Collection;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.DrawManager;
import net.runelite.client.util.ImageUtil;

/**
 * Proof pictures for bingo drop tiles. When a drop or collection log slot matches an item on one of the player's live
 * drop tiles (the server lists them in settings.screenshotItems), the next game frame is captured. Once the event
 * itself has reached the server, the picture is uploaded against it; the server attaches it to the tile submission.
 * Pictures that no tile wants are thrown away by the server.
 */
@Slf4j
@Singleton
class ScreenshotService
{
	private static final int MAX_WIDTH = 1280;
	private static final int MAX_HELD = 5;

	@Inject
	private DrawManager drawManager;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private NibTrackerApi api;

	private final Map<String, byte[]> ready = new ConcurrentHashMap<>();
	private final Set<String> capturing = ConcurrentHashMap.newKeySet();
	private final Set<String> delivered = ConcurrentHashMap.newKeySet();
	private volatile String key;

	/** Client thread. Captures the next frame for this event. */
	void capture(String eventId, String pluginKey)
	{
		if (eventId == null || capturing.size() + ready.size() >= MAX_HELD)
		{
			return;
		}
		key = pluginKey;
		capturing.add(eventId);
		drawManager.requestNextFrameListener(img -> executor.execute(() -> {
			byte[] jpg = encode(img);
			capturing.remove(eventId);
			if (jpg == null)
			{
				delivered.remove(eventId);
				return;
			}
			if (delivered.remove(eventId))
			{
				api.uploadScreenshot(key, eventId, jpg);
			}
			else
			{
				ready.put(eventId, jpg);
			}
		}));
	}

	/** Any thread. These events reached the server; upload their pictures (now, or once they're encoded). */
	void eventsDelivered(Collection<String> eventIds)
	{
		for (String id : eventIds)
		{
			byte[] jpg = ready.remove(id);
			if (jpg != null)
			{
				api.uploadScreenshot(key, id, jpg);
			}
			else if (capturing.contains(id))
			{
				delivered.add(id);
			}
		}
	}

	void reset()
	{
		ready.clear();
		capturing.clear();
		delivered.clear();
	}

	private static byte[] encode(Image img)
	{
		try
		{
			BufferedImage src = ImageUtil.bufferedImageFromImage(img);
			int w = src.getWidth(), h = src.getHeight();
			if (w > MAX_WIDTH)
			{
				h = h * MAX_WIDTH / w;
				w = MAX_WIDTH;
			}
			BufferedImage rgb = new BufferedImage(w, h, BufferedImage.TYPE_INT_RGB);
			Graphics2D g = rgb.createGraphics();
			g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			g.drawImage(src, 0, 0, w, h, null);
			g.dispose();
			ByteArrayOutputStream out = new ByteArrayOutputStream();
			ImageIO.write(rgb, "jpg", out);
			return out.toByteArray();
		}
		catch (Exception e)
		{
			log.debug("Nib Tracker couldn't encode a screenshot", e);
			return null;
		}
	}
}

package com.nibtracker;

import com.google.gson.JsonObject;
import java.util.List;
import java.util.Objects;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.eventbus.Subscribe;

/** The current slayer task, points and streaks, read from the same game values RuneLite's Slayer plugin reads. */
@Singleton
class SlayerTracker
{
	/* Game database tables and columns for task names and locations (as RuneLite's Slayer plugin uses them). The boss task
	   id has no named constant in RuneLite's API. */
	private static final int TASK_BOSS_ID = 98;
	/* While a task counts down, progress is sent at most this often. */
	private static final int PROGRESS_EVERY_TICKS = 50;

	@Inject
	private Client client;

	@Inject
	private NibTrackerConfig config;

	private EventSink sink;
	private boolean dirty;
	private JsonObject last;
	private int lastStreak = -1;
	private int ticks;
	private int lastSentTick = -PROGRESS_EVERY_TICKS;
	/* The task as last read, for the Goals panel (whether or not Slayer is being sent), and a count of changes to it. */
	private JsonObject current;
	private int version;

	void start(EventSink sink)
	{
		this.sink = sink;
	}

	void login()
	{
		dirty = true;
		last = null;
		lastStreak = -1;
	}

	void reset()
	{
		dirty = false;
		current = null;
		version++;
	}

	/** Client thread. The current task ({ name, remaining, amount, location }), or null before it's been read. */
	JsonObject current()
	{
		return current;
	}

	/** Goes up whenever the current task changes, so the Goals panel knows to update. */
	int version()
	{
		return version;
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged e)
	{
		int varp = e.getVarpId(), varbit = e.getVarbitId();
		if (varbit == -1 && (varp == VarPlayerID.SLAYER_COUNT || varp == VarPlayerID.SLAYER_TARGET || varp == VarPlayerID.SLAYER_AREA
			|| varp == VarPlayerID.SLAYER_COUNT_ORIGINAL))
		{
			dirty = true;
		}
		else if (varbit == VarbitID.SLAYER_POINTS || varbit == VarbitID.SLAYER_TASKS_COMPLETED || varbit == VarbitID.SLAYER_MASTER
			|| varbit == VarbitID.SLAYER_TARGET_BOSSID || varbit == VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED)
		{
			dirty = true;
		}
	}

	void tick()
	{
		ticks++;
		if (!dirty || sink == null || !sink.active())
		{
			return;
		}
		JsonObject now = read();
		if (!now.equals(current))
		{
			current = now;
			version++;
		}
		if (!sink.allowed("slayer", config.sendSlayer()))
		{
			dirty = false;
			return;
		}
		int streak = client.getVarbitValue(VarbitID.SLAYER_TASKS_COMPLETED);
		if (lastStreak >= 0 && streak > lastStreak)
		{
			JsonObject d = new JsonObject();
			d.addProperty("streak", streak);
			d.addProperty("points", client.getVarbitValue(VarbitID.SLAYER_POINTS));
			d.addProperty("wildStreak", client.getVarbitValue(VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED));
			sink.emit("slayer_done", d);
		}
		lastStreak = streak;

		if (now.equals(last))
		{
			dirty = false;
			return;
		}
		boolean newTask = last == null || !Objects.equals(str(last, "name"), str(now, "name"));
		boolean finished = now.get("remaining").getAsInt() == 0;
		if (!newTask && !finished && ticks - lastSentTick < PROGRESS_EVERY_TICKS)
		{
			return; // stays dirty: sent once the wait is up
		}
		dirty = false;
		last = now;
		lastSentTick = ticks;
		sink.emit("slayer_state", now);
	}

	private JsonObject read()
	{
		int remaining = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
		int taskId = client.getVarpValue(VarPlayerID.SLAYER_TARGET);
		JsonObject d = new JsonObject();
		d.addProperty("remaining", Math.max(0, remaining));
		d.addProperty("amount", client.getVarpValue(VarPlayerID.SLAYER_COUNT_ORIGINAL));
		d.addProperty("taskId", taskId);
		d.addProperty("master", client.getVarbitValue(VarbitID.SLAYER_MASTER));
		d.addProperty("points", client.getVarbitValue(VarbitID.SLAYER_POINTS));
		d.addProperty("streak", client.getVarbitValue(VarbitID.SLAYER_TASKS_COMPLETED));
		d.addProperty("wildStreak", client.getVarbitValue(VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED));
		if (remaining > 0)
		{
			String name = taskId == TASK_BOSS_ID
				? field(DBTableID.SlayerTaskSublist.ID, DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID, client.getVarbitValue(VarbitID.SLAYER_TARGET_BOSSID), DBTableID.SlayerTaskSublist.COL_TASK)
				: field(DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID, taskId, DBTableID.SlayerTask.COL_NAME_UPPERCASE);
			if (name != null)
			{
				d.addProperty("name", name);
			}
			int area = client.getVarpValue(VarPlayerID.SLAYER_AREA);
			String location = area > 0 ? field(DBTableID.SlayerArea.ID, DBTableID.SlayerArea.COL_AREA_ID, area, DBTableID.SlayerArea.COL_AREA_NAME_IN_HELPER) : null;
			if (location != null)
			{
				d.addProperty("location", location);
			}
		}
		return d;
	}

	private String field(int table, int column, int value, int nameColumn)
	{
		try
		{
			List<Integer> rows = client.getDBRowsByValue(table, column, 0, value);
			if (rows == null || rows.isEmpty())
			{
				return null;
			}
			Object[] f = client.getDBTableField(rows.get(0), nameColumn, 0);
			return f != null && f.length > 0 && f[0] instanceof String ? (String) f[0] : null;
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	private static String str(JsonObject o, String key)
	{
		return o.has(key) ? o.get(key).getAsString() : null;
	}
}

package com.nibtracker;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class ChatParserTest
{
	@Test
	public void killCounts()
	{
		ChatParser.Parsed p = ChatParser.parse("Your Zulrah kill count is: 1,512.");
		assertEquals("kc", p.type);
		assertEquals("Zulrah", p.data.get("boss").getAsString());
		assertEquals(1512, p.data.get("count").getAsInt());

		assertEquals("Chambers of Xeric", ChatParser.parse("Your completed Chambers of Xeric count is: 50.").data.get("boss").getAsString());
		assertEquals("Barrows", ChatParser.parse("Your Barrows chest count is: 12.").data.get("boss").getAsString());
		assertEquals("Wintertodt", ChatParser.parse("Your subdued Wintertodt count is: 300.").data.get("boss").getAsString());
	}

	@Test
	public void collectionLogAndPets()
	{
		ChatParser.Parsed p = ChatParser.parse("New item added to your collection log: Dragon pickaxe");
		assertEquals("clog_new", p.type);
		assertEquals("Dragon pickaxe", p.data.get("item").getAsString());

		p = ChatParser.parse("You have a funny feeling like you would have been followed...");
		assertEquals("pet", p.type);
		assertTrue(p.data.get("duplicate").getAsBoolean());
	}

	@Test
	public void tasks()
	{
		ChatParser.Parsed p = ChatParser.parse("Congratulations, you've completed an elite combat task: Perfect Zulrah (5 points).");
		assertEquals("ca_done", p.type);
		assertEquals("elite", p.data.get("tier").getAsString());
		assertEquals("Perfect Zulrah", p.data.get("task").getAsString());

		assertEquals("Dragon Slayer I", ChatParser.parse("Congratulations, you've completed a quest: Dragon Slayer I").data.get("quest").getAsString());
	}

	@Test
	public void cluesAndTimes()
	{
		ChatParser.Parsed p = ChatParser.parse("You have completed 1,204 medium Treasure Trails.");
		assertEquals("clue_done", p.type);
		assertEquals("medium", p.data.get("tier").getAsString());
		assertEquals(1204, p.data.get("count").getAsInt());

		p = ChatParser.parse("Fight duration: 1:23.40. Personal best: 1:10.00");
		assertEquals("boss_time", p.type);
		assertEquals(83.4, p.data.get("seconds").getAsDouble(), 0.001);
		assertEquals(70.0, p.data.get("pbSeconds").getAsDouble(), 0.001);
		assertFalse(p.data.get("newPb").getAsBoolean());

		p = ChatParser.parse("Challenge duration: 25:01 (new personal best)");
		assertEquals("Challenge", p.data.get("label").getAsString());
		assertEquals(1501.0, p.data.get("seconds").getAsDouble(), 0.001);
		assertTrue(p.data.get("newPb").getAsBoolean());

		assertEquals(3723.0, ChatParser.seconds("1:02:03"), 0.001);
	}

	@Test
	public void leaguesDiariesAndSlayer()
	{
		ChatParser.Parsed p = ChatParser.parse("Congratulations, you've completed a hard task: Kill a Demonic Gorilla.");
		assertEquals("league_task", p.type);
		assertEquals("hard", p.data.get("tier").getAsString());
		assertEquals("Kill a Demonic Gorilla", p.data.get("task").getAsString());

		// A combat task is still a combat task, not a league task.
		assertEquals("ca_done", ChatParser.parse("Congratulations, you've completed a hard combat task: Whack-a-Mole (3 points).").type);

		p = ChatParser.parse("Well done! You have completed an easy task in the Ardougne area. Your Achievement Diary has been updated.");
		assertEquals("diary_task", p.type);
		assertEquals("Ardougne", p.data.get("region").getAsString());

		p = ChatParser.parse("Congratulations! You have completed all of the medium tasks in the Varrock area. Speak to Toby to claim your reward.");
		assertEquals("diary_done", p.type);
		assertEquals("medium", p.data.get("tier").getAsString());

		p = ChatParser.parse("You've completed 123 tasks and received 15 points, giving you a total of 1,234; return to a Slayer master.");
		assertEquals("slayer_task_done", p.type);
		assertEquals(123, p.data.get("streak").getAsInt());
		assertEquals(1234, p.data.get("total").getAsInt());
	}

	@Test
	public void accountIdIsStableAndOneWay()
	{
		String a = NibTrackerPlugin.accountId(123456789L);
		assertEquals(a, NibTrackerPlugin.accountId(123456789L));
		assertEquals(32, a.length());
		assertFalse(a.contains("123456789"));
	}

	@Test
	public void ignoresOtherLines()
	{
		assertNull(ChatParser.parse("Welcome to Old School RuneScape."));
		assertNull(ChatParser.parse(""));
	}
}

package com.nibtracker;

import net.runelite.api.Item;
import org.junit.Test;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class ContainerTrackerTest
{
	private static final int PLACEHOLDER = 9999;

	private static boolean owned(int id, int quantity)
	{
		return ContainerTracker.owned(new Item(id, quantity), i -> i == PLACEHOLDER ? 14401 : -1);
	}

	@Test
	public void realItemsCount()
	{
		assertTrue(owned(4151, 1));
	}

	@Test
	public void placeholdersAndEmptySlotsDont()
	{
		assertFalse(owned(PLACEHOLDER, 0));
		assertFalse(owned(PLACEHOLDER, 1)); // a placeholder id never counts, whatever its quantity
		assertFalse(owned(4151, 0));
		assertFalse(owned(-1, 1));
	}
}

package com.nibtracker;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.IntUnaryOperator;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;

public class DailySignalsTest
{
	private static IntUnaryOperator vars(Map<Integer, Integer> m)
	{
		return id -> m.getOrDefault(id, 0);
	}

	private static final IntUnaryOperator NONE = id -> 0;

	private static Routines.Daily daily(String id, String key)
	{
		Routines.Daily d = new Routines.Daily(id, id, "daily", 1, 0);
		d.key = key;
		return d;
	}

	@Test
	public void zaffClaimedIsDone()
	{
		Map<Integer, Integer> vb = new HashMap<>();
		vb.put(VarbitID.ZAFF_LAST_CLAIMED, 1);
		Set<String> c = DailySignals.claimedToday(vars(vb), NONE);
		assertTrue(c.contains("zaff_staves"));
		assertFalse(c.contains("bert_sand"));
	}

	@Test
	public void slimeNeedsTheDiaryCap()
	{
		Map<Integer, Integer> vb = new HashMap<>();
		vb.put(VarbitID.MORYTANIA_DIARY_MEDIUM_COMPLETE, 1);
		vb.put(VarbitID.MORYTANIA_DIARY_HARD_COMPLETE, 1);
		vb.put(VarbitID.MORYTANIA_SLIME_CLAIMED, 13);
		assertFalse(DailySignals.claimedToday(vars(vb), NONE).contains("robin_slime"));
		vb.put(VarbitID.MORYTANIA_SLIME_CLAIMED, 26);
		assertTrue(DailySignals.claimedToday(vars(vb), NONE).contains("robin_slime"));
		// No diary, nothing to claim: never done.
		assertFalse(DailySignals.claimedToday(NONE, NONE).contains("robin_slime"));
	}

	@Test
	public void herbBoxesAt15()
	{
		Map<Integer, Integer> vb = new HashMap<>();
		vb.put(VarbitID.NZONE_HERBBOXES_PURCHASED, 14);
		assertFalse(DailySignals.claimedToday(vars(vb), NONE).contains("nmz_herb_boxes"));
		vb.put(VarbitID.NZONE_HERBBOXES_PURCHASED, 15);
		assertTrue(DailySignals.claimedToday(vars(vb), NONE).contains("nmz_herb_boxes"));
	}

	@Test
	public void explorersRingAt30Alchs()
	{
		Map<Integer, Integer> vb = new HashMap<>();
		vb.put(VarbitID.LUMBRIDGE_DIARY_EASY_COMPLETE, 1);
		vb.put(VarbitID.LUMBRIDGE_FREE_ALCHS, 29);
		assertFalse(DailySignals.claimedToday(vars(vb), NONE).contains("explorers_ring"));
		vb.put(VarbitID.LUMBRIDGE_FREE_ALCHS, 30);
		assertTrue(DailySignals.claimedToday(vars(vb), NONE).contains("explorers_ring"));
		vb.put(VarbitID.LUMBRIDGE_DIARY_EASY_COMPLETE, 0);
		assertFalse(DailySignals.claimedToday(vars(vb), NONE).contains("explorers_ring"));
	}

	@Test
	public void tearsPlayedWhenCollectingEndsAfterTears()
	{
		assertTrue(DailySignals.tearsPlayed(1, 0, true));
		// Collecting ending with no tears seen this game: not counted.
		assertFalse(DailySignals.tearsPlayed(1, 0, false));
		assertFalse(DailySignals.tearsPlayed(0, 1, true));
		assertFalse(DailySignals.tearsPlayed(0, 0, true));
	}

	private static final long NOW = 20_000 * Routines.DAY + 12 * 60 * Routines.MINUTE;

	@Test
	public void approvalDecaysByTheDay()
	{
		assertEquals(100, DailySignals.estimatedApproval(127, NOW, NOW, false), 0.001);
		assertEquals(87.5, DailySignals.estimatedApproval(127, NOW - 5 * Routines.DAY, NOW, false), 0.001);
		assertEquals(95, DailySignals.estimatedApproval(127, NOW - 5 * Routines.DAY, NOW, true), 0.001);
		assertEquals(0, DailySignals.estimatedApproval(10, NOW - 100 * Routines.DAY, NOW, false), 0.001);
	}

	@Test
	public void miscellaniaBelow90IsDue()
	{
		long fiveDays = NOW - 5 * Routines.DAY;
		assertEquals(Boolean.FALSE, DailySignals.miscellaniaDue(true, 127, NOW, NOW, false));
		assertEquals(Boolean.TRUE, DailySignals.miscellaniaDue(true, 127, fiveDays, NOW, false));
		assertEquals(Boolean.FALSE, DailySignals.miscellaniaDue(true, 127, fiveDays, NOW, true));
		assertEquals(Boolean.TRUE, DailySignals.miscellaniaDue(true, 100, NOW, NOW, false));
		assertNull(DailySignals.miscellaniaDue(false, 127, NOW, NOW, false)); // not unlocked
		assertNull(DailySignals.miscellaniaDue(true, null, 0, NOW, false)); // never read
	}

	@Test
	public void readingTrustedInTheKingdomOrWhenBothSet()
	{
		assertTrue(DailySignals.trusted(true, 0, 0));
		assertTrue(DailySignals.trusted(false, 120, 50_000));
		assertFalse(DailySignals.trusted(false, 120, 0)); // outside, coffer 0: ignored
		assertFalse(DailySignals.trusted(false, 0, 50_000));
	}

	@Test
	public void approvalNewsOnlyWhenTheVarbitMoves()
	{
		long yesterday = NOW - Routines.DAY;
		// Ticked by hand (saved 127) with the varbit still at its old 100: the same 100 again is not news.
		assertFalse(DailySignals.approvalNews(false, 100, 100, 127, NOW, NOW));
		assertFalse(DailySignals.approvalNews(false, 100, 100, 127, yesterday, NOW));
		// Outside, the raw value moved: news.
		assertTrue(DailySignals.approvalNews(false, 110, 100, 127, NOW, NOW));
		// Nothing seen yet (first run): only remembered as seen.
		assertFalse(DailySignals.approvalNews(false, 100, null, 127, NOW, NOW));
		// Nothing saved: any trusted reading counts.
		assertTrue(DailySignals.approvalNews(false, 100, null, null, 0, NOW));
		// In the kingdom: a different value, or the same one saved on an earlier day, is today's reading.
		assertTrue(DailySignals.approvalNews(true, 100, 100, 127, NOW, NOW));
		assertFalse(DailySignals.approvalNews(true, 127, 100, 127, NOW, NOW));
		assertTrue(DailySignals.approvalNews(true, 127, 127, 127, yesterday, NOW));
	}

	@Test
	public void loginWithClaimedFlagIsQuietAndOnce()
	{
		List<Routines.Daily> dailies = Arrays.asList(daily("z", "zaff_staves"), daily("b", "bert_sand"));
		Set<String> claimed = Collections.singleton("zaff_staves");
		Set<String> sent = new HashSet<>();
		List<Routines.Daily> first = DailySignals.newlyDone(claimed, sent, dailies);
		assertEquals(1, first.size());
		assertEquals("z", first.get(0).id);
		assertTrue(DailySignals.newlyDone(claimed, sent, dailies).isEmpty());
		sent.clear(); // the daily reset
		assertEquals(1, DailySignals.newlyDone(claimed, sent, dailies).size());
	}

	@Test
	public void taskWithoutKeyIsNeverAutoDone()
	{
		List<Routines.Daily> dailies = Collections.singletonList(daily("x", ""));
		Set<String> claimed = new HashSet<>(Collections.singletonList(""));
		assertTrue(DailySignals.newlyDone(claimed, new HashSet<>(), dailies).isEmpty());
	}

	@Test
	public void iconFromFeedThenTableThenCoins()
	{
		Routines.Daily d = daily("z", "zaff_staves");
		assertEquals(ItemID.BATTLESTAFF, DailySignals.icon(d));
		d.itemId = ItemID.BOW_STRING;
		assertEquals(ItemID.BOW_STRING, DailySignals.icon(d));
		assertEquals(ItemID.COINS, DailySignals.icon(daily("x", "")));
		assertEquals(ItemID.POH_TREASURE_TEAK, (int) DailySignals.ICONS.get("miscellania"));
	}

	private static Routines.Daily labelled(String label)
	{
		return new Routines.Daily(label, label, "daily", 1, 0);
	}

	@Test
	public void exactLabelWithoutKeyGetsTheKey()
	{
		assertEquals("bert_sand", DailySignals.keyFor(labelled("Bert's buckets of sand")));
		assertEquals("miscellania", DailySignals.keyFor(labelled("kingdom of miscellania (keep approval up)")));
		assertEquals("robin_slime", DailySignals.keyFor(labelled("Robin's buckets of slime (Port Phasmatys)")));
		assertEquals("tears_of_guthix", DailySignals.keyFor(labelled(" TEARS OF GUTHIX ")));
		Routines.Daily keyed = labelled("Whatever");
		keyed.key = "zaff_staves";
		assertEquals("zaff_staves", DailySignals.keyFor(keyed));
		assertEquals("", DailySignals.keyFor(labelled("Sand mining")));
	}

	@Test
	public void exactLabelWithoutKeyGetsIconAndIsAutoDone()
	{
		Routines.Daily d = labelled("Bert's buckets of sand");
		assertEquals(ItemID.BUCKET_SAND, DailySignals.icon(d));
		List<Routines.Daily> done = DailySignals.newlyDone(Collections.singleton("bert_sand"), new HashSet<>(),
			Collections.singletonList(d));
		assertEquals(1, done.size());
	}

	@Test
	public void customLabelGetsIconButIsNeverAutoDone()
	{
		Routines.Daily d = labelled("Sand mining");
		assertEquals(ItemID.BUCKET_SAND, DailySignals.icon(d));
		Set<String> all = new HashSet<>(DailySignals.ICONS.keySet());
		assertTrue(DailySignals.newlyDone(all, new HashSet<>(), Collections.singletonList(d)).isEmpty());
		assertEquals(ItemID.LOVAKENGJ_DYNAMITE_FUSED, DailySignals.icon(labelled("Buy Thirus stuff")));
		assertEquals(ItemID.BATTLESTAFF, DailySignals.icon(labelled("Battlestaff run")));
		assertEquals(ItemID.NZONE_HERBBOX, DailySignals.icon(labelled("Nightmare Zone boxes")));
	}
}

package com.nibtracker;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class FarmGroupsTest
{
	private static final long NOW = 1_000_000_000L;
	private static final long MIN = 60_000L;

	private static Routines.Patch guild(String kind, String crop, String state, long readyAt)
	{
		Routines.Patch p = new Routines.Patch("Farming Guild", "Guild " + kind, kind, crop, 0, readyAt, "ready".equals(state));
		p.kind = kind;
		p.state = state;
		return p;
	}

	private static FarmGroups.Contract ranarr()
	{
		return FarmGroups.contract(ItemID.RANARR_WEED);
	}

	private static FarmGroups.ContractView view(FarmGroups.Contract c, Routines.Patch... patches)
	{
		List<Routines.Patch> farm = Arrays.asList(patches);
		return FarmGroups.contractView(c, farm, NOW);
	}

	@Test
	public void specialKinds()
	{
		assertTrue(FarmGroups.special("seaweed"));
		assertFalse(FarmGroups.special("herb"));
		assertFalse(FarmGroups.special("celastrus"));
		for (String k : new String[]{"hespori", "anima", "belladonna", "cactus", "seaweed", "mushroom", "calquat"})
		{
			assertTrue(k, FarmGroups.special(k));
		}
	}

	@Test
	public void treeKinds()
	{
		assertTrue(FarmGroups.tree("redwood"));
		assertTrue(FarmGroups.tree("hardwood"));
		assertFalse(FarmGroups.tree("fruit_tree"));
	}

	@Test
	public void contractIdIgnoresCrop()
	{
		assertEquals("farming:contract", FarmGroups.CONTRACT_ID);
	}

	@Test
	public void contractLookup()
	{
		assertEquals("herb", FarmGroups.contract(ItemID.RANARR_WEED).kind);
		assertEquals("Ranarr", FarmGroups.contract(ItemID.RANARR_WEED).crop);
		assertEquals("redwood", FarmGroups.contract(ItemID.REDWOOD_LOGS).kind);
		assertEquals("fruit_tree", FarmGroups.contract(ItemID.COOKING_APPLE).kind);
		assertEquals("cactus", FarmGroups.contract(ItemID.CACTUS_POTATO).kind);
		assertNull(FarmGroups.contract(ItemID.TEAK_LOGS));
	}

	@Test
	public void noContract()
	{
		FarmGroups.ContractView v = FarmGroups.contractView(null, Collections.<Routines.Patch>emptyList(), NOW);
		assertEquals("No contract · talk to Jane", v.value);
		assertFalse(v.ready);
		assertFalse(v.attention);
	}

	@Test
	public void readyPatch()
	{
		FarmGroups.ContractView v = view(ranarr(), guild("herb", "Ranarr", "ready", 0));
		assertTrue(v.ready);
		assertEquals("Ready · then see Jane for a new contract", v.value);
		assertEquals(ItemID.RANARR_WEED, v.itemId);
	}

	@Test
	public void contractOccupiedAndEmpty()
	{
		assertEquals("Other crop planted", view(ranarr(), guild("herb", "Guam", "growing", NOW + MIN)).value);
		FarmGroups.ContractView none = view(ranarr());
		assertEquals("Not planted", none.value);
		assertEquals("Harvested? See Jane for a new contract", none.sub);
		assertEquals("Not planted", view(ranarr(), guild("herb", "", "empty", 0)).value);
		assertEquals("Not planted", view(ranarr(), guild("tree", "Oak", "growing", 0)).value);
	}

	private static Routines.Patch allotment(String name, String crop, String state, long readyAt)
	{
		Routines.Patch p = new Routines.Patch("Farming Guild", name, "Allotment", crop, 0, readyAt, "ready".equals(state));
		p.kind = "allotment";
		p.state = state;
		return p;
	}

	@Test
	public void contractCropInTheSecondAllotment()
	{
		FarmGroups.Contract potato = FarmGroups.contract(ItemID.POTATO);
		Routines.Patch south = allotment("South", "Potatoes", "growing", NOW + 90 * MIN);
		south.progress = 0.4;
		FarmGroups.ContractView v = view(potato, allotment("North", "Onions", "growing", NOW + MIN), south);
		assertEquals("1h 30m", v.value);
		assertEquals(0.4, v.progress, 0.0001);
		assertEquals("1h 30m", view(potato, allotment("North", "", "empty", 0), south).value);
		// The more advanced of two matching crops wins: ready over growing over diseased.
		FarmGroups.ContractView ready = view(potato, allotment("North", "Potatoes", "diseased", 0),
			south, allotment("South", "Potatoes", "ready", 0));
		assertTrue(ready.ready);
		assertEquals("Ready · then see Jane for a new contract", ready.value);
		assertEquals(1, ready.progress, 0.0001);
		assertEquals("1h 30m", view(potato, allotment("North", "Potatoes", "diseased", 0), south).value);
	}

	@Test
	public void contractEmptyAllotmentBeatsOtherCrop()
	{
		FarmGroups.Contract potato = FarmGroups.contract(ItemID.POTATO);
		FarmGroups.ContractView v = view(potato, allotment("North", "Onions", "growing", NOW + MIN), allotment("South", "", "empty", 0));
		assertEquals("Not planted", v.value);
		assertEquals("Harvested? See Jane for a new contract", v.sub);
		assertEquals("Other crop planted", view(potato, allotment("North", "Onions", "growing", NOW + MIN),
			allotment("South", "Cabbages", "growing", NOW + MIN)).value);
	}

	@Test
	public void diseasedNeedsAttention()
	{
		FarmGroups.ContractView v = view(ranarr(), guild("herb", "Ranarr", "diseased", 0));
		assertTrue(v.attention);
		assertEquals("Diseased", v.value);
	}

	@Test
	public void growingShowsTimeLeft()
	{
		Routines.Patch p = guild("herb", "Ranarr", "growing", NOW + 90 * MIN);
		p.progress = 0.4;
		FarmGroups.ContractView v = view(ranarr(), p);
		assertEquals("1h 30m", v.value);
		assertEquals(0.4, v.progress, 0.0001);
		assertFalse(v.ready);
		assertEquals("Growing", view(ranarr(), guild("herb", "Ranarr", "growing", 0)).value);
	}

	@Test
	public void cropMatchIgnoresCaseAndPlural()
	{
		FarmGroups.Contract potato = FarmGroups.contract(ItemID.POTATO);
		assertNotNull(potato);
		assertEquals("Potatoes", potato.crop);
		assertEquals("Ready · then see Jane for a new contract", view(potato, guild("allotment", "potato", "ready", 0)).value);
	}

	@Test
	public void title()
	{
		assertEquals("Contract: Ranarr · Farming Guild herb patch", view(ranarr()).title);
		assertEquals("Contract: Apple · Farming Guild fruit tree patch", view(FarmGroups.contract(ItemID.COOKING_APPLE)).title);
	}

	private static GoalsPanel.PatchView view(String kind, String kindLabel)
	{
		GoalsPanel.PatchView v = new GoalsPanel.PatchView("Catherby", "Crop", "", "", "", "", false, 0);
		v.kind = kind;
		v.kindLabel = kindLabel;
		return v;
	}

	@Test
	public void specialKindsHaveTheirOwnPicture()
	{
		assertEquals(ItemID.CRYSTAL_TREE_SEED, FarmGroups.kindIcon("crystal_tree"));
		assertEquals(ItemID.GIANT_SEAWEED, FarmGroups.kindIcon("seaweed"));
		assertEquals(ItemID.BITTERCAP_MUSHROOM, FarmGroups.kindIcon("mushroom"));
		assertEquals(0, FarmGroups.kindIcon("herb"));
	}

	@Test
	public void favouritesGroupByKindLabelInNameOrder()
	{
		GoalsPanel.PatchView herb1 = view("herb", "Herbs"), bush = view("bush", "Bushes"), herb2 = view("herb", "Herbs"),
			noLabel = view("hespori", "");
		java.util.Map<String, List<GoalsPanel.PatchView>> g = GoalsPanel.byKind(Arrays.asList(herb1, bush, herb2, noLabel));
		assertEquals(Arrays.asList("Bushes", "Herbs", "hespori"), new java.util.ArrayList<>(g.keySet()));
		assertEquals(Arrays.asList(herb1, herb2), g.get("Herbs"));
	}

	@Test
	public void kindChipsLeaveOutTreesAndGroups()
	{
		List<GoalsPanel.PatchView> ps = Arrays.asList(view("herb", "Herbs"), view("tree", "Trees"), view("hardwood", "Hardwood"),
			view("redwood", "Redwood"), view("fruit_tree", "Fruit trees"), view("herb", "Herbs"), view("hespori", "Hespori"),
			view("x", ""), view("spirit_tree", "Spirit trees"));
		assertEquals(Arrays.asList("Fruit trees", "Herbs", "Hespori"), GoalsPanel.kindChips(ps));
	}
}

package com.nibtracker;

import static org.junit.Assert.assertEquals;
import com.google.gson.Gson;
import com.google.gson.JsonParser;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class FarmMergeTest
{
	private static final long T = 1_441_333L * 1200;

	@Test
	public void feedMissingOrStale()
	{
		Map<String, String> e = new HashMap<>();
		e.put("11062.4774", "32:" + T);
		List<Routines.Patch> local = PatchPredictor.load(new Gson()).predict(e, T * 1000);
		// The feed is older: it still says the herb is empty, but it knows the way there and the run order.
		List<Routines.Patch> feed = Routines.farm(new JsonParser().parse(
			"[{\"region\":\"Catherby\",\"type\":\"Herb\",\"crop\":\"Weeds\",\"state\":\"empty\",\"kind\":\"herb\",\"travel\":\"Catherby teleport\","
				+ "\"travelHow\":\"Cast it\",\"travelCat\":\"SPELLBOOK\",\"travelItem\":\"Law rune\",\"order\":2}]"));

		List<Routines.Patch> merged = FarmRows.merge(local, feed);
		assertEquals(1, merged.size());
		Routines.Patch p = merged.get(0);
		assertEquals("growing", p.state);
		assertEquals("Ranarr", p.crop);
		assertEquals("Catherby teleport", p.travel);
		assertEquals("Cast it", p.travelHow);
		assertEquals("SPELLBOOK", p.travelCat);
		assertEquals("Law rune", p.travelItem);
		assertEquals(2, p.order);

		List<Routines.Patch> alone = FarmRows.merge(local, Collections.emptyList());
		assertEquals(1, alone.size());
		assertEquals("", alone.get(0).travel);

		// A row only the feed has (a special patch with no Time Tracking data) is kept as it is.
		List<Routines.Patch> extra = Routines.farm(new JsonParser().parse(
			"[{\"region\":\"Farming Guild\",\"name\":\"Hespori\",\"crop\":\"\",\"state\":\"unknown\",\"kind\":\"hespori\"}]"));
		List<Routines.Patch> both = FarmRows.merge(local, extra);
		assertEquals(2, both.size());
		assertEquals("Catherby||herb", both.get(0).id());
		assertEquals("unknown", both.get(1).state);
	}

	@Test
	public void staleFeedOnlyRowsDropped()
	{
		Map<String, String> e = new HashMap<>();
		e.put("11062.4774", "32:" + T);
		List<Routines.Patch> local = PatchPredictor.load(new Gson()).predict(e, T * 1000);
		// The bird house was emptied, so there's no row for it here; the feed still says it's ready.
		List<Routines.Patch> feed = Routines.farm(new JsonParser().parse(
			"[{\"region\":\"Fossil Island\",\"name\":\"Verdant Valley\",\"crop\":\"Bird house\",\"state\":\"ready\",\"kind\":\"birdhouse\"},"
				+ "{\"region\":\"Farming Guild\",\"name\":\"Hespori\",\"crop\":\"\",\"state\":\"unknown\",\"kind\":\"hespori\"}]"));

		List<Routines.Patch> merged = FarmRows.merge(local, feed);
		assertEquals(2, merged.size());
		assertEquals("Catherby||herb", merged.get(0).id());
		assertEquals("Hespori", merged.get(1).name);
		assertEquals("unknown", merged.get(1).state);

		// With nothing worked out here (no Time Tracking data), the feed's rows show as they are.
		List<Routines.Patch> none = FarmRows.merge(Collections.emptyList(), feed);
		assertEquals(2, none.size());
		assertEquals("ready", none.get(0).state);
	}
}

package com.nibtracker;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class FarmRowsTest
{
	private static final long NOW = 1_000_000_000L;
	private static final long MIN = 60_000L;

	private static Routines.Patch patch(String crop, String state, long readyAt)
	{
		Routines.Patch p = new Routines.Patch("Catherby", "Catherby", "Herb", crop, 0, readyAt, "ready".equals(state));
		p.kind = "herb";
		p.kindLabel = "Herbs";
		p.state = state;
		return p;
	}

	@Test
	public void statusForEachState()
	{
		assertEquals("Diseased", FarmRows.status(patch("Ranarr", "diseased", NOW - MIN), NOW));
		assertEquals("Dead", FarmRows.status(patch("Ranarr", "dead", 0), NOW));
		assertEquals("Ready", FarmRows.status(patch("Ranarr", "ready", 0), NOW));
		assertEquals("Ready", FarmRows.status(patch("Ranarr", "growing", NOW - MIN), NOW));
		assertEquals("Empty", FarmRows.status(patch("", "empty", 0), NOW));
		assertEquals("Unknown", FarmRows.status(patch("", "unknown", 0), NOW));
		assertEquals("30m", FarmRows.status(patch("Ranarr", "growing", NOW + 30 * MIN), NOW));
		assertEquals("Growing", FarmRows.status(patch("Ranarr", "growing", 0), NOW));
	}

	@Test
	public void diseasedIsNeverReady()
	{
		assertFalse(FarmRows.ready(patch("Ranarr", "diseased", NOW - MIN), NOW));
		assertFalse(FarmRows.ready(patch("", "empty", NOW - MIN), NOW));
		assertTrue(FarmRows.ready(patch("Ranarr", "ready", 0), NOW));
	}

	@Test
	public void titles()
	{
		assertEquals("Ranarr", FarmRows.title(patch("Ranarr", "growing", 0)));
		assertEquals("Unknown", FarmRows.title(patch("Ranarr", "unknown", 0)));
		assertEquals("Herbs", FarmRows.title(patch("", "empty", 0)));
	}

	@Test
	public void subLeavesOutRepeatsAndBlanks()
	{
		assertEquals("Catherby · Camelot Teleport", FarmRows.sub("Catherby", "Catherby", "Camelot Teleport"));
		assertEquals("Farming Guild · Tree patch · Skills necklace", FarmRows.sub("Farming Guild", "Tree patch", "Skills necklace"));
		assertEquals("Ardougne", FarmRows.sub("Ardougne", "", ""));
	}

	@Test
	public void readyFirstKeepsOrderOtherwise()
	{
		List<String> rows = Arrays.asList("a", "B", "c", "D");
		assertEquals(Arrays.asList("B", "D", "a", "c"), FarmRows.readyFirst(rows, s -> Character.isUpperCase(s.charAt(0))));
	}

	@Test
	public void shiftClickTicksTheRange()
	{
		List<String> ids = Arrays.asList("a", "b", "c", "d", "e");
		Set<String> ticked = new HashSet<>(Collections.singleton("a"));
		FarmRows.tickRange(ids, 0, 3, true, ticked);
		assertEquals(new HashSet<>(Arrays.asList("a", "b", "c", "d")), ticked);
		// Upwards, and unticking.
		FarmRows.tickRange(ids, 3, 1, false, ticked);
		assertEquals(new HashSet<>(Collections.singletonList("a")), ticked);
	}

	@Test
	public void clickWithNoAnchorTicksOne()
	{
		List<String> ids = Arrays.asList("a", "b", "c");
		Set<String> ticked = new HashSet<>();
		FarmRows.tickRange(ids, -1, 2, true, ticked);
		assertEquals(Collections.singleton("c"), ticked);
	}

	@Test
	public void hiddenRegionsKeepThoseNotOffered()
	{
		List<String> offered = Arrays.asList("Ardougne", "Catherby", "Falador");
		Set<String> before = new LinkedHashSet<>(Arrays.asList("Catherby", "Trollheim"));
		Set<String> shown = new HashSet<>(Arrays.asList("Catherby"));
		assertEquals(new LinkedHashSet<>(Arrays.asList("Trollheim", "Ardougne", "Falador")), FarmRows.hiddenAfter(offered, before, shown));
	}

	@Test
	public void favouritesKeepSavedOrderAndAppendNew()
	{
		List<String> saved = Arrays.asList("x", "c", FarmGroups.CONTRACT_ID, "a");
		List<String> offered = Arrays.asList("a", "b", "c", FarmGroups.CONTRACT_ID);
		Set<String> ticked = new HashSet<>(Arrays.asList("a", "b", FarmGroups.CONTRACT_ID));
		// "x" wasn't offered (no data now), so it stays; "c" was unticked; "b" is new and goes last.
		assertEquals(Arrays.asList("x", FarmGroups.CONTRACT_ID, "a", "b"), FarmRows.favouritesAfter(saved, offered, ticked));
	}

	@Test
	public void summaryIgnoresPatchesThatArentGrowing()
	{
		// A diseased crop with a timer that has run out isn't "1 ready", and one still timed isn't "next".
		assertEquals("Diseased", Routines.summary(Arrays.asList(patch("Ranarr", "diseased", NOW - MIN)), NOW));
		assertEquals("Dead", Routines.summary(Arrays.asList(patch("Ranarr", "dead", NOW + MIN)), NOW));
		assertEquals("Empty", Routines.summary(Arrays.asList(patch("", "empty", 0), patch("", "empty", NOW + MIN)), NOW));
		assertEquals("Unknown", Routines.summary(Arrays.asList(patch("", "unknown", NOW + MIN)), NOW));
		assertEquals("Diseased", Routines.summary(Arrays.asList(patch("", "empty", 0), patch("Ranarr", "diseased", NOW + MIN)), NOW));
		assertEquals("Growing", Routines.summary(Arrays.asList(patch("", "empty", 0), patch("Guam", "growing", 0)), NOW));
		assertEquals("next 30m", Routines.summary(Arrays.asList(patch("Ranarr", "diseased", NOW + 5 * MIN),
			patch("", "empty", NOW + 10 * MIN), patch("Guam", "growing", NOW + 30 * MIN)), NOW));
		assertEquals("1 ready", Routines.summary(Arrays.asList(patch("Ranarr", "dead", NOW - MIN), patch("Guam", "ready", 0)), NOW));
	}

	@Test
	public void soonestAndNextSkipPatchesThatArentGrowing()
	{
		Routines.Patch diseased = patch("Ranarr", "diseased", NOW + 5 * MIN);
		Routines.Patch empty = patch("", "empty", NOW + 10 * MIN);
		Routines.Patch growing = patch("Guam", "growing", NOW + 30 * MIN);
		Routines.Patch untimed = patch("Guam", "growing", 0);
		assertEquals(0, FarmRows.soonest(patch("Guam", "ready", 0), NOW));
		assertEquals(NOW + 30 * MIN, FarmRows.soonest(growing, NOW));
		assertEquals(Long.MAX_VALUE, FarmRows.soonest(diseased, NOW));
		assertEquals(Long.MAX_VALUE, FarmRows.soonest(empty, NOW));
		// A growing crop with no timer still sorts before a region with nothing growing.
		assertTrue(FarmRows.soonest(untimed, NOW) < FarmRows.soonest(empty, NOW));
		assertEquals(NOW + 30 * MIN, FarmRows.soonest(Arrays.asList(diseased, empty, growing), NOW));
		assertEquals(growing, FarmRows.next(Arrays.asList(diseased, empty, growing), NOW));
		assertEquals(null, FarmRows.next(Arrays.asList(diseased, empty), NOW));
	}

	@Test
	public void readyShareCountsOnlyGrowingAndReady()
	{
		List<Routines.Patch> ps = Arrays.asList(patch("Guam", "ready", 0), patch("Ranarr", "growing", NOW + MIN),
			patch("", "empty", 0), patch("", "unknown", 0), patch("Torstol", "diseased", 0));
		assertEquals(0.5, FarmRows.readyShare(ps, NOW), 0.0001);
		assertTrue(FarmRows.anyGrowing(ps));
		assertFalse(FarmRows.anyGrowing(Arrays.asList(patch("", "empty", 0), patch("Torstol", "dead", 0))));
		assertEquals(0, FarmRows.readyShare(Arrays.asList(patch("", "empty", 0)), NOW), 0.0001);
	}

	@Test
	public void excludedTeleportsAreParsedAndMatchedInAnyCase()
	{
		List<String> skip = FarmRows.excluded(" Book of the dead , ,Ectophial\n");
		assertEquals(Arrays.asList("book of the dead", "ectophial"), skip);
		assertTrue(FarmRows.excluded("Book of the Dead (Kourend)", skip));
		assertFalse(FarmRows.excluded("Camelot Teleport", skip));
		assertFalse(FarmRows.excluded("Camelot Teleport", Collections.emptyList()));
		// However it is written: capitals, extra spaces, apostrophes.
		assertTrue(FarmRows.excluded("Xeric’s talisman", FarmRows.excluded("XERICS   Talisman")));
		assertTrue(FarmRows.excluded("Book of the dead", FarmRows.excluded("book-of-the-DEAD")));
	}

	@Test
	public void aStopUsesItsBestTeleportNotExcluded()
	{
		Routines.Stop s = new Routines.Stop(3, "Hosidius");
		s.teles.add(new Routines.Tele("Book of the dead", "Rub it", "ITEM", "Book of the dead"));
		s.teles.add(new Routines.Tele("Xeric's talisman", "Rub it", "ITEM", "Xeric's talisman"));
		assertEquals("Book of the dead", FarmRows.pick(s, Collections.emptyList()).travel);
		assertEquals("Xeric's talisman", FarmRows.pick(s, FarmRows.excluded("book of the dead")).travel);
		assertEquals(null, FarmRows.pick(s, FarmRows.excluded("book of the dead, xeric")));
	}

	@Test
	public void excludedTeleportsGiveWayToTheStopsNextBest()
	{
		Routines.Stop s = new Routines.Stop(1, "Catherby");
		s.teles.add(new Routines.Tele("Camelot Teleport", "Cast it", "SPELLBOOK", ""));
		s.teles.add(new Routines.Tele("Catherby tablet", "Break it", "ITEM", "Catherby teleport"));
		Routines.Patch p = patch("Ranarr", "growing", NOW + MIN);
		p.stop = 1;
		p.travel = "Camelot Teleport";
		Routines.Patch other = patch("Guam", "growing", NOW + MIN);
		other.travel = "Camelot Teleport";
		List<Routines.Patch> out = FarmRows.skipTeleports(Arrays.asList(p, other), Collections.singletonList(s), FarmRows.excluded("camelot"));
		assertEquals("Catherby tablet", out.get(0).travel);
		assertEquals("ITEM", out.get(0).travelCat);
		assertEquals("Camelot Teleport", p.travel);
		// No stop to fall back on: it keeps what it had.
		assertEquals("Camelot Teleport", out.get(1).travel);
		assertTrue(FarmRows.skipTeleports(Arrays.asList(p), Collections.singletonList(s), Collections.emptyList()).get(0) == p); // nothing excluded: as given
	}
}

package com.nibtracker;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class FavouritesTest
{
	private static Set<String> set(String... ids)
	{
		return new LinkedHashSet<>(Arrays.asList(ids));
	}

	@Test
	public void roundTrips()
	{
		Map<String, Set<String>> m = new LinkedHashMap<>();
		m.put("farming", set("farm:patch:Ardougne|North|herb", "daily:a,b", "fav:x"));
		m.put("goals", set("g1"));
		assertEquals(m, Favourites.parse(Favourites.write(m)));
	}

	@Test
	public void oldPinsStillParse()
	{
		assertTrue(Favourites.isLegacyKindPin("farming:Herbs"));
		assertFalse(Favourites.isLegacyKindPin("farming:kind:herb"));
		assertFalse(Favourites.isLegacyKindPin("farming:contract"));
		assertFalse(Favourites.isLegacyKindPin("dailies"));
		assertFalse(Favourites.isLegacyKindPin("farming"));
		assertTrue(Favourites.parse(null).isEmpty());
		assertTrue(Favourites.parse("").isEmpty());
	}

	@Test
	public void pinIds()
	{
		assertEquals("farm:patch:a|b|c", Favourites.patchPin("a|b|c"));
		assertEquals("daily:x", Favourites.dailyPin("x"));
		assertEquals("fav:t", Favourites.groupPin("t"));
		assertEquals("farming:kind:herb", Favourites.kindPin("herb"));
	}

	@Test
	public void toggleAddsThenRemoves()
	{
		Map<String, Set<String>> m = new LinkedHashMap<>();
		Favourites.toggle(m, "farming", "a");
		assertEquals(set("a"), m.get("farming"));
		Favourites.toggle(m, "farming", "a");
		assertTrue(m.getOrDefault("farming", Collections.emptySet()).isEmpty());
	}

	@Test
	public void setAllReplacesOnlyThatTab()
	{
		Map<String, Set<String>> m = new LinkedHashMap<>();
		m.put("farming", set("a", "b"));
		m.put("goals", set("g"));
		Favourites.setAll(m, "farming", Arrays.asList("c"));
		assertEquals(set("c"), m.get("farming"));
		assertEquals(set("g"), m.get("goals"));
	}

	@Test
	public void hiddenRegionKeepsFavourites()
	{
		Routines.Patch p = new Routines.Patch("Ardougne", "North", "herb", "Ranarr", 0, 0, false);
		assertFalse(FarmGroups.shownInAll(p, new HashSet<>(Arrays.asList("Ardougne"))));
		assertTrue(FarmGroups.shownInAll(p, Collections.emptySet()));
	}

	@Test
	public void regionPinIsDistinct()
	{
		assertEquals("farm:region:Farming Guild", Favourites.regionPin("Farming Guild"));
		assertFalse(Favourites.isLegacyKindPin(Favourites.regionPin("Farming Guild")));
	}

	@Test
	public void onlyKeepsFavouritesInOrder()
	{
		Set<String> favs = new HashSet<>(Arrays.asList("b", "d"));
		assertEquals(Arrays.asList("b", "d"), Favourites.only(Arrays.asList("a", "b", "c", "d"), s -> s, favs));
		assertTrue(Favourites.only(Arrays.asList("a", "c"), s -> s, favs).isEmpty());
		assertTrue(Favourites.only(Arrays.asList("a"), s -> s, Collections.emptySet()).isEmpty());
	}

	@Test
	public void oldTreeKindPinsBecomeAllTrees()
	{
		Set<String> pins = new LinkedHashSet<>(Arrays.asList("g1", "farming:Trees", "farming:kind:herb", "farming:kind:hardwood",
			"farming:Redwood", "farming:Herbs", "farming:kind:redwood", "farming:Hardwood", "farming:kind:tree", "farming:special"));
		Set<String> out = Favourites.migrateTreePins(pins);
		assertEquals(new LinkedHashSet<>(Arrays.asList("g1", Favourites.TREES_PIN, "farming:kind:herb", "farming:Herbs", "farming:special")), out);
		assertEquals(Arrays.asList("g1", Favourites.TREES_PIN, "farming:kind:herb", "farming:Herbs", "farming:special"), new ArrayList<>(out));
		// Again changes nothing; an All trees pin already there isn't doubled.
		assertEquals(out, Favourites.migrateTreePins(out));
		Set<String> both = Favourites.migrateTreePins(new LinkedHashSet<>(Arrays.asList(Favourites.TREES_PIN, "farming:kind:tree")));
		assertEquals(Collections.singleton(Favourites.TREES_PIN), both);
		Set<String> none = new LinkedHashSet<>(Arrays.asList("dailies", "farming:contract", "farm:patch:x"));
		assertEquals(none, Favourites.migrateTreePins(none));
	}
}

package com.nibtracker;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

public class GoalLayoutTest
{
	private static GoalsPanel.Row row(String id, String category, double progress, boolean done, String parent)
	{
		GoalsPanel.Row r = new GoalsPanel.Row(id, category, id, "", "", progress, done, 0, null, null, -1, null);
		r.parent = parent;
		r.serverDone = done;
		return r;
	}

	@Test
	public void partsFoldUnderTheirMainGoal()
	{
		GoalsPanel.Row base = row("base", "Skills", 0.6, false, "");
		base.partsDone = 20;
		base.partsTotal = 23;
		List<GoalsPanel.Row> rows = Arrays.asList(base,
			row("smith", "Skills", 0.5, false, "base"), row("fish", "Skills", 0.9, false, "base"),
			row("ds1", "Quests", 0, false, ""));
		GoalLayout.Layout l = GoalLayout.of(rows);
		assertEquals(1, l.sections.get("Skills").size());
		GoalLayout.Group g = l.sections.get("Skills").get(0);
		assertEquals("base", g.main.id);
		assertEquals(Arrays.asList("fish", "smith"), Arrays.asList(g.parts.get(0).id, g.parts.get(1).id));
		assertEquals(1, l.sections.get("Quests").size());
		assertTrue(l.completed.isEmpty());
	}

	@Test
	public void mainGoalWithoutItsOwnProgressCountsItsParts()
	{
		GoalsPanel.Row cape = row("cape", "Items", -1, false, "");
		cape.partsDone = 8;
		cape.partsTotal = 10;
		GoalsPanel.Row q1 = row("q1", "Quests", 0, false, "cape");
		GoalsPanel.Row q2 = row("q2", "Quests", 1, true, "cape");
		q2.serverDone = false; // done in game since the web app last sent the list
		GoalLayout.Group g = GoalLayout.of(Arrays.asList(cape, q1, q2)).sections.get("Items").get(0);
		assertEquals(9, g.partsDone());
		assertEquals(10, g.partsTotal());
		assertEquals(0.9, g.progress(), 0.0001);
	}

	@Test
	public void finishedGoalsGoToCompletedAndOrphanPartsStandAlone()
	{
		List<GoalsPanel.Row> rows = Arrays.asList(row("done", "Quests", 1, true, ""), row("orphan", "Skills", 0.2, false, "gone"));
		GoalLayout.Layout l = GoalLayout.of(rows);
		assertEquals("done", l.completed.get(0).main.id);
		assertEquals("orphan", l.sections.get("Skills").get(0).main.id);
		assertEquals(1, l.sections.size());
	}

	@Test
	public void extrasShowUnderTheirGoalButAreNotParts()
	{
		GoalsPanel.Row slayer = row("s95", "Skills", 0.4, false, "");
		GoalsPanel.Row task = row(GoalTracker.SLAYER_TASK, "Skills", 0.5, false, "s95");
		task.extra = true;
		GoalsPanel.Row lost = row("x", "Skills", 0.5, false, "missing");
		lost.extra = true;
		GoalLayout.Layout l = GoalLayout.of(Arrays.asList(slayer, task, lost));
		GoalLayout.Group g = l.sections.get("Skills").get(0);
		assertEquals(1, l.sections.get("Skills").size());
		assertEquals(GoalTracker.SLAYER_TASK, g.extras.get(0).id);
		assertTrue(g.parts.isEmpty());
		assertEquals(0, g.partsTotal());
	}

	@Test
	public void overviewKeepsOnlyFavourites()
	{
		GoalsPanel.Row base = row("base", "Skills", 0.6, false, "");
		List<GoalsPanel.Row> rows = Arrays.asList(base, row("smith", "Skills", 0.5, false, "base"),
			row("fish", "Skills", 0.9, false, "base"), row("att", "Skills", 0.3, false, ""), row("hp", "Skills", 0.1, false, ""),
			row("done1", "Quests", 1, true, ""), row("done2", "Quests", 1, true, ""));
		GoalLayout.Layout l = GoalLayout.of(rows);
		Map<String, Set<String>> favs = new HashMap<>();
		favs.put("Skills", new HashSet<>(Arrays.asList("fish", "hp")));
		favs.put("Quests", new HashSet<>(Collections.singletonList("done2")));

		// A favourite part comes on its own; a group whose main goal isn't a favourite doesn't.
		GoalLayout.Picks skills = GoalLayout.favourites(l.sections.get("Skills"), favs);
		assertTrue(skills.groups.stream().anyMatch(g -> "hp".equals(g.main.id)));
		assertEquals(1, skills.groups.size());
		assertEquals(Collections.singletonList("fish"), Arrays.asList(skills.rows.get(0).id));
		assertEquals(2, skills.size());

		// A favourite main goal brings its group (and its parts with it, not again on their own).
		favs.put("Skills", new HashSet<>(Arrays.asList("base", "fish")));
		GoalLayout.Picks whole = GoalLayout.favourites(l.sections.get("Skills"), favs);
		assertEquals("base", whole.groups.get(0).main.id);
		assertTrue(whole.rows.isEmpty());

		// Completed: only the favourited ones.
		GoalLayout.Picks done = GoalLayout.favourites(l.completed, favs);
		assertEquals(1, done.groups.size());
		assertEquals("done2", done.groups.get(0).main.id);

		assertTrue(GoalLayout.favourites(l.completed, Collections.emptyMap()).isEmpty());
	}

	@Test
	public void overviewOrderDefaultsAndKeepsSavedOrder()
	{
		assertEquals(GoalLayout.OVERVIEW_ORDER, GoalLayout.overviewOrder(""));
		assertEquals("Farming", GoalLayout.overviewOrder("").get(0));
		// Saved names first, unknown and repeated ones dropped, the rest after in the default order.
		List<String> o = GoalLayout.overviewOrder("Skills, Nonsense,Quests,Skills");
		assertEquals(Arrays.asList("Skills", "Quests", "Farming", "Daily tasks"), o.subList(0, 4));
		assertEquals(GoalLayout.OVERVIEW_ORDER.size(), o.size());
	}

	@Test
	public void movingASectionLandsWhereItIsDropped()
	{
		List<String> o = Arrays.asList("A", "B", "C", "D");
		assertEquals(Arrays.asList("B", "C", "A", "D"), GoalLayout.move(o, "A", "C"));
		assertEquals(Arrays.asList("A", "D", "B", "C"), GoalLayout.move(o, "D", "B"));
		assertEquals(o, GoalLayout.move(o, "B", "B"));
		assertEquals(o, GoalLayout.move(o, "B", "Z"));
	}
}

package com.nibtracker;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.google.gson.JsonParser;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

public class GoalProgressTest
{
	private static GoalProgress.Goal goal(String json)
	{
		List<GoalProgress.Goal> l = GoalProgress.parse(new JsonParser().parse("[" + json + "]"));
		assertEquals(1, l.size());
		return l.get(0);
	}

	@Test
	public void itemGoalCarriesItemId()
	{
		GoalProgress.Goal g = goal("{\"id\":\"g\",\"type\":\"clog_item\",\"params\":{\"item\":\"Pendant of ates (inert)\",\"itemId\":12345}}");
		assertEquals(12345, g.itemId());
		assertEquals(0, goal("{\"id\":\"h\",\"type\":\"clog_item\",\"params\":{\"item\":\"Abyssal whip\"}}").itemId());
	}

	@Test
	public void parseSkipsMalformedAndCaps()
	{
		StringBuilder sb = new StringBuilder("[1, {\"title\":\"no id\",\"type\":\"kc\"}, {\"id\":\"x\"}");
		for (int i = 0; i < 160; i++)
		{
			sb.append(",{\"id\":\"g").append(i).append("\",\"type\":\"custom\"}");
		}
		List<GoalProgress.Goal> l = GoalProgress.parse(new JsonParser().parse(sb.append("]").toString()));
		assertEquals(GoalProgress.MAX_GOALS, l.size());
		assertEquals("Goal", l.get(0).title);
		assertTrue(GoalProgress.parse(null).isEmpty());
		assertTrue(GoalProgress.parse(new JsonParser().parse("{}")).isEmpty());
	}

	@Test
	public void skillLevelMeasuresFromZeroXp()
	{
		GoalProgress.Goal g = goal("{\"id\":\"a\",\"title\":\"99 Woodcutting\",\"type\":\"skill_level\",\"params\":{\"skill\":\"Woodcutting\",\"level\":99}}");
		GoalProgress.Facts f = new GoalProgress.Facts();
		f.xp.put("woodcutting", 6_517_253L); // level 92, half of 99
		f.levels.put("woodcutting", 92);
		GoalProgress.Result r = GoalProgress.compute(g, f);
		assertEquals(0.5, r.progress, 0.001);
		assertEquals("92 / 99", r.detail);
		assertEquals("6,517,178 XP left", r.hint);
		assertFalse(r.done);

		f.xp.put("woodcutting", 13_034_431L);
		f.levels.put("woodcutting", 99);
		r = GoalProgress.compute(g, f);
		assertEquals(1, r.progress, 0);
		assertTrue(r.done);
	}

	@Test
	public void skillXpAndRunecraftName()
	{
		GoalProgress.Goal g = goal("{\"id\":\"a\",\"type\":\"skill_xp\",\"params\":{\"skill\":\"Runecrafting\",\"xp\":200000}}");
		GoalProgress.Facts f = new GoalProgress.Facts();
		f.xp.put("runecraft", 50_000L);
		f.levels.put("runecraft", 40);
		GoalProgress.Result r = GoalProgress.compute(g, f);
		assertEquals(0.25, r.progress, 0.0001);
		assertEquals("50,000 / 200K", r.detail);
		assertEquals("150,000 XP left", r.hint);
	}

	@Test
	public void baseLevelAveragesSkills()
	{
		GoalProgress.Goal g = goal("{\"id\":\"a\",\"type\":\"base_level\",\"params\":{\"level\":70}}");
		GoalProgress.Facts f = new GoalProgress.Facts();
		f.levels.put("attack", 70);
		f.xp.put("attack", (long) GoalProgress.xpFor(70));
		f.levels.put("magic", 1);
		f.xp.put("magic", 0L);
		GoalProgress.Result r = GoalProgress.compute(g, f);
		assertEquals(0.5, r.progress, 0.0001);
		assertEquals("Lowest 1", r.detail);
		assertEquals("1 skill below 70  ·  737,627 XP left", r.hint);
		assertFalse(r.done);
	}

	@Test
	public void killCountUsesHigherOfChatAndServerAndAliases()
	{
		GoalProgress.Goal g = goal("{\"id\":\"a\",\"type\":\"kc\",\"params\":{\"boss\":\"barrows_chests\",\"count\":100},\"current\":40}");
		GoalProgress.Facts f = new GoalProgress.Facts();
		GoalProgress.Result r = GoalProgress.compute(g, f);
		assertEquals(0.4, r.progress, 0.0001);
		assertEquals("40 / 100", r.detail);
		assertEquals("60 kills left", r.hint);

		f.kcAliases = Collections.singletonMap("barrows", "barrows_chests");
		f.kc.put(GoalProgress.metric("Barrows", f.kcAliases), 100);
		r = GoalProgress.compute(g, f);
		assertTrue(r.done);
		assertEquals("100 / 100", r.detail);
		assertEquals("", r.hint);
	}

	@Test
	public void metricMatchesServer()
	{
		assertEquals("kreearra", GoalProgress.metric("Kree'arra", Collections.emptyMap()));
		assertEquals("chambers_of_xeric", GoalProgress.metric("Chambers of Xeric", Collections.emptyMap()));
		assertEquals("the_gauntlet", GoalProgress.metric("Gauntlet", Collections.singletonMap("gauntlet", "the_gauntlet")));
	}

	@Test
	public void collectionLogAndQuest()
	{
		GoalProgress.Facts f = new GoalProgress.Facts();
		GoalProgress.Goal clog = goal("{\"id\":\"a\",\"type\":\"clog_item\",\"params\":{\"item\":\"Dragon pickaxe\"},\"progress\":0}");
		assertEquals(0, GoalProgress.compute(clog, f).progress, 0);
		assertFalse(GoalProgress.compute(clog, f).done);
		f.clog.add("dragon pickaxe");
		assertTrue(GoalProgress.compute(clog, f).done);

		GoalProgress.Goal quest = goal("{\"id\":\"b\",\"type\":\"quest\",\"params\":{\"quest\":\"Dragon Slayer I\"}}");
		assertEquals(-1, GoalProgress.compute(quest, f).progress, 0);
		f.quests.put("dragon slayer i", "IN_PROGRESS");
		assertEquals("In progress", GoalProgress.compute(quest, f).detail);
		f.quests.put("dragon slayer i", "FINISHED");
		assertTrue(GoalProgress.compute(quest, f).done);
	}

	@Test
	public void itemOwnedCountsBankAndCarried()
	{
		GoalProgress.Goal g = goal("{\"id\":\"a\",\"type\":\"item_owned\",\"params\":{\"item\":\"Shark\",\"qty\":1000},\"target\":1000,\"current\":300}");
		GoalProgress.Facts f = new GoalProgress.Facts();
		// Nothing seen yet: the server's count
		assertEquals(0.3, GoalProgress.compute(g, f).progress, 0.0001);
		// Carried but bank not opened: the higher of the two
		f.carried.put("shark", 500L);
		assertEquals("500 / 1,000", GoalProgress.compute(g, f).detail);
		// Bank seen: bank plus carried
		f.bankSeen = true;
		f.bank.put("shark", 500L);
		assertTrue(GoalProgress.compute(g, f).done);
	}

	@Test
	public void otherTypesShowServerProgressAndServerDoneSticks()
	{
		GoalProgress.Facts f = new GoalProgress.Facts();
		GoalProgress.Goal checklist = goal("{\"id\":\"a\",\"type\":\"checklist\",\"target\":4,\"current\":1,\"progress\":0.25}");
		GoalProgress.Result r = GoalProgress.compute(checklist, f);
		assertEquals(0.25, r.progress, 0);
		assertEquals("1 / 4", r.detail);

		GoalProgress.Goal custom = goal("{\"id\":\"b\",\"type\":\"custom\"}");
		assertEquals(-1, GoalProgress.compute(custom, f).progress, 0);

		GoalProgress.Goal done = goal("{\"id\":\"c\",\"type\":\"skill_level\",\"params\":{\"skill\":\"Attack\",\"level\":99},\"done\":true,\"points\":100}");
		f.xp.put("attack", 0L);
		f.levels.put("attack", 1);
		assertTrue(GoalProgress.compute(done, f).done);
		assertEquals(100, done.points);
	}

	@Test
	public void categoriesAndCompactNumbers()
	{
		assertEquals("Skills", GoalProgress.category("base_level"));
		assertEquals("Quests", GoalProgress.category("quest"));
		assertEquals("Bosses", GoalProgress.category("kc"));
		assertEquals("Achievement diaries", GoalProgress.category("diary_tier"));
		assertEquals("Other", GoalProgress.category("something_new"));
		assertEquals("13.0M", GoalProgress.compact(13_034_431));
		assertEquals("250K", GoalProgress.compact(250_000));
		assertEquals("99,999", GoalProgress.compact(99_999));
	}

	@Test
	public void goalLinks()
	{
		assertEquals("https://buntracker.pages.dev/#goal=gabc123&c=Kimchi%20Bun",
			GoalTracker.link(goal("{\"id\":\"gabc123\",\"type\":\"kc\",\"params\":{\"boss\":\"vorkath\",\"count\":100}}"), "Kimchi Bun"));
		assertEquals("https://buntracker.pages.dev/#goal=a%26b", GoalTracker.link(goal("{\"id\":\"a&b\",\"type\":\"custom\"}"), null));
		assertEquals("https://oldschool.runescape.wiki/w/Dragon_Slayer_I%2FQuick_guide",
			GoalTracker.link(goal("{\"id\":\"q\",\"type\":\"quest\",\"params\":{\"quest\":\"Dragon Slayer I\"}}"), "Kimchi Bun"));
		assertEquals("https://oldschool.runescape.wiki/w/Kourend_%26_Kebos_Diary",
			GoalTracker.link(goal("{\"id\":\"d\",\"type\":\"diary_tier\",\"params\":{\"region\":\"Kourend & Kebos\",\"tier\":\"Hard\"}}"), null));
	}

	@Test
	public void serverInfoIsTheHint()
	{
		GoalProgress.Goal ca = goal("{\"id\":\"a\",\"type\":\"combat_achievement\",\"params\":{\"task\":\"Shayzien Protector\"},\"info\":\"Kill 25 lizardman shamans\"}");
		assertEquals("Kill 25 lizardman shamans", GoalProgress.compute(ca, new GoalProgress.Facts()).hint);
		GoalProgress.Goal bare = goal("{\"id\":\"b\",\"type\":\"combat_achievement\",\"params\":{\"task\":\"Master of Buckets\"}}");
		assertEquals("Updates when Nib Tracker sees it", GoalProgress.compute(bare, new GoalProgress.Facts()).hint);
	}

	@Test
	public void parsesMainGoalsAndParts()
	{
		GoalProgress.Goal main = goal("{\"id\":\"b\",\"type\":\"base_level\",\"params\":{\"level\":80},\"parts\":[3,23]}");
		assertEquals("", main.parent);
		assertEquals(3, main.partsDone);
		assertEquals(23, main.partsTotal);
		GoalProgress.Goal part = goal("{\"id\":\"s\",\"type\":\"skill_level\",\"params\":{\"skill\":\"Smithing\",\"level\":80},\"parent\":\"b\",\"parts\":\"x\"}");
		assertEquals("b", part.parent);
		assertEquals(0, part.partsTotal);
	}

	@Test
	public void shortTextForTheGameScreen()
	{
		assertEquals("73/80", GoalProgress.shortText("73 / 80", 0.5, false));
		assertEquals("34 left", GoalProgress.shortText("34 left", 0.6, false));
		assertEquals("53%", GoalProgress.shortText("1,234,567 / 13.0M", 0.53, false));
		assertEquals("40%", GoalProgress.shortText("", 0.4, false));
		assertEquals("Done", GoalProgress.shortText("73 / 80", 1, true));
	}

	@Test
	public void alreadyDoneAtLoginIsNotAnnounced()
	{
		Map<String, Boolean> wasDone = new HashMap<>();
		Set<String> announced = new HashSet<>();
		assertFalse(GoalProgress.justCompleted(wasDone, announced, "a", true));
		assertFalse(GoalProgress.justCompleted(wasDone, announced, "a", true));
		assertTrue(announced.isEmpty());
	}

	@Test
	public void finishingThisSessionIsAnnouncedOnce()
	{
		Map<String, Boolean> wasDone = new HashMap<>();
		Set<String> announced = new HashSet<>();
		assertFalse(GoalProgress.justCompleted(wasDone, announced, "a", false));
		assertTrue(GoalProgress.justCompleted(wasDone, announced, "a", true));
		assertFalse(GoalProgress.justCompleted(wasDone, announced, "a", true));
		// Dipping back below (a level drained, an item dropped) and finishing again doesn't announce it twice.
		assertFalse(GoalProgress.justCompleted(wasDone, announced, "a", false));
		assertFalse(GoalProgress.justCompleted(wasDone, announced, "a", true));
	}

	@Test
	public void serverDoneStaysDone()
	{
		GoalProgress.Goal g = goal("{\"id\":\"a\",\"type\":\"skill_level\",\"done\":true,\"params\":{\"skill\":\"Attack\",\"level\":99}}");
		GoalProgress.Facts f = new GoalProgress.Facts();
		f.xp.put("attack", 0L);
		f.levels.put("attack", 1);
		GoalProgress.Result r = GoalProgress.compute(g, f);
		assertTrue(r.done);
		assertEquals(1, r.progress, 0);
	}
}

