package com.nibtracker;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class OverlayBoxesTest
{
	private static GoalOverlay.Entry entry(String box, String title, boolean ready)
	{
		return new GoalOverlay.Entry(box, null, title, "1", "", -1, ready, null);
	}

	@Test
	public void boxesGroupByBoxInFirstSeenOrder()
	{
		GoalOverlay.Entry e1 = entry("A", "one", false);
		GoalOverlay.Entry e2 = entry("B", "two", false);
		GoalOverlay.Entry e3 = entry("A", "three", false);
		List<Map.Entry<String, List<GoalOverlay.Entry>>> boxes = GoalOverlay.boxes(Arrays.asList(e1, e2, e3));
		assertEquals(2, boxes.size());
		assertEquals("A", boxes.get(0).getKey());
		assertEquals(Arrays.asList(e1, e3), boxes.get(0).getValue());
		assertEquals("B", boxes.get(1).getKey());
		assertEquals(Collections.singletonList(e2), boxes.get(1).getValue());
		assertSame(e2, boxes.get(1).getValue().get(0));
	}

	@Test
	public void anOldGroupPinKeepsItsOwnBoxBesideItsTabsSinglePins()
	{
		GoalOverlay.Entry oldDailies = entry("legacy:dailies", "Daily tasks", false);
		GoalOverlay.Entry oneDaily = entry("Daily tasks", "Herb run", true);
		GoalOverlay.Entry oldFarming = entry("legacy:farming", "Farming", true);
		GoalOverlay.Entry onePatch = entry("Farming", "Ranarr", true);
		GoalOverlay.Entry oldHerbs = entry("legacy:farming:Herbs", "Herbs", true);
		GoalOverlay.Entry herbKind = entry("Herbs", "Herbs", true);
		List<Map.Entry<String, List<GoalOverlay.Entry>>> boxes = GoalOverlay.boxes(
			Arrays.asList(oldDailies, oneDaily, oldFarming, onePatch, oldHerbs, herbKind));
		assertEquals(6, boxes.size());
		for (Map.Entry<String, List<GoalOverlay.Entry>> b : boxes)
		{
			assertEquals(1, b.getValue().size());
			// One entry: no title line, so the legacy key never shows and old pins look as before.
			assertNull(GoalOverlay.heading(b.getKey(), b.getValue()));
		}
	}

	@Test
	public void noEntriesNoBoxes()
	{
		assertTrue(GoalOverlay.boxes(Collections.emptyList()).isEmpty());
	}

	@Test
	public void headingCarriesTheReadyOrDueCount()
	{
		assertEquals("Farming · 2 ready", GoalOverlay.heading("Farming",
			Arrays.asList(entry("Farming", "a", true), entry("Farming", "b", true), entry("Farming", "c", false))));
		assertEquals("Daily tasks · 1 due", GoalOverlay.heading("Daily tasks",
			Arrays.asList(entry("Daily tasks", "a", true), entry("Daily tasks", "b", false))));
		assertEquals("Skills", GoalOverlay.heading("Skills",
			Arrays.asList(entry("Skills", "a", false), entry("Skills", "b", false))));
	}

	@Test
	public void aSinglePinIsAOneLineBoxButAFavouritesListKeepsItsTitle()
	{
		assertNull(GoalOverlay.heading("Farming", Collections.singletonList(entry("Farming", "Ranarr", true))));
		assertEquals("★ Farming favourites · 1 ready", GoalOverlay.heading("★ Farming favourites",
			Collections.singletonList(entry("★ Farming favourites", "Ranarr", true))));
	}

	private static Routines.Patch patch(String region, String name)
	{
		return new Routines.Patch(region, name, "herb", "Ranarr", 0, 0, true);
	}

	@Test
	public void regionPinShowsOnlyThatRegion()
	{
		List<Routines.Patch> farm = Arrays.asList(patch("Farming Guild", "Herb"), patch("Catherby", "Herb"), patch("Farming Guild", "Tree"));
		Map<String, List<Routines.Patch>> shown = GoalTracker.pinnedRegions(
			Collections.singleton(Favourites.regionPin("Farming Guild")), farm);
		assertEquals(1, shown.size());
		assertEquals(Arrays.asList(farm.get(0), farm.get(2)), shown.get("Farming Guild"));
		assertTrue(GoalTracker.pinnedRegions(Collections.singleton(Favourites.regionPin("Falador")), farm).isEmpty());
	}
}

package com.nibtracker;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class PatchPredictorTest
{
	private static final PatchPredictor TT = PatchPredictor.load(new Gson());
	/* A farming tick boundary (20 minutes), in unix seconds. */
	private static final long T = 1_441_333L * 1200;
	private static final long HOUR = 60 * 60 * 1000L;

	private static List<Routines.Patch> predict(String key, String value, long nowMs)
	{
		Map<String, String> e = new HashMap<>();
		e.put(key, value);
		return TT.predict(e, nowMs);
	}

	@Test
	public void herbGrowingThenReady()
	{
		// HERB 32..35 is Ranarr growing (stage = value - 32); Ranarr grows every 20 minutes over 5 stages.
		List<Routines.Patch> at = predict("11062.4774", "32:" + T, T * 1000);
		assertEquals(1, at.size());
		Routines.Patch p = at.get(0);
		assertEquals("Catherby", p.region);
		assertEquals("", p.name);
		assertEquals("Herb", p.type);
		assertEquals("Ranarr", p.crop);
		assertEquals(257, p.itemId);
		assertEquals("growing", p.state);
		assertFalse(p.ready);
		assertTrue(p.readyAt > T * 1000);
		assertEquals((T + 80 * 60) * 1000, p.readyAt);
		assertEquals(0, p.progress, 0);
		assertEquals("herb", p.kind);
		assertEquals("Herbs", p.kindLabel);
		assertEquals("herb", p.run);
		assertEquals("Catherby||herb", p.id());

		Routines.Patch later = predict("11062.4774", "32:" + T, T * 1000 + 2 * HOUR).get(0);
		assertEquals("ready", later.state);
		assertTrue(later.ready);
		assertEquals(1, later.progress, 0);
	}

	@Test
	public void farmingGuildSpiritTreeIsLeftOut()
	{
		assertTrue(predict("4922.4771", "20:" + T, T * 1000).isEmpty());
	}

	@Test
	public void weedsAreEmpty()
	{
		Routines.Patch p = predict("11062.4774", "3:" + T, T * 1000).get(0);
		assertEquals("empty", p.state);
		assertEquals("Weeds", p.crop);
		assertEquals(0, p.itemId);
		assertFalse(p.ready);
	}

	@Test
	public void idMatchesFeed()
	{
		Routines.Patch p = predict("4922.7910", "8:" + T, T * 1000).get(0);
		assertEquals("Farming Guild||celastrus", p.id());
		assertEquals("Celastrus", p.type);
		assertEquals("Celastrus", p.kindLabel);
	}

	@Test
	public void unknownPatchOrValueIsSkipped()
	{
		Map<String, String> e = new HashMap<>();
		e.put("99999.1", "32:" + T);
		e.put("11062.4774", "220:" + T); // no HERB range has 220
		e.put("11062.4773", "junk");
		e.put("farmTickOffset", "x");
		assertTrue(TT.predict(e, T * 1000).isEmpty());
	}

	@Test
	public void seededBirdHouseIsReadyAfterFiftyMinutes()
	{
		// 6 is an oak bird house (values 4..6), seeded (a multiple of 3).
		Routines.Patch p = predict("birdhouse.1626", "6:" + T, T * 1000).get(0);
		assertEquals("Fossil Island|Mushroom Meadow (North)|birdhouse", p.id());
		assertEquals("Oak Bird House", p.crop);
		assertEquals("growing", p.state);
		assertEquals((T + 50 * 60) * 1000, p.readyAt);
		assertEquals("ready", predict("birdhouse.1626", "6:" + T, T * 1000 + HOUR).get(0).state);
		// Built but not seeded counts as empty, and the feed leaves those out.
		assertTrue(predict("birdhouse.1626", "5:" + T, T * 1000).isEmpty());
	}

	@Test
	public void tickOffsetMovesTheReadyTime()
	{
		Map<String, String> e = new HashMap<>();
		e.put("11062.4774", "32:" + T);
		e.put("farmTickOffset", "5");
		e.put("farmTickOffsetPrecision", "40");
		// With a 5 minute offset the ticks fall 5 minutes earlier: T - 5 min is the boundary, ready 4 ticks later.
		assertEquals((T - 5 * 60 + 80 * 60) * 1000, TT.predict(e, T * 1000).get(0).readyAt);
	}

	private static PatchPredictor.SpiritTree spirit(List<PatchPredictor.SpiritTree> trees, String region)
	{
		for (PatchPredictor.SpiritTree t : trees)
		{
			if (region.equals(t.region))
			{
				return t;
			}
		}
		throw new AssertionError("no spirit tree spot " + region);
	}

	@Test
	public void spiritTreesEveryStateAndSpot()
	{
		Map<String, String> e = new HashMap<>();
		e.put("12082.4771", "3:" + T); // Port Sarim: weeds
		e.put("11058.4772", "20:" + T); // Brimhaven: grown
		e.put("10300.4772", "10:" + T); // Etceteria: growing, stage 2 of 12
		e.put("6967.7904", "25:" + T); // Kourend (Hosidius): diseased
		List<PatchPredictor.SpiritTree> trees = TT.spiritTrees(e, T * 1000);
		assertEquals(5, trees.size());
		assertEquals("Not planted", spirit(trees, "Port Sarim").state);
		assertEquals("Grown", spirit(trees, "Brimhaven").state);
		assertEquals(1, spirit(trees, "Brimhaven").progress, 0);
		PatchPredictor.SpiritTree growing = spirit(trees, "Etceteria");
		assertEquals("Growing", growing.state);
		assertEquals(2 / 12.0, growing.progress, 1e-9);
		assertEquals("Diseased", spirit(trees, "Hosidius").state);
		assertEquals("Unknown", spirit(trees, "Farming Guild").state);
		assertEquals(-1, spirit(trees, "Farming Guild").progress, 0);

		// Spirit trees grow every 320 minutes; ten more ticks and it's grown.
		long later = (T + 10 * 320 * 60) * 1000;
		assertEquals("Grown", spirit(TT.spiritTrees(e, later), "Etceteria").state);
		assertEquals("Growing", spirit(TT.spiritTrees(e, later - 320 * 60 * 1000L), "Etceteria").state);
	}

	@Test
	public void spiritTreeDeadAndLateGrownStage()
	{
		Map<String, String> e = new HashMap<>();
		e.put("4922.4771", "35:" + T);
		e.put("11058.4772", "44:" + T);
		List<PatchPredictor.SpiritTree> trees = TT.spiritTrees(e, T * 1000);
		assertEquals("Dead", spirit(trees, "Farming Guild").state);
		assertEquals("Grown", spirit(trees, "Brimhaven").state);
	}
}

package com.nibtracker;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.google.gson.JsonParser;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

public class RoutinesTest
{
	private static final long NOON = 20_000 * Routines.DAY + 12 * 60 * Routines.MINUTE;

	@Test
	public void readsDailiesAndPatchesAndSkipsJunk()
	{
		List<Routines.Daily> d = Routines.dailies(new JsonParser().parse(
			"[{\"id\":\"a\",\"label\":\"Battlestaves\",\"cadence\":\"daily\",\"every\":1,\"dueAt\":5}, {\"id\":\"\"}, 3]"));
		assertEquals(1, d.size());
		assertEquals(5, d.get(0).dueAt);
		List<Routines.Patch> f = Routines.farm(new JsonParser().parse(
			"[{\"region\":\"Catherby\",\"type\":\"Herb\",\"crop\":\"Ranarr\",\"itemId\":257,\"readyAt\":100,\"ready\":false}, {\"crop\":\"x\"}]"));
		assertEquals(1, f.size());
		assertEquals(257, f.get(0).itemId);
		assertTrue(Routines.dailies(null).isEmpty());
	}

	@Test
	public void readsKeyItemIdAndCondition()
	{
		List<Routines.Daily> d = Routines.dailies(new JsonParser().parse(
			"[{\"id\":\"m\",\"key\":\"miscellania\",\"label\":\"Miscellania\",\"cadence\":\"condition\",\"every\":1,\"due\":true,\"itemId\":8150},"
				+ "{\"id\":\"z\",\"label\":\"Zaff\",\"cadence\":\"daily\",\"dueAt\":5}]"));
		Routines.Daily m = d.get(0);
		assertEquals("miscellania", m.key);
		assertEquals(8150, m.itemId);
		assertEquals("condition", m.cadence);
		assertEquals(Boolean.TRUE, m.due);
		Routines.Daily z = d.get(1);
		assertEquals("", z.key);
		assertEquals(0, z.itemId);
		assertEquals(null, z.due);
	}

	@Test
	public void feedWithoutStateIsGrowingOrReady()
	{
		List<Routines.Patch> f = Routines.farm(new JsonParser().parse(
			"[{\"region\":\"Catherby\",\"crop\":\"Ranarr\",\"ready\":true},{\"region\":\"Ardougne\",\"crop\":\"Guam\"}]"));
		assertEquals("ready", f.get(0).state);
		assertEquals("growing", f.get(1).state);
		assertEquals(-1, f.get(1).progress, 0);
	}

	@Test
	public void readsStateProgressAndId()
	{
		Routines.Patch p = Routines.farm(new JsonParser().parse(
			"[{\"region\":\"Farming Guild\",\"name\":\"\",\"kind\":\"anima\",\"state\":\"diseased\",\"progress\":0.5}]")).get(0);
		assertEquals("diseased", p.state);
		assertEquals(0.5, p.progress, 0);
		assertTrue(p.needsAttention());
		assertEquals("Farming Guild||anima", p.id());
		assertFalse(p.readyAt(Long.MAX_VALUE)); // no readyAt, not ready
	}

	@Test
	public void nextDueFollowsTheCadence()
	{
		Routines.Daily daily = new Routines.Daily("a", "x", "daily", 1, 0);
		assertEquals(20_001 * Routines.DAY, Routines.nextDue(daily, NOON));
		Routines.Daily tears = new Routines.Daily("b", "Tears of Guthix", "rolling_days", 7, 0);
		assertEquals(20_007 * Routines.DAY, Routines.nextDue(tears, NOON));
		Routines.Daily timer = new Routines.Daily("c", "x", "interval_min", 90, 0);
		assertEquals(NOON + 90 * Routines.MINUTE, Routines.nextDue(timer, NOON));
	}

	@Test
	public void shortTimesAndRegionSummaries()
	{
		assertEquals("1m", Routines.left(20_000));
		assertEquals("34m", Routines.left(34 * Routines.MINUTE));
		assertEquals("5h 12m", Routines.left(312 * Routines.MINUTE));
		assertEquals("2d 3h", Routines.left(51 * 60 * Routines.MINUTE));
		Routines.Patch ready = new Routines.Patch("Catherby", "", "Herb", "Ranarr", 0, NOON - 1, false);
		Routines.Patch later = new Routines.Patch("Catherby", "", "Allotment", "Potato", 0, NOON + 34 * Routines.MINUTE, false);
		assertTrue(ready.readyAt(NOON));
		assertFalse(later.readyAt(NOON));
		assertEquals("1 ready", Routines.summary(Arrays.asList(ready, later), NOON));
		assertEquals("next 34m", Routines.summary(Arrays.asList(later), NOON));
	}

	@Test
	public void routeStopsWithTheirTeleportsBestFirst()
	{
		List<Routines.Stop> r = Routines.route(new JsonParser().parse(
			"[{\"stop\":1,\"place\":\"Ardougne\",\"teles\":[{\"travel\":\"Ardougne cloak 2\",\"cat\":\"ITEM\",\"item\":\"Ardougne cloak 2\"},{\"travel\":\"Ardougne Teleport\",\"cat\":\"SPELLBOOK\"}]},"
				+ "{\"stop\":0,\"place\":\"Nowhere\"},{\"stop\":2,\"place\":\"\"}]"));
		assertEquals(1, r.size());
		assertEquals("Ardougne", r.get(0).place);
		assertEquals(Arrays.asList("Ardougne cloak 2", "Ardougne Teleport"), Arrays.asList(r.get(0).teles.get(0).travel, r.get(0).teles.get(1).travel));
		assertEquals("", r.get(0).teles.get(1).item);
		assertTrue(Routines.route(null).isEmpty());
	}

	@Test
	public void bingoBoardsKeepOnlyWhatFits()
	{
		List<Routines.Board> b = Routines.bingo(new JsonParser().parse(
			"[{\"id\":\"a\",\"name\":\"Clan bingo\",\"size\":3,\"tiles\":["
				+ "{\"idx\":0,\"label\":\"Tanzanite fang\",\"itemId\":12922,\"done\":true},"
				+ "{\"idx\":4,\"label\":\"80 Slayer\",\"skill\":\"Slayer\"},"
				+ "{\"idx\":9,\"label\":\"Off the board\"},{\"label\":\"No idx\"}]},"
				+ "{\"name\":\"Too big\",\"size\":6},{\"name\":\"\",\"size\":4}]"));
		assertEquals(1, b.size());
		assertEquals(9, b.get(0).tiles.length);
		assertEquals("Tanzanite fang", b.get(0).tiles[0].label);
		assertTrue(b.get(0).tiles[0].done);
		assertEquals("Slayer", b.get(0).tiles[4].skill);
		assertFalse(b.get(0).tiles[4].done);
		// Empty slots, a tile past the board and one with no idx are left out.
		assertEquals(null, b.get(0).tiles[1]);
		assertEquals(2, java.util.Arrays.stream(b.get(0).tiles).filter(java.util.Objects::nonNull).count());
		assertEquals("a", b.get(0).id);
		// An id that isn't plain is dropped, as it goes into a link.
		assertEquals("", Routines.bingo(new JsonParser().parse("[{\"id\":\"x/../y\",\"name\":\"B\",\"size\":3}]")).get(0).id);
		assertTrue(Routines.bingo(null).isEmpty());
	}
}

package com.nibtracker;

import com.google.gson.JsonParser;
import java.util.Arrays;
import java.util.HashSet;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** What the plugin takes from the server's settings: container ids to watch, the bank's tabs, and a notice code. */
public class ServerWatchTest
{
	@Test
	public void aNoticeIsOnlyOneOfThePluginsOwn()
	{
		assertTrue(GoalTracker.noticeText(new JsonParser().parse("\"update\"")).contains("Plugin Hub"));
		assertTrue(GoalTracker.noticeText(new JsonParser().parse("\"news\"")).contains("Open it"));
		// Free text, an unknown code, or none at all shows nothing.
		assertEquals("", GoalTracker.noticeText(new JsonParser().parse("\"Visit evil.example for free gold\"")));
		assertEquals("", GoalTracker.noticeText(new JsonParser().parse("{\"code\":\"update\"}")));
		assertEquals("", GoalTracker.noticeText(null));
	}

	@Test
	public void containerIdsAreCheckedAndCapped()
	{
		assertEquals(new HashSet<>(Arrays.asList(516, 93)), ProgressTracker.watchIds(
			new JsonParser().parse("{\"watch\":{\"containers\":[516, -1, 70000, \"x\", 93]}}").getAsJsonObject(), "containers", 65536, 50));
		assertEquals(2, ProgressTracker.watchIds(
			new JsonParser().parse("{\"watch\":{\"containers\":[1, 2, 3]}}").getAsJsonObject(), "containers", 65536, 2).size());
		assertTrue(ProgressTracker.watchIds(new JsonParser().parse("{}").getAsJsonObject(), "containers", 65536, 50).isEmpty());
	}

	@Test
	public void bankSlotsFallInTheirTabs()
	{
		int[] tabs = {2, 0, 3};
		assertEquals(1, ContainerTracker.bankTab(0, tabs));
		assertEquals(1, ContainerTracker.bankTab(1, tabs));
		assertEquals(3, ContainerTracker.bankTab(2, tabs)); // tab 2 is empty
		assertEquals(3, ContainerTracker.bankTab(4, tabs));
		assertEquals(0, ContainerTracker.bankTab(5, tabs)); // the main tab comes after them
	}

	@Test
	public void theServerCanOnlyAskForThePlayersOwnStorage()
	{
		assertTrue(ContainerTracker.OWN_STORAGE.contains(net.runelite.api.gameval.InventoryID.LOOTING_BAG));
		// A trade window (the player's offer, or the other player's at 90 + 32768) or a shop is never sent.
		assertFalse(ContainerTracker.OWN_STORAGE.contains(net.runelite.api.gameval.InventoryID.TRADEOFFER));
		assertFalse(ContainerTracker.OWN_STORAGE.contains(net.runelite.api.gameval.InventoryID.TRADEOFFER + 32768));
		assertFalse(ContainerTracker.OWN_STORAGE.contains(net.runelite.api.gameval.InventoryID.SHIPYARD_SHOP));
	}
}

package com.nibtracker;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;

public class SlayerTaskIconsTest
{
	@Test
	public void namesAreLowerCaseWithoutThe() throws Exception
	{
		try (Reader r = new InputStreamReader(GoalTracker.class.getResourceAsStream("slayer_tasks.json"), StandardCharsets.UTF_8))
		{
			JsonObject icons = new Gson().fromJson(r, JsonObject.class);
			assertEquals(8139, icons.get("kalphites").getAsInt());
			assertEquals(13262, icons.get("abyssal sire").getAsInt());
			icons.keySet().forEach(k -> assertFalse(k, k.startsWith("the ") || !k.equals(k.toLowerCase())));
		}
	}
}
